function mdo = opf_case74ds(gen_QMIN_13, bus_VMAX_44)
%OPF_CASE74DS Multi-period DC OPF (MOST) for case74ds with scenario-driven parameter updates

define_constants;

%% load base case
casefile = 'case74ds';
mpc0 = loadcase(casefile);

%% scenario-driven parameter modifications with direction validation
% 1) Generator at bus 13: QMIN increases (i.e., becomes >= original QMIN)
idx_g13 = find(mpc0.gen(:, GEN_BUS) == 13);
assert(~isempty(idx_g13), 'No generator found at bus 13');
% if multiple gens at bus 13, apply to all to respect scenario direction
for k = 1:numel(idx_g13)
    g = idx_g13(k);
    qmin0 = mpc0.gen(g, QMIN);
    assert(gen_QMIN_13 >= qmin0, 'Parameter must increase');
end

% 2) Bus 44: VMAX increases
b44 = find(mpc0.bus(:, BUS_I) == 44);
assert(~isempty(b44) && numel(b44) == 1, 'Bus 44 not found or not unique');
vmax0_44 = mpc0.bus(b44, VMAX);
assert(bus_VMAX_44 >= vmax0_44, 'Parameter must increase');

%% apply modifications
mpc = mpc0;
for k = 1:numel(idx_g13)
    g = idx_g13(k);
    mpc.gen(g, QMIN) = gen_QMIN_13;
end
mpc.bus(b44, VMAX) = bus_VMAX_44;

%% MOST multi-period DC OPF setup (template-aligned)
% DC model
mpopt = mpoption('most.dc_model', 1, ...
                 'opf.violation', 1e-6);

% NOTE: This template expects external xGen and profile data. To keep this
% function self-contained while still implementing the multi-period MOST
% structure, we build a minimal deterministic multi-period data set with a
% flat profile (no structural scenario changes beyond the specified limits).
% Users can replace the profiles and xgd with their own datasets.

nt = 2; % placeholder number of periods for multi-period formulation

% create simple load profiles (identity scaling)
% MOST profiles are specified via md.profile entries; we keep loads constant.
profiles = struct([]);
profiles(1).type = 'mpcData';
profiles(1).table = CT_TBUS;
profiles(1).rows = (1:size(mpc.bus,1))';
profiles(1).col = PD;
profiles(1).chgtype = CT_REP;
profiles(1).values = repmat(mpc.bus(:, PD), 1, nt);

profiles(2).type = 'mpcData';
profiles(2).table = CT_TBUS;
profiles(2).rows = (1:size(mpc.bus,1))';
profiles(2).col = QD;
profiles(2).chgtype = CT_REP;
profiles(2).values = repmat(mpc.bus(:, QD), 1, nt);

% xGen data: empty (no additional flexible resources)
xgd = [];

% build MOST data model
mdi = loadmd(mpc, nt, xgd, [], [], profiles);

% run MOST
mdo = most(mdi, mpopt);

% optional: expose commonly used outputs to caller via returned mdo
% ExpectedDispatch = mdo.results.ExpectedDispatch;
% GenPrices        = mdo.results.GenPrices;

end

function results = opf_case141(bus_PD_44, bus_QD_137, branch_TAP_63_42)
%OPF_CASE141  DC-SCOPF for case141 with angle-difference penalty and scenario parameter edits.
%
% Inputs (placeholders representing post-modification values):
%   bus_PD_44          - new PD at bus 44 (must Increase)
%   bus_QD_137         - new QD at bus 137 (must Increase)
%   branch_TAP_63_42   - new TAP for branch 63->42 (must Increase)
%
% Output:
%   results - MATPOWER results struct (external indexing)

define_constants;

%% load case
mpc0 = loadcase('case141');
if isempty(mpc0)
    error('Failed to load case141');
end

%% ===== scenario-driven parameter modifications (with direction asserts) =====
% bus 44 PD increase
b44 = find(mpc0.bus(:, BUS_I) == 44, 1);
assert(~isempty(b44), 'Bus 44 not found');
PD_old_44 = mpc0.bus(b44, PD);
assert(bus_PD_44 >= PD_old_44, 'Parameter must increase');
mpc0.bus(b44, PD) = bus_PD_44;

% bus 137 QD increase
b137 = find(mpc0.bus(:, BUS_I) == 137, 1);
assert(~isempty(b137), 'Bus 137 not found');
QD_old_137 = mpc0.bus(b137, QD);
assert(bus_QD_137 >= QD_old_137, 'Parameter must increase');
mpc0.bus(b137, QD) = bus_QD_137;

% branch 63-42 TAP increase (handle either orientation by matching both ends)
br6342 = find(mpc0.branch(:, F_BUS) == 63 & mpc0.branch(:, T_BUS) == 42, 1);
assert(~isempty(br6342), 'Branch 63->42 not found');
TAP_old_63_42 = mpc0.branch(br6342, TAP);
% MATPOWER convention: TAP = 0 means 1.0; compare against effective tap
if TAP_old_63_42 == 0
    TAP_eff_old = 1.0;
else
    TAP_eff_old = TAP_old_63_42;
end
assert(branch_TAP_63_42 >= TAP_eff_old, 'Parameter must increase');
% write new tap; allow user to pass 1.0+; do not encode as 0
mpc0.branch(br6342, TAP) = branch_TAP_63_42;

%% ===== solver / model options =====
SOLVER = 'MIPS';
mpopt = mpoption('verbose', 1, 'out.all', 0);
mpopt = mpoption(mpopt, 'model', 'DC');
mpopt = mpoption(mpopt, 'opf.dc.solver', SOLVER);
mpopt = mpoption(mpopt, 'opf.violation', 1e-8);

%% ===== build DC-SCOPF model (internal indexing) =====
mpc = ext2int(mpc0);
baseMVA = mpc.baseMVA;
bus    = mpc.bus;
branch = mpc.branch;

nb = size(bus, 1);
nl = size(branch, 1);

% DC network matrices
[~, Bf, ~, Pfinj] = makeBdc(baseMVA, bus, branch);
PTDF = makePTDF(baseMVA, bus, branch);
LODF = makeLODF(branch, PTDF);

% contingency set: in-service branches with RATE_A > 0
in_service = (branch(:, BR_STATUS) == 1);
has_limit  = (branch(:, RATE_A) > 0);
cont_set   = find(in_service & has_limit);
nc = length(cont_set);
if isempty(cont_set)
    error('Contingency set is empty! No in-service lines with RATE_A limits.');
end

% set up OPF model
om = opf_setup(mpc, mpopt);
nv = om.var.N;

iVa1 = om.var.idx.i1.Va;
iVaN = om.var.idx.iN.Va;

%% ===== objective modification: angle-difference quadratic penalty =====
% beta * ||E*Va||^2 = beta * Va' * (E'*E) * Va
% MATPOWER quad cost uses 0.5*x'*Q*x, so Q = 2*beta*(E'*E)
beta = 10;

% build incidence E only for in-service branches to reflect operating network
br_in = find(in_service);
nl_in = length(br_in);
f = branch(br_in, F_BUS);
t = branch(br_in, T_BUS);

E = sparse(1:nl_in, f,  1, nl_in, nb) + sparse(1:nl_in, t, -1, nl_in, nb);
Q_va = 2 * beta * (E' * E);
om = om.add_quad_cost('ang_diff_pen', Q_va, [], 0, {'Va'});

%% ===== constraint modification: N-1 branch thermal limits (DC-SCOPF) =====
rateA = branch(:, RATE_A);
constrain_lines = find(in_service & has_limit);
nL = length(constrain_lines);

nRows = 2 * nL * nc;
A = spalloc(nRows, nv, max(1, 2 * nL * nc * min(nb, 20))); % conservative sparsity guess
l = -inf(nRows, 1);
u =  inf(nRows, 1);

row = 0;
for kk = 1:nc
    k = cont_set(kk);

    lodf_col = LODF(:, k);   % nl x 1
    Bf_row_k = Bf(k, :);     % 1 x nb
    Pk       = Pfinj(k);     % scalar

    % post-contingency flow mapping
    Bf_k = Bf + lodf_col * Bf_row_k;  % nl x nb
    Pf_k = Pfinj + lodf_col * Pk;     % nl x 1

    for ii = 1:nL
        ell = constrain_lines(ii);
        limit = rateA(ell);

        aVa = Bf_k(ell, :);
        cst = Pf_k(ell);

        % f_ell^(k) <= limit
        row = row + 1;
        A(row, iVa1:iVaN) = aVa;
        u(row) = limit - cst;

        % -f_ell^(k) <= limit  <=> f_ell^(k) >= -limit
        row = row + 1;
        A(row, iVa1:iVaN) = -aVa;
        u(row) = limit + cst;
    end
end

if row ~= nRows
    error('Row count mismatch: row=%d, expected nRows=%d', row, nRows);
end

om.add_lin_constraint('N1_branch_limits', A, l, u);

%% ===== solve =====
[x, fval, eflag, output, lambda] = om.solve();
if eflag <= 0
    error('OPF solver failed with exit flag: %d', eflag);
end

%% ===== pack results (back to external indexing) =====
idx_i1 = om.var.idx.i1;
idx_iN = om.var.idx.iN;

Va_solution = x(idx_i1.Va:idx_iN.Va);
Pg_solution = x(idx_i1.Pg:idx_iN.Pg);

results = mpc;
results.bus(:, VA) = Va_solution * 180/pi;
results.gen(:, PG) = Pg_solution;
results.f = fval;
results.success = (eflag > 0);
results.eflag = eflag;
results.output = output;
results.lambda = lambda;

results = int2ext(results);

end

function results = opf_case22(bus_VMIN_3, bus_PD_13, bus_QD_13)
%OPF_CASE22  Level-4 DC-SCOPF for case22 with scenario parameter changes and objective modification.

define_constants;

%% ===== Load case and options =====
mpc0 = loadcase('case22');
if isempty(mpc0)
    error('Failed to load case22');
end

mpopt = mpoption('verbose', 1, 'out.all', 0);
mpopt = mpoption(mpopt, 'model', 'DC');
mpopt = mpoption(mpopt, 'opf.dc.solver', 'MIPS');
mpopt = mpoption(mpopt, 'opf.violation', 1e-8);

%% ===== Scenario-driven parameter modifications (with direction asserts) =====
% Bus 3: VMIN set to zero (disable lower voltage limit for feasibility assessment)
old_VMIN_3 = mpc0.bus(3, VMIN);
assert(bus_VMIN_3 == 0, 'Parameter must be set to zero');
mpc0.bus(3, VMIN) = bus_VMIN_3;

% Bus 13: PD increased
old_PD_13 = mpc0.bus(13, PD);
assert(bus_PD_13 >= old_PD_13, 'Parameter must increase');
mpc0.bus(13, PD) = bus_PD_13;

% Bus 13: QD increased
old_QD_13 = mpc0.bus(13, QD);
assert(bus_QD_13 >= old_QD_13, 'Parameter must increase');
mpc0.bus(13, QD) = bus_QD_13;

%% ===== Convert to internal indexing =====
mpc = ext2int(mpc0);
baseMVA = mpc.baseMVA;
bus    = mpc.bus;
branch = mpc.branch;

nb = size(bus, 1);
nl = size(branch, 1);

%% ===== Build PTDF/LODF for N-1 security constraints =====
% Bf: nl x nb, Pfinj: nl x 1
[~, Bf, ~, Pfinj] = makeBdc(baseMVA, bus, branch);
PTDF = makePTDF(baseMVA, bus, branch);
LODF = makeLODF(branch, PTDF);

in_service = (branch(:, BR_STATUS) == 1);
has_limit  = (branch(:, RATE_A) > 0);
cont_set   = find(in_service & has_limit);
nc = length(cont_set);

if isempty(cont_set)
    error('Contingency set is empty! No in-service lines with RATE_A > 0.');
end

%% ===== OPF model setup =====
om = opf_setup(mpc, mpopt);

idx_i1 = om.var.idx.i1;
idx_iN = om.var.idx.iN;

iVa1 = idx_i1.Va;
iVaN = idx_iN.Va;

nv = om.var.N;

%% ===== Add N-1 branch flow limit constraints =====
rateA = branch(:, RATE_A);
constrain_lines = find(in_service & has_limit);
nL = length(constrain_lines);

nRows = 2 * nL * nc;

% Each row touches only Va vars; allocate conservatively.
A = spalloc(nRows, nv, nRows * min(nb, 50));
l = -inf(nRows, 1);
u =  inf(nRows, 1);

row = 0;
for kk = 1:nc
    k = cont_set(kk);

    lodf_col = LODF(:, k);      % nl x 1
    Bf_row_k = Bf(k, :);        % 1 x nb
    Pk       = Pfinj(k);        % scalar

    % Post-contingency flow mapping
    Bf_k = Bf + lodf_col * Bf_row_k;   % nl x nb
    Pf_k = Pfinj + lodf_col * Pk;      % nl x 1

    for ii = 1:nL
        ell = constrain_lines(ii);
        limit = rateA(ell);

        aVa = Bf_k(ell, :);   % 1 x nb
        cst = Pf_k(ell);      % scalar

        % Upper:  aVa*Va <= limit - cst
        row = row + 1;
        A(row, iVa1:iVaN) = aVa;
        u(row) = limit - cst;

        % Lower: -aVa*Va <= limit + cst
        row = row + 1;
        A(row, iVa1:iVaN) = -aVa;
        u(row) = limit + cst;
    end
end

if row ~= nRows
    error('Row count mismatch: row=%d, expected nRows=%d', row, nRows);
end

om.add_lin_constraint('N1_branch_limits', A, l, u);

%% ===== Add quadratic reactive power generation cost: sum(c_Q .* Qg.^2) =====
% Note: This cost is added to the underlying (DC) model objective as a
% quadratic penalty on Qg variables.
ng = idx_iN.Pg - idx_i1.Pg + 1;

% If the case has Qg variables in the model indexing, apply cost; otherwise error.
if ~isfield(idx_i1, 'Qg') || ~isfield(idx_iN, 'Qg')
    error('Qg variables are not present in the OPF model; cannot add reactive power cost.');
end

nQg = idx_iN.Qg - idx_i1.Qg + 1;
if nQg ~= ng
    % This can happen for unusual cases; still proceed on Qg dimension.
end

% Use placeholder coefficients sized to number of generators if needed.
% For a fully specified implementation, user should align c_Q length to number of gens.
% Here we map/expand the template coefficients deterministically.
c_Q_template = [100; 15; 20];
if length(c_Q_template) == nQg
    c_Q = c_Q_template;
else
    c_Q = c_Q_template(mod((1:nQg)'-1, length(c_Q_template)) + 1);
end

Q_mat = sparse(1:nQg, 1:nQg, 2*c_Q, nQg, nQg);
om = om.add_quad_cost('reactive_power_generation_cost', Q_mat, [], 0, {'Qg'});

%% ===== Solve =====
[x, f, eflag, output, lambda] = om.solve();
if eflag <= 0
    error('OPF solver failed with exit flag: %d', eflag);
end

%% ===== Pack results back into a MATPOWER results struct =====
results = mpc;

Va_solution = x(idx_i1.Va:idx_iN.Va);
Pg_solution = x(idx_i1.Pg:idx_iN.Pg);
Qg_solution = x(idx_i1.Qg:idx_iN.Qg);

results.bus(:, VA) = Va_solution * 180/pi;
results.gen(:, PG) = Pg_solution;
results.gen(:, QG) = Qg_solution;
results.f = f;
results.success = (eflag > 0);
results.eflag = eflag;
results.output = output;
results.lambda = lambda;

results = int2ext(results);

end

function out = opf_case85(gen_COST_PARAMS_C1_10, gen_COST_PARAMS_C2_8, gen_COST_PARAMS_C3_2, branch_BR_B_31_73, w_bus_ext, mu_w_MW, sigma_w_MW, eps)
%OPF_CASE85 Multi-period DCOPF (MOST) with chance-constrained line limits + scenario parameter edits
%   Inputs are placeholders representing post-modification values consistent
%   with scenario directions.

define_constants;

casefile = 'case85';
mpc0 = loadcase(casefile);

%% ---------------- scenario-driven parameter modifications ----------------
% 1) Nuclear units prioritized: decrease selected generator cost coefficients
% We interpret COST_PARAMS_Ck as polynomial cost coefficients in gencost.
% For MODEL=2 (polynomial), columns are: [MODEL STARTUP SHUTDOWN NCOST c(n-1) ... c0]
% Here we map:
%   C2 := quadratic coefficient, C1 := linear coefficient, C0 := constant coefficient.

mpc = mpc0;

% helper to find generator row by GEN_BUS (first match)
find_gen_by_bus = @(busno) find(mpc.gen(:, GEN_BUS) == busno, 1, 'first');

% --- bus 10: decrease linear term (C1)
gi10 = find_gen_by_bus(10);
if isempty(gi10), error('No generator found at bus 10.'); end
if size(mpc.gencost, 1) < gi10, error('gencost rows do not align with gen rows.'); end
if mpc.gencost(gi10, MODEL) ~= 2
    error('This template expects polynomial gencost (MODEL=2) for generator at bus 10.');
end
ncost10 = mpc.gencost(gi10, NCOST);
assert(ncost10 >= 2, 'Generator at bus 10 must have at least 2 cost coefficients to modify C1.');
% column index of linear coefficient in polynomial form
col_c1_10 = 4 + (ncost10 - 2);
old_c1_10 = mpc.gencost(gi10, col_c1_10);
new_c1_10 = gen_COST_PARAMS_C1_10;
assert(new_c1_10 <= old_c1_10, 'Parameter must decrease');
mpc.gencost(gi10, col_c1_10) = new_c1_10;

% --- bus 8: decrease quadratic term (C2)
gi8 = find_gen_by_bus(8);
if isempty(gi8), error('No generator found at bus 8.'); end
if mpc.gencost(gi8, MODEL) ~= 2
    error('This template expects polynomial gencost (MODEL=2) for generator at bus 8.');
end
ncost8 = mpc.gencost(gi8, NCOST);
assert(ncost8 >= 3, 'Generator at bus 8 must have at least 3 cost coefficients to modify C2.');
col_c2_8 = 4 + (ncost8 - 3);
old_c2_8 = mpc.gencost(gi8, col_c2_8);
new_c2_8 = gen_COST_PARAMS_C2_8;
assert(new_c2_8 <= old_c2_8, 'Parameter must decrease');
mpc.gencost(gi8, col_c2_8) = new_c2_8;

% --- bus 2: decrease constant term (C0)
gi2 = find_gen_by_bus(2);
if isempty(gi2), error('No generator found at bus 2.'); end
if mpc.gencost(gi2, MODEL) ~= 2
    error('This template expects polynomial gencost (MODEL=2) for generator at bus 2.');
end
ncost2 = mpc.gencost(gi2, NCOST);
assert(ncost2 >= 1, 'Generator at bus 2 must have at least 1 cost coefficient to modify C0.');
col_c0_2 = 4 + (ncost2 - 1);
old_c0_2 = mpc.gencost(gi2, col_c0_2);
new_c0_2 = gen_COST_PARAMS_C3_2;
assert(new_c0_2 <= old_c0_2, 'Parameter must decrease');
mpc.gencost(gi2, col_c0_2) = new_c0_2;

% 2) Emergency simplification: set line charging susceptance BR_B to zero on branch 31-73
% Find the (first) matching branch in either direction
br_idx = find(mpc.branch(:, F_BUS) == 31 & mpc.branch(:, T_BUS) == 73, 1, 'first');
if isempty(br_idx)
    br_idx = find(mpc.branch(:, F_BUS) == 73 & mpc.branch(:, T_BUS) == 31, 1, 'first');
end
if isempty(br_idx), error('Branch 31-73 not found in case85.'); end
old_br_b = mpc.branch(br_idx, BR_B);
new_br_b = branch_BR_B_31_73;
assert(new_br_b == 0, 'Parameter must be set to zero');
mpc.branch(br_idx, BR_B) = new_br_b;

%% ---------------- multi-period DCOPF (MOST) base setup ----------------
% DC model for MOST
mpopt = mpoption('most.dc_model', 1, ...
                'model', 'DC', ...
                'opf.dc.solver', 'MIPS', ...
                'opf.violation', 1e-7, ...
                'verbose', 1, ...
                'out.all', 0);

% Create a trivial flat load profile over nt periods if no external profile is provided.
% MOST requires profiles; here we keep it self-contained with a constant profile.
if nargin < 8 || isempty(eps)
    eps = 0.05;
end
if nargin < 7 || isempty(sigma_w_MW)
    sigma_w_MW = 0;
end
if nargin < 6 || isempty(mu_w_MW)
    mu_w_MW = 0;
end
if nargin < 5 || isempty(w_bus_ext)
    w_bus_ext = mpc.bus(1, BUS_I); % default to first bus
end

% Choose nt=1 by default; users can edit here if they want multi-period >1.
nt = 1;

% Build MOST profiles: constant multipliers on PD (load)
% profile struct format: see MOST documentation; this is a minimal compatible form.
profiles = struct([]);
profiles(1).type      = 'mpcData';
profiles(1).table     = CT_TBUS;
profiles(1).rows      = (1:size(mpc.bus,1))';
profiles(1).col       = PD;
profiles(1).chgtype   = CT_REL;      % relative multiplier
profiles(1).values    = ones(nt, size(mpc.bus,1));

% xGenData empty (no unit commitment features used)
xgd = [];
mdi = loadmd(mpc, nt, xgd, [], [], profiles);

% Solve with MOST (expected dispatch)
mdo = most(mdi, mpopt);

%% ---------------- chance constraints on line limits (single-source) ----------------
% Add chance constraints to each period by re-solving a DCOPF with OM and the
% same case snapshot used by MOST at that period. For nt=1, we use the base snapshot.
% This keeps the implementation aligned with the provided chance-constraint template.

% chance level and z-value
z = norminv_approx(1 - eps/2);

% Ensure RATE_A limits exist and positive (as in the template)
rateA = mpc.branch(:, RATE_A);
if all(rateA == 0)
    mpc.branch(:, RATE_A) = 250;
else
    mpc.branch(rateA == 0, RATE_A) = 1e4;
end

% Embed mean stochastic injection as negative load at w_bus_ext
bus_idx_ext = find(mpc.bus(:, BUS_I) == w_bus_ext, 1, 'first');
if isempty(bus_idx_ext), error('Wind/stochastic injection bus not found.'); end
mpc_mean = mpc;
mpc_mean.bus(bus_idx_ext, PD) = mpc_mean.bus(bus_idx_ext, PD) - mu_w_MW;

% convert to internal indexing
mpc_i   = ext2int(mpc_mean);
baseMVA = mpc_i.baseMVA;
bus     = mpc_i.bus;
branch  = mpc_i.branch;
gen     = mpc_i.gen;

nb = size(bus, 1);
nl = size(branch, 1);
ng = size(gen, 1);

% PTDF and mapping
PTDF = makePTDF(baseMVA, bus, branch);
Cg = sparse(gen(:, GEN_BUS), (1:ng)', 1, nb, ng);
Pd = bus(:, PD) / baseMVA;

% internal index of stochastic bus
tmp = ext2int(mpc0);
w_bus_int = find(tmp.bus(:, BUS_I) == w_bus_ext, 1);
if isempty(w_bus_int), error('Wind bus internal mapping failed.'); end

sigma_w_pu = sigma_w_MW / baseMVA;
ptdf_w  = PTDF(:, w_bus_int);
sigma_f = abs(ptdf_w) * sigma_w_pu;

% Build DC OPF model
om = opf_setup(mpc_i, mpopt);
idx = om.var.idx;
i1 = idx.i1.Pg;
iN = idx.iN.Pg;
if (iN - i1 + 1) ~= ng
    error('Pg dimension mismatch.');
end
nv = om.var.N;

Fmax = branch(:, RATE_A) / baseMVA;

Arows = [];
u = [];
lb = [];

for ell = 1:nl
    if branch(ell, BR_STATUS) == 0
        continue;
    end
    a_pg  = PTDF(ell,:) * Cg;
    const = PTDF(ell,:) * (-Pd);
    margin  = Fmax(ell) - z * sigma_f(ell);
    rhs_pos = margin - const;
    rhs_neg = margin + const;

    Arows(end+1,:) = a_pg; %#ok<AGROW>
    lb(end+1,1)    = -Inf; %#ok<AGROW>
    u(end+1,1)     = rhs_pos; %#ok<AGROW>

    Arows(end+1,:) = -a_pg; %#ok<AGROW>
    lb(end+1,1)    = -Inf; %#ok<AGROW>
    u(end+1,1)     = rhs_neg; %#ok<AGROW>
end

if ~isempty(Arows)
    A = sparse(Arows);
    Afull = sparse(size(A,1), nv);
    Afull(:, i1:iN) = A;
    om = om.add_lin_constraint('CHANCE_LINE_LIMITS', Afull, lb, u);
end

% solve chance-constrained DCOPF snapshot
try
    [res_i, success, raw] = opf_execute(om, mpopt); %#ok<ASGLU>
catch
    [res_i, success, raw] = opf_execute(om, mpc_i, mpopt); %#ok<ASGLU>
end
res = int2ext(res_i, mpc_mean);

if ~success
    error('Chance-constrained DCOPF failed.');
end

% outputs
out = struct();
out.mdo = mdo;
out.cc_res = res;
out.cc_success = success;
out.cc_objective = res.f;
out.eps = eps;
out.z = z;
out.w_bus_ext = w_bus_ext;
out.mu_w_MW = mu_w_MW;
out.sigma_w_MW = sigma_w_MW;

end

function z = norminv_approx(p)
% Compute z = Phi^{-1}(p) without requiring Statistics Toolbox.
z = -sqrt(2) * erfcinv(2*p);
end

function mdo = opf_case118(branch_TAP_9_116, gen_PMIN_2)
%OPF_CASE118  Multi-period DC SCUC-style MOST run for case118 with scenario-driven parameter modifications.
%   mdo = opf_case118(branch_TAP_9_116, gen_PMIN_2)
%
% Inputs (placeholders representing post-modification values):
%   branch_TAP_9_116 : new TAP for branch 9-116 (must Increase vs original)
%   gen_PMIN_2       : new PMIN for generator at bus 2 (must Decrease vs original)

define_constants;

%% 1) Load case
mpc = loadcase('case118');

%% 2) Scenario-driven parameter modifications with direction asserts
% --- Branch TAP increase on corridor 9 -> 116
fbus = 9; tbus = 116;
br = find(mpc.branch(:, F_BUS) == fbus & mpc.branch(:, T_BUS) == tbus);
if isempty(br)
    % some cases store in opposite direction
    br = find(mpc.branch(:, F_BUS) == tbus & mpc.branch(:, T_BUS) == fbus);
end
assert(~isempty(br), 'Branch between bus 9 and bus 116 not found in case118.');
assert(numel(br) == 1, 'Multiple branches found between bus 9 and bus 116; specify unique corridor.');
orig_tap = mpc.branch(br, TAP);
if orig_tap == 0
    orig_tap = 1; % MATPOWER convention: 0 means 1.0 p.u. tap
end
assert(branch_TAP_9_116 >= orig_tap, 'Parameter must increase');
mpc.branch(br, TAP) = branch_TAP_9_116;

% --- Generator PMIN decrease at bus 2
g = find(mpc.gen(:, GEN_BUS) == 2);
assert(~isempty(g), 'No generator found at bus 2 in case118.');
if numel(g) > 1
    % apply to all gens at bus 2 consistently
    for k = 1:numel(g)
        orig_pmin = mpc.gen(g(k), PMIN);
        assert(gen_PMIN_2 <= orig_pmin, 'Parameter must decrease');
        mpc.gen(g(k), PMIN) = gen_PMIN_2;
    end
else
    orig_pmin = mpc.gen(g, PMIN);
    assert(gen_PMIN_2 <= orig_pmin, 'Parameter must decrease');
    mpc.gen(g, PMIN) = gen_PMIN_2;
end

%% 3) MOST / multi-period SCUC template structure (DC model)
verbose = 1;
mpopt = mpoption('verbose', verbose);
mpopt = mpoption(mpopt, 'out.gen', 1);
mpopt = mpoption(mpopt, 'model', 'DC');

% solver requirements
mpopt = mpoption(mpopt, 'opf.violation', 1e-6);
mpopt = mpoption(mpopt, 'opf.dc.solver', 'MIPS');
mpopt = mpoption(mpopt, 'opf.ac.solver', 'MIPS');
mpopt = mpoption(mpopt, 'most.solver', 'MIPS');
mpopt = mpoption(mpopt, 'most.price_stage_warn_tol', 1e-5);
mpopt = mpoption(mpopt, 'most.dc_model', 1);    % use DC network model

if have_feature('intlinprog')
    mpopt = mpoption(mpopt, 'linprog.Algorithm', 'dual-simplex');
    mpopt = mpoption(mpopt, 'intlinprog.RootLPAlgorithm', 'dual-simplex');
    mpopt = mpoption(mpopt, 'intlinprog.TolCon', 1e-9);
    mpopt = mpoption(mpopt, 'intlinprog.TolGapAbs', 0);
    mpopt = mpoption(mpopt, 'intlinprog.TolGapRel', 0);
    mpopt = mpoption(mpopt, 'intlinprog.TolInteger', 1e-6);
end

%% 4) Load extended generator data for UC
% Note: using example xgd bundle; user can swap with a case118-consistent xgendata file.
xgd = loadxgendata('ex_xgd_uc', mpc);

%% 5) Add wind + profiles (example profile files)
[iwind, mpc, xgd] = addwind('ex_wind_uc', mpc, xgd);
windprofile = struct( ...
    'type', 'mpcData', ...
    'table', CT_TGEN, ...
    'rows', 1, ...
    'col', PMAX, ...
    'chgtype', CT_REL, ...
    'values', [] );
wp = ex_wind_profile;
windprofile.values(:, :, 1) = mean(wp.values, 2);
profiles = getprofiles(windprofile, iwind);
profiles = getprofiles('ex_load_profile', profiles);
nt = size(profiles(1).values, 1);

%% 6) Example commitment-related edits (template-consistent)
% Keep indices safe for case118 by checking sizes.
ng = size(mpc.gen, 1);
if size(mpc.gencost, 1) >= 3
    if size(mpc.gencost, 2) >= SHUTDOWN
        mpc.gencost(2, [STARTUP SHUTDOWN]) = [300 300];
        mpc.gencost(3, [STARTUP SHUTDOWN]) = [2000 500];
    end
end
if isfield(xgd, 'MinUp') && numel(xgd.MinUp) >= 2
    xgd.MinUp(2) = 2;
end
if isfield(xgd, 'MinDown') && numel(xgd.MinDown) >= 3
    xgd.MinDown(3) = 2;
end
if isfield(xgd, 'PositiveLoadFollowReserveQuantity') && numel(xgd.PositiveLoadFollowReserveQuantity) >= 3
    xgd.PositiveLoadFollowReserveQuantity(3) = 120;
end
if isfield(xgd, 'PositiveLoadFollowReservePrice') && numel(xgd.PositiveLoadFollowReservePrice) >= 3
    xgd.PositiveLoadFollowReservePrice(3) = 10;
end
if isfield(xgd, 'NegativeLoadFollowReservePrice') && numel(xgd.NegativeLoadFollowReservePrice) >= 3
    xgd.NegativeLoadFollowReservePrice(3) = 10;
end

%% 7) Add storage (cyclic SOC)
mpopt = mpoption(mpopt, 'most.storage.cyclic', 1);
[iess, mpc, xgd, sd] = addstorage('ex_storage', mpc, xgd);

%% 8) Build multi-period data model and solve with MOST
mdi = loadmd(mpc, nt, xgd, sd, [], profiles);
mdo = most(mdi, mpopt);

if verbose
    most_summary(mdo);
end

end

function out = opf_case6ww(bus_BS_4, branch_BR_R_5_2, w_bus_ext, mu_w_MW, sigma_w_MW, eps)
%OPF_CASE6WW  Multi-period MOST DC model with chance-constrained line limits
%            + auxiliary voltage-deviation penalty evaluated on a reference AC OPF.
%
% Inputs are placeholder post-modification parameter values consistent with scenario directions.

define_constants;

%% ----- load base case -----
casefile = 'case6ww';
mpc0 = loadcase(casefile);

%% ----- scenario-driven parameter modifications with direction asserts -----
% Bus 4 BS increases
b4 = find(mpc0.bus(:, BUS_I) == 4, 1);
if isempty(b4), error('Bus 4 not found.'); end
old_BS_4 = mpc0.bus(b4, BS);
assert(bus_BS_4 >= old_BS_4, 'Parameter must increase');

% Branch 5->2 BR_R increases (match either orientation)
br52 = find((mpc0.branch(:, F_BUS) == 5 & mpc0.branch(:, T_BUS) == 2) | ...
            (mpc0.branch(:, F_BUS) == 2 & mpc0.branch(:, T_BUS) == 5), 1);
if isempty(br52), error('Branch between bus 5 and bus 2 not found.'); end
old_BR_R_5_2 = mpc0.branch(br52, BR_R);
assert(branch_BR_R_5_2 >= old_BR_R_5_2, 'Parameter must increase');

mpc = mpc0;
mpc.bus(b4, BS) = bus_BS_4;
mpc.branch(br52, BR_R) = branch_BR_R_5_2;

%% ----- solver / options -----
mpopt_most = mpoption('verbose', 1, 'out.all', 0);
mpopt_most = mpoption(mpopt_most, 'most.dc_model', 1);
mpopt_most = mpoption(mpopt_most, 'model', 'DC', 'opf.dc.solver', 'MIPS');
mpopt_most = mpoption(mpopt_most, 'opf.violation', 1e-8);

%% ----- build multi-period data (MOST) -----
% Use load and/or wind profiles if available; otherwise fall back to a flat profile.
% This keeps the function self-contained while still following the multi-period template.
nt_default = 4;
profiles = [];

try
    % Optional: user can place their own MOST profiles/xgendata on MATLAB path.
    xgd = loadxgendata('ex_xgd_ramp', mpc);
    nt = nt_default;
    mdi = loadmd(mpc, nt, xgd, [], [], profiles);
catch
    % No external xgd/profiles available; create a minimal multi-period dataset.
    xgd = [];
    nt = nt_default;
    % Flat profile: leave system unchanged across periods.
    mdi = loadmd(mpc, nt, xgd, [], [], []);
end

%% ----- add chance-constrained line limits (DC, per period) via PTDF cut on Pg -----
% We approximate by enforcing the same chance constraints in each period.
% The stochastic injection is modeled as a single uncertain net injection at w_bus_ext.

% convert to internal indexing for matrix building
mpc_i0 = ext2int(mpc);
baseMVA = mpc_i0.baseMVA;
bus_i   = mpc_i0.bus;
branch_i= mpc_i0.branch;
gen_i   = mpc_i0.gen;

nb = size(bus_i, 1);
nl = size(branch_i, 1);
ng = size(gen_i, 1);

% find internal index of wind/stochastic bus
w_bus_int = find(bus_i(:, BUS_I) == w_bus_ext, 1);
if isempty(w_bus_int), error('Stochastic injection bus not found in case.'); end

% Embed mean injection in the deterministic model as negative load (mean model)
% (applied to the underlying mpc used by MOST)
mpc_mean = mpc;
bw = find(mpc_mean.bus(:, BUS_I) == w_bus_ext, 1);
if isempty(bw), error('Stochastic injection bus not found (external).'); end
mpc_mean.bus(bw, PD) = mpc_mean.bus(bw, PD) - mu_w_MW;

% Update mdi base mpc to the mean model
mdi.mpc = mpc_mean;

% Chance parameters
z = -sqrt(2) * erfcinv(2 * (1 - eps/2));
sigma_w_pu = sigma_w_MW / baseMVA;

% Ensure RATE_A exists and is positive in underlying model
rateA = branch_i(:, RATE_A);
if all(rateA == 0)
    branch_i(:, RATE_A) = 1e4;
else
    branch_i(rateA == 0, RATE_A) = 1e4;
end

% PTDF and helper matrices
PTDF = makePTDF(baseMVA, bus_i, branch_i);          % nl x nb
Cg   = sparse(gen_i(:, GEN_BUS), (1:ng)', 1, nb, ng); % nb x ng
Pd   = bus_i(:, PD) / baseMVA;
Fmax = branch_i(:, RATE_A) / baseMVA;

ptdf_w  = PTDF(:, w_bus_int);
sigma_f = abs(ptdf_w) * sigma_w_pu;

% Build A*Pg <= u constraints for in-service lines
Arows = [];
u = [];
for ell = 1:nl
    if branch_i(ell, BR_STATUS) == 0
        continue;
    end
    a_pg  = PTDF(ell,:) * Cg;      % 1 x ng
    const = PTDF(ell,:) * (-Pd);   % scalar

    margin  = Fmax(ell) - z * sigma_f(ell);

    % mu_f <= margin  => a_pg*Pg + const <= margin
    Arows(end+1,:) = a_pg; %#ok<AGROW>
    u(end+1,1)     = margin - const; %#ok<AGROW>

    % -mu_f <= margin => -a_pg*Pg - const <= margin
    Arows(end+1,:) = -a_pg; %#ok<AGROW>
    u(end+1,1)     = margin + const; %#ok<AGROW>
end

% Store for later use: MOST can take additional constraints via userfcn; here we
% attach them to mdi as an opaque field and enforce via an OPF userfcn each period.
mdi.userdata.cc = struct('Apg', sparse(Arows), 'u', u);

% Register userfcn to add chance constraints at each period OPF model build
mpopt_most = mpoption(mpopt_most, 'opf.userfcn', 'opf_case6ww_userfcn');

%% ----- run MOST (multi-period DCOPF with chance constraints) -----
mdo = most(mdi, mpopt_most);

%% ----- voltage deviation penalty objective (AC, reference single-period) -----
% Add an AC OPF run on the modified case as a reference metric using quadratic
% voltage deviation penalty: beta*||Vm - Vref||^2.
mpopt_ac = mpoption('verbose', 1, 'out.all', 0, 'model', 'AC', 'opf.ac.solver', 'MIPS');
mpopt_ac = mpoption(mpopt_ac, 'opf.violation', 1e-8);

beta = 5000;
Vref = 1.0;

om = opf_setup(mpc_mean, mpopt_ac);
idx = om.var.idx;
i1 = idx.i1; iN = idx.iN; nv = om.var.N;

% Quadratic cost: beta * sum_k (Vm_k - Vref)^2 = beta*(Vm'Vm - 2*Vref*1'Vm + nb*Vref^2)
nb_ext = size(mpc_mean.bus, 1);
Q = sparse(nv, nv);
c = zeros(nv, 1);
k = 0;

Vm_i1 = i1.Vm; Vm_iN = iN.Vm;
Q(Vm_i1:Vm_iN, Vm_i1:Vm_iN) = 2*beta*speye(nb_ext);
c(Vm_i1:Vm_iN) = c(Vm_i1:Vm_iN) - 2*beta*Vref*ones(nb_ext, 1);
k = beta*nb_ext*(Vref^2);

om.add_quad_cost('voltage_deviation_penalty', Q, c, k);

try
    [res_ac, success_ac] = opf_execute(om, mpopt_ac);
catch
    [res_ac, success_ac] = om.solve();
    res_ac.success = (success_ac > 0);
end

%% ----- package outputs -----
out = struct();
out.mdo = mdo;
out.ac_ref = res_ac;
out.success_most = isfield(mdo, 'success') && mdo.success;
out.success_ac = success_ac;

end

function om = opf_case6ww_userfcn(om, mpopt, args)
% Userfcn hook to add chance-constraint linear cuts on Pg.
% This function is called by MATPOWER during OPF model building.

if ~isfield(om, 'mpc')
    return;
end

if ~isfield(om, 'userdata') || ~isfield(om.userdata, 'cc')
    % MOST stores userdata in om.userdata in many setups; if not present, do nothing.
    return;
end

cc = om.userdata.cc;
Apg = cc.Apg;
u   = cc.u;

if isempty(Apg)
    return;
end

idx = om.var.idx;
i1 = idx.i1.Pg;
iN = idx.iN.Pg;
ng = iN - i1 + 1;

if size(Apg, 2) ~= ng
    % dimension mismatch, skip
    return;
end

nv = om.var.N;
Afull = sparse(size(Apg, 1), nv);
Afull(:, i1:iN) = Apg;

l = -Inf(size(u));
om.add_lin_constraint('CHANCE_LINE_LIMITS', Afull, l, u);

end

function out = opf_case70da(bus_VMIN_69, bus_PD_28, bus_QD_65)
%OPF_CASE70DA  Multi-period MOST DC UC-style OPF with PTDF chance constraints + scenario parameter edits.

define_constants;

%% -------------------- 1) Load case --------------------
mpc0 = loadcase('case70da');

%% -------------------- 2) Scenario-driven parameter modifications (with direction asserts) --------------------
% Bus 69, VMIN: DISABLE -> set to zero
bus69_idx = find(mpc0.bus(:, BUS_I) == 69, 1);
if isempty(bus69_idx), error('Bus 69 not found in case70da.'); end
orig_VMIN_69 = mpc0.bus(bus69_idx, VMIN);
assert(bus_VMIN_69 == 0, 'Parameter must be set to zero');

% Bus 28, PD: Increase
bus28_idx = find(mpc0.bus(:, BUS_I) == 28, 1);
if isempty(bus28_idx), error('Bus 28 not found in case70da.'); end
orig_PD_28 = mpc0.bus(bus28_idx, PD);
assert(bus_PD_28 >= orig_PD_28, 'Parameter must increase');

% Bus 65, QD: Increase
bus65_idx = find(mpc0.bus(:, BUS_I) == 65, 1);
if isempty(bus65_idx), error('Bus 65 not found in case70da.'); end
orig_QD_65 = mpc0.bus(bus65_idx, QD);
assert(bus_QD_65 >= orig_QD_65, 'Parameter must increase');

% Apply edits
mpc = mpc0;
mpc.bus(bus69_idx, VMIN) = bus_VMIN_69;
mpc.bus(bus28_idx, PD)   = bus_PD_28;
mpc.bus(bus65_idx, QD)   = bus_QD_65;

%% -------------------- 3) MOST multi-period SCUC-style setup (DC) --------------------
verbose = 1;
mpopt = mpoption('verbose', verbose);
mpopt = mpoption(mpopt, 'out.gen', 1);
mpopt = mpoption(mpopt, 'model', 'DC');
mpopt = mpoption(mpopt, 'opf.dc.solver', 'MIPS');
mpopt = mpoption(mpopt, 'opf.violation', 1e-6);

% MOST options (use OT if available, otherwise fall back to default)
mpopt = mpoption(mpopt, 'most.solver', 'OT');
mpopt = mpoption(mpopt, 'most.price_stage_warn_tol', 1e-5);
mpopt = mpoption(mpopt, 'most.dc_model', 1);

% Optional intlinprog tuning if present
if have_feature('intlinprog')
    mpopt = mpoption(mpopt, 'linprog.Algorithm', 'dual-simplex');
    mpopt = mpoption(mpopt, 'intlinprog.RootLPAlgorithm', 'dual-simplex');
    mpopt = mpoption(mpopt, 'intlinprog.TolCon', 1e-9);
    mpopt = mpoption(mpopt, 'intlinprog.TolGapAbs', 0);
    mpopt = mpoption(mpopt, 'intlinprog.TolGapRel', 0);
    mpopt = mpoption(mpopt, 'intlinprog.TolInteger', 1e-6);
end

% Load extended generator data if available; otherwise create a minimal stub
try
    xgd = loadxgendata('ex_xgd_uc', mpc);
catch
    % minimal stub with required fields for MOST in many configurations
    ng = size(mpc.gen, 1);
    xgd = struct();
    xgd.CommitKey = (1:ng)';
    xgd.MinUp     = ones(ng,1);
    xgd.MinDown   = ones(ng,1);
end

% Add multi-period profiles if available; otherwise create a trivial 1-period profile
profiles = [];
nt = 1;
try
    % Try to follow the template: add wind, then load profiles
    try
        [iwind, mpc, xgd] = addwind('ex_wind_uc', mpc, xgd); %#ok<ASGLU>
        windprofile = struct('type','mpcData','table',CT_TGEN,'rows',1,'col',PMAX,'chgtype',CT_REL,'values',[]);
        wp = ex_wind_profile;
        windprofile.values(:, :, 1) = mean(wp.values, 2);
        profiles = getprofiles(windprofile, iwind);
    catch
        % no wind data available, continue
    end

    try
        profiles = getprofiles('ex_load_profile', profiles);
    catch
        % no load profile available, continue
    end

    if ~isempty(profiles)
        nt = size(profiles(1).values, 1);
        if isempty(nt) || nt < 1
            nt = 1;
        end
    end
catch
    profiles = [];
    nt = 1;
end

% Storage (optional)
sd = [];
try
    mpopt = mpoption(mpopt, 'most.storage.cyclic', 1);
    [iess, mpc, xgd, sd] = addstorage('ex_storage', mpc, xgd); %#ok<ASGLU>
catch
    sd = [];
end

%% -------------------- 4) Add chance-constraint cuts to the base case (used across periods) --------------------
% We implement PTDF-based chance constraints as additional linear constraints
% on the DC OPF. We attach them to the mpc userfcn so they are applied inside
% each OPF solve that MOST triggers.

% Chance constraint parameters (placeholders typical of the template)
w_bus_ext = mpc.bus(bus28_idx, BUS_I);   % choose a stressed area bus as the stochastic injection source (external bus number)
mu_w_MW    = 0;          % mean stochastic injection embedded into PD (can be 0 for pure variability study)
sigma_w_MW = 1;          % placeholder std (MW), scaled by baseMVA inside

% chance level
eps = 0.05;
z = norminv_approx(1 - eps/2);

% Ensure RATE_A exists and is positive; if some are 0, set large so they don't bind
tmp_rateA = mpc.branch(:, RATE_A);
if all(tmp_rateA == 0)
    mpc.branch(:, RATE_A) = 1e4;
else
    mpc.branch(tmp_rateA == 0, RATE_A) = 1e4;
end

% Embed mean injection as negative load at w_bus (mean model)
w_bus_idx = find(mpc.bus(:, BUS_I) == w_bus_ext, 1);
if isempty(w_bus_idx), error('Wind/stochastic bus not found.'); end
mpc.bus(w_bus_idx, PD) = mpc.bus(w_bus_idx, PD) - mu_w_MW;

% Attach userfcn to add constraints to OM at formulation time
userargs = struct('w_bus_ext', w_bus_ext, 'sigma_w_MW', sigma_w_MW, 'eps', eps, 'z', z, 'mpc0_for_map', mpc);
mpc = add_userfcn(mpc, 'formulation', @userfcn_chance_line_limits, userargs);

%% -------------------- 5) Build MOST data model and solve --------------------
mdi = loadmd(mpc, nt, xgd, sd, [], profiles);

mdo = most(mdi, mpopt);

if verbose
    try
        most_summary(mdo);
    catch
    end
end

out = struct();
out.mdo = mdo;
out.success = mdo.QP.exitflag > 0 || isfield(mdo, 'results');
out.mpopt = mpopt;
out.nt = nt;
out.scenario_parameters = struct('bus_VMIN_69', bus_VMIN_69, 'bus_PD_28', bus_PD_28, 'bus_QD_65', bus_QD_65, ...
    'orig_VMIN_69', orig_VMIN_69, 'orig_PD_28', orig_PD_28, 'orig_QD_65', orig_QD_65);

end

%% ========================================================================
%% Userfcn: add PTDF chance constraints to OPF model
%% ========================================================================
function om = userfcn_chance_line_limits(om, mpopt, args)
% Adds linear constraints implementing: |mu_f| + z*sigma_f <= Fmax
% with mu_f(l) = PTDF(l,:)*(Cg*Pg - Pd) in p.u.

define_constants;

mpc_i = om.get_mpc();
baseMVA = mpc_i.baseMVA;
bus     = mpc_i.bus;
branch  = mpc_i.branch;
gen     = mpc_i.gen;

nb = size(bus, 1);
nl = size(branch, 1);
ng = size(gen, 1);

% Build PTDF and mappings
PTDF = makePTDF(baseMVA, bus, branch); % (nl x nb)
Cg   = sparse(gen(:, GEN_BUS), (1:ng)', 1, nb, ng);
Pd   = bus(:, PD) / baseMVA;

% internal index of stochastic bus
w_bus_ext = args.w_bus_ext;
w_bus_int = find(bus(:, BUS_I) == w_bus_ext, 1);
if isempty(w_bus_int)
    error('Chance-constraint stochastic bus internal mapping failed.');
end

sigma_w_pu = args.sigma_w_MW / baseMVA;
ptdf_w  = PTDF(:, w_bus_int);
sigma_f = abs(ptdf_w) * sigma_w_pu;

% OM var indices for Pg
idx = om.var.idx;
i1 = idx.i1.Pg;
iN = idx.iN.Pg;
if (iN - i1 + 1) ~= ng
    error('Pg dimension mismatch.');
end
nv = om.var.N;

Fmax = branch(:, RATE_A) / baseMVA;
z = args.z;

Arows = [];
u = [];
l = [];

for ell = 1:nl
    if branch(ell, BR_STATUS) == 0
        continue;
    end

    a_pg  = PTDF(ell,:) * Cg;     % 1 x ng
    const = PTDF(ell,:) * (-Pd);  % scalar

    margin  = Fmax(ell) - z * sigma_f(ell);
    rhs_pos = margin - const;
    rhs_neg = margin + const;

    Arows(end+1,:) = a_pg; %#ok<AGROW>
    l(end+1,1)     = -Inf; %#ok<AGROW>
    u(end+1,1)     = rhs_pos; %#ok<AGROW>

    Arows(end+1,:) = -a_pg; %#ok<AGROW>
    l(end+1,1)     = -Inf; %#ok<AGROW>
    u(end+1,1)     = rhs_neg; %#ok<AGROW>
end

if ~isempty(Arows)
    A = sparse(Arows);
    Afull = sparse(size(A,1), nv);
    Afull(:, i1:iN) = A;
    om = om.add_lin_constraint('CHANCE_LINE_LIMITS', Afull, l, u);
end

end

function z = norminv_approx(p)
% Compute z = Phi^{-1}(p) without requiring Statistics Toolbox.
z = -sqrt(2) * erfcinv(2*p);
end

function results = opf_case145(gen_QMAX_3, gen_PMAX_21)
%OPF_CASE145 Level-4 Economy Dispatch with scenario parameter changes and emissions objective

define_constants;
mpc0 = loadcase('case145');
mpc = mpc0;

%% -------------------- Scenario-driven parameter modifications --------------------
% Generator at bus 3: QMAX increases
ig3 = find(mpc.gen(:, GEN_BUS) == 3, 1, 'first');
assert(~isempty(ig3), 'No generator found at bus 3');
qmax0_3 = mpc0.gen(ig3, QMAX);
assert(gen_QMAX_3 >= qmax0_3, 'Parameter must increase');
mpc.gen(ig3, QMAX) = gen_QMAX_3;

% Generator at bus 21: PMAX decreases
ig21 = find(mpc.gen(:, GEN_BUS) == 21, 1, 'first');
assert(~isempty(ig21), 'No generator found at bus 21');
pmax0_21 = mpc0.gen(ig21, PMAX);
assert(gen_PMAX_21 <= pmax0_21, 'Parameter must decrease');
mpc.gen(ig21, PMAX) = gen_PMAX_21;

%% -------------------- Economy Dispatch setup (QP) --------------------
% Only Pg is optimized, with sum(Pg) = sum(Pd) and Pmin <= Pg <= Pmax.
% Base quadratic generation costs are taken from mpc.gencost.

Pd = sum(mpc.bus(:, PD));
Pmin = mpc.gen(:, PMIN);
Pmax = mpc.gen(:, PMAX);
ng = size(mpc.gen, 1);

% Ensure polynomial cost model; if not, fall back to zero quadratic/linear.
% MATPOWER gencost format: [MODEL STARTUP SHUTDOWN NCOST c(n-1) ... c0]
% For quadratic, NCOST=3 and coefficients are [c2 c1 c0] at the end.
if size(mpc.gencost, 2) >= 7 && all(mpc.gencost(:, MODEL) == POLYNOMIAL)
    c2 = mpc.gencost(:, end-2);
    c1 = mpc.gencost(:, end-1);
    c0 = mpc.gencost(:, end);
else
    c2 = zeros(ng,1);
    c1 = zeros(ng,1);
    c0 = zeros(ng,1);
end

%% -------------------- Emissions objective modification (template-inspired) --------------------
% Add an environmental impact quadratic cost term: eta*(gamma*Pg^2 + beta*Pg + alpha)
eta_emission = 100; % as in template

% Use placeholder per-generator emission parameters consistent with the template structure.
% If ng > 3, extend by repeating the last row to match ng.
em3 = [
    10, 2.0, 0.05;
    15, 1.8, 0.04;
    12, 2.2, 0.06
];
if ng <= 3
    emission_params = em3(1:ng, :);
else
    emission_params = [em3; repmat(em3(end,:), ng-3, 1)];
end
alpha_em = emission_params(:,1);
beta_em  = emission_params(:,2);
gamma_em = emission_params(:,3);

% Total objective: sum( (c2 + eta*gamma_em)*Pg^2 + (c1 + eta*beta_em)*Pg + (c0 + eta*alpha_em) )
C2t = c2 + eta_emission * gamma_em;
C1t = c1 + eta_emission * beta_em;
C0t = c0 + eta_emission * alpha_em;

H = 2 * diag(C2t); % quadprog uses 1/2*x'*H*x
f = C1t;
Aeq = ones(1, ng);
beq = Pd;
lb = Pmin;
ub = Pmax;

% Solve QP
qp_opts = optimoptions('quadprog', 'Display', 'none');
[Pg, fval, exitflag, output] = quadprog(H, f, [], [], Aeq, beq, lb, ub, [], qp_opts);

% Pack results in MATPOWER-like struct
results = mpc;
results.gen(:, PG) = Pg;
results.f = fval + sum(C0t); % add constant terms
results.success = (exitflag > 0);
results.et = NaN;
results.raw.exitflag = exitflag;
results.raw.output = output;

%% -------------------- Also provide an AC-OPF run with solver settings (violation/MIPS) --------------------
% This is solved after ED for validation under the requested OPF options; ED solution is kept.
mpopt = mpoption('verbose', 0, 'out.all', 0);
mpopt = mpoption(mpopt, 'opf.violation', 1e-6);
mpopt = mpoption(mpopt, 'model', 'AC');
mpopt = mpoption(mpopt, 'opf.ac.solver', 'MIPS');

try
    opfres = runopf(mpc, mpopt);
    results.opf = opfres;
catch me
    results.opf = [];
    results.opf_error = me.message;
end

end

function mdo = opf_case300(branch_BR_STATUS_92_298, gen_QMIN_17)
%OPF_CASE300 Multi-period DCOPF (MOST) with scenario parameter modifications
% and added regulation-up (RU) reserve constraints.
%
% Inputs (placeholders representing post-modification values):
%   branch_BR_STATUS_92_298 : new BR_STATUS for branch 92-298 (must be set to zero)
%   gen_QMIN_17             : new QMIN for generator at bus 17 (must decrease)
%
% Output:
%   mdo : MOST output struct

define_constants;

%% ================== Load system ========================
mpc = loadcase('case300');

%% ================== Scenario-driven parameter modifications ========================
% (1) Corridor unavailable: open (disable) branch 92-298 by setting BR_STATUS = 0
br_idx = find( (mpc.branch(:, F_BUS) == 92 & mpc.branch(:, T_BUS) == 298) | ...
              (mpc.branch(:, F_BUS) == 298 & mpc.branch(:, T_BUS) == 92) );
assert(~isempty(br_idx), 'Branch between buses 92 and 298 not found in case300');
assert(isscalar(br_idx), 'Expected a single branch between buses 92 and 298');
old_BR_STATUS = mpc.branch(br_idx, BR_STATUS);
assert(branch_BR_STATUS_92_298 == 0, 'Parameter must be set to zero');
mpc.branch(br_idx, BR_STATUS) = branch_BR_STATUS_92_298;

% (2) High-voltage regions need stronger reactive regulation: decrease QMIN at bus 17
g_idx = find(mpc.gen(:, GEN_BUS) == 17);
assert(~isempty(g_idx), 'Generator at bus 17 not found in case300');
assert(isscalar(g_idx), 'Expected a single generator at bus 17');
old_QMIN = mpc.gen(g_idx, QMIN);
assert(gen_QMIN_17 <= old_QMIN, 'Parameter must decrease');
mpc.gen(g_idx, QMIN) = gen_QMIN_17;

%% ================== MOST multi-period DC model setup ========================
% DC model and solver settings
mpopt = mpoption('most.dc_model', 1, ...
                 'opf.violation', 1e-7, ...
                 'opf.ac.solver', 'MIPS', ...
                 'opf.dc.solver', 'MIPS', ...
                 'verbose', 0, ...
                 'out.all', 0);

% --- Build a simple multi-period profile set internally (no external files).
% Use a placeholder number of periods and keep profiles neutral (all ones)
% so the problem structure is multi-period without prescribing numeric scenario magnitudes.
nt = 24;  % number of periods (typical day-ahead horizon)

% Construct MOST profiles: scale all bus loads by 1 in each period
nb = size(mpc.bus, 1);
prof_load = struct();
prof_load(1).type = 'mpcData';
prof_load(1).table = CT_TBUS;
prof_load(1).rows = (1:nb)';
prof_load(1).col = PD;
prof_load(1).chgtype = CT_MULT;
prof_load(1).values = ones(nt, nb);

profiles = prof_load;

% xGenData: empty (no unit commitment, no ramps), but MOST expects a struct
xgd = struct();

mdi = loadmd(mpc, nt, xgd, [], [], profiles);

%% ================== Run MOST ========================
% MOST supports userfcn callbacks; we add RU constraints to each period's OPF model.
mdi = add_most_userfcn_ru(mdi);

mdo = most(mdi, mpopt);

end

%% ========================================================================
function mdi = add_most_userfcn_ru(mdi)
%ADD_MOST_USERFCN_RU Adds a MOST userfcn to enforce regulation-up constraints.

if ~isfield(mdi, 'userfcn') || isempty(mdi.userfcn)
    mdi.userfcn = struct('name', {}, 'stage', {}, 'fcn', {}, 'args', {});
end

k = numel(mdi.userfcn) + 1;
mdi.userfcn(k).name  = 'ru_constraints_each_period';
mdi.userfcn(k).stage = 'formulation';
mdi.userfcn(k).fcn   = @ru_userfcn_formulation;
mdi.userfcn(k).args  = {};

end

function om = ru_userfcn_formulation(om, mpopt, args)
%RU_USERFCN_FORMULATION Adds RU variables and constraints to the OPF model.
% This is executed for each time period subproblem created by MOST.

define_constants;
mpc = om.get_mpc();
baseMVA = mpc.baseMVA;
ng = size(mpc.gen, 1);

% Regulation-up parameters (template-aligned); treated as generic constants
% for structure; no scenario-specific numeric tuning beyond the template.
RUmax_MW = 45 * ones(ng, 1);
regions  = { [1 2], [3] };  % generator-index regions (example partition)
R_RU_MW  = [70; 70];        % regional RU requirement (MW)

RUmax_pu = RUmax_MW / baseMVA;
R_RU_pu  = R_RU_MW  / baseMVA;

% Add RU decision variables: 0 <= RU <= RUmax
om.add_var('RU', ng, zeros(ng, 1), zeros(ng, 1), RUmax_pu);

% Indexing for Pg and RU
iPg = om.var.idx.i1.Pg : om.var.idx.iN.Pg;
iRU = om.var.idx.i1.RU : om.var.idx.iN.RU;
nv  = om.var.N;

% (1) Unit headroom: Pg + RU <= PMAX   (p.u.)
A = sparse(ng, nv);
A(:, iPg) = speye(ng);
A(:, iRU) = speye(ng);
u_pu = mpc.gen(:, PMAX) / baseMVA;
om.add_lin_constraint('Pg_RU_le_Pmax', A, -inf(ng, 1), u_pu);

% (2) Regional RU procurement: sum(RU in region) >= R_RU (p.u.)
nr = numel(regions);
Areg = sparse(nr, nv);
for j = 1:nr
    idx = regions{j};
    idx = idx(idx >= 1 & idx <= ng);
    Areg(j, iRU(idx)) = 1;
end
om.add_lin_constraint('region_RU_req', Areg, R_RU_pu, inf(nr, 1));

end

function mdo = opf_case33mg(branch_BR_B_20_26, gen_PMAX_5)
%OPF_CASE33MG  Multi-period DC OPF (MOST) with scenario parameter changes,
% soft line limits, and regulation-up reserve requirement.
%
% Returns MOST output struct mdo.

define_constants;

%% =============== Load base case ======================
mpc0 = loadcase('case33mg');

%% =============== Scenario-driven parameter modifications (with asserts) ===
% (1) Branch shunt susceptance BR_B on line 20-26 must Increase
br = mpc0.branch;
mask_20_26 = ( (br(:, F_BUS) == 20 & br(:, T_BUS) == 26) | (br(:, F_BUS) == 26 & br(:, T_BUS) == 20) );
assert(nnz(mask_20_26) == 1, 'Expected exactly one branch between bus 20 and bus 26 in case33mg.');
old_BR_B_20_26 = br(mask_20_26, BR_B);
assert(branch_BR_B_20_26 >= old_BR_B_20_26, 'Parameter must increase');
mpc0.branch(mask_20_26, BR_B) = branch_BR_B_20_26;

% (2) Generator PMAX at bus 5 must Increase
g = mpc0.gen;
mask_gen_bus5 = (g(:, GEN_BUS) == 5);
assert(nnz(mask_gen_bus5) >= 1, 'Expected at least one generator at bus 5 in case33mg.');
old_PMAX_bus5 = g(mask_gen_bus5, PMAX);
assert(all(gen_PMAX_5 >= old_PMAX_bus5), 'Parameter must increase');
mpc0.gen(mask_gen_bus5, PMAX) = gen_PMAX_5;

%% =============== MOST multi-period setup (DC) =========================
mpopt = mpoption('most.dc_model', 1, ...
                 'model', 'DC', ...
                 'opf.dc.solver', 'MIPS', ...
                 'opf.violation', 1e-8, ...
                 'verbose', 0, 'out.all', 0);

% --- Profiles: if user does not provide external profiles, create a flat profile
% across nt periods that preserves base-case loads.
nt = 24; % placeholder horizon length (can be edited by user)
nb = size(mpc0.bus, 1);

% Build a MOST-style profile struct for fixed real power demand scaling (flat = 1)
profiles = struct([]);
profiles(1).type      = 'mpcData';
profiles(1).table     = 'bus';
profiles(1).rows      = (1:nb)';
profiles(1).col       = PD;
profiles(1).chgtype   = 1;                 % replace
profiles(1).values    = repmat(mpc0.bus(:, PD).', nt, 1);

mdi = loadmd(mpc0, nt, [], [], [], profiles);

%% =============== Build MOST/OPF model and add structural modifications ===
% We solve each period via OM-based DCOPF, embedding:
%   - regulation-up reserve vars + constraints
%   - soft line limits via slack vars with linear penalty

% Parameters for added features (placeholders; user may tune)
lambda_slack = 10000; % linear penalty on soft line limit slacks

% Regulation-up requirement (single system-wide requirement per period)
% Using the template notion: RUmax_MW and R_RU_MW; placeholders set here.
% NOTE: Values below are structural placeholders; change as needed.
RUmax_MW = 45;  % template value
R_RU_MW  = 70;  % template value

% Configure MOST to use a custom DC OPF model builder via userfcn.
% We attach data to mdi for access inside callbacks.
mdi.userdata.lambda_slack = lambda_slack;
mdi.userdata.RUmax_MW = RUmax_MW;
mdi.userdata.R_RU_MW  = R_RU_MW;

% Add user functions that modify each period OPF model
mdi = add_userfcn(mdi, 'most', 'formulation', @userfcn_most_formulation);

% Run MOST
mdo = most(mdi, mpopt);

end

%% ======================= MOST userfcn: formulation =========================
function mm = userfcn_most_formulation(mm, ~)
% Called by MOST during formulation building; we hook into each time period OM.

define_constants;

lambda_slack = mm.userdata.lambda_slack;
RUmax_MW     = mm.userdata.RUmax_MW;
R_RU_MW      = mm.userdata.R_RU_MW;

nt = mm.nt;
for t = 1:nt
    % Each period has its own MATPOWER case in mm.mpc(t)
    mpc_t = mm.mpc(t);
    baseMVA = mpc_t.baseMVA;

    % Build an OM DCOPF model for this period
    mpopt_t = mm.mpopt;
    mpopt_t = mpoption(mpopt_t, 'model', 'DC', 'opf.dc.solver', 'MIPS', 'opf.violation', 1e-8);
    om = opf_setup(mpc_t, mpopt_t);

    % Add soft line limits (DC approximation using PF values)
    om = add_soft_line_limits_dc(om, mpc_t, lambda_slack);

    % Add regulation-up reserve variables + constraints
    om = add_regulation_up_dc(om, mpc_t, RUmax_MW, R_RU_MW);

    % Solve this period OPF
    [x, f, eflag] = om.solve();
    if eflag <= 0
        error('MOST period %d OPF failed, eflag=%d', t, eflag);
    end

    % Store solution back to MOST model object
    mm.results(t).om = om;
    mm.results(t).x  = x;
    mm.results(t).f  = f;
    mm.results(t).eflag = eflag;
end

end

%% ======================= Add regulation up (DC) ============================
function om = add_regulation_up_dc(om, mpc, RUmax_MW, R_RU_MW)

define_constants;

baseMVA = mpc.baseMVA;
ng = size(mpc.gen, 1);

% Add RU variable: 0 <= RU <= RUmax
RUmax_pu = (RUmax_MW * ones(ng, 1)) / baseMVA;
om.add_var('RU', ng, zeros(ng,1), zeros(ng,1), RUmax_pu);

iPg = om.var.idx.i1.Pg : om.var.idx.iN.Pg;
iRU = om.var.idx.i1.RU : om.var.idx.iN.RU;
nv  = om.var.N;

% (1) Pg + RU <= PMAX (in p.u.)
A = sparse(ng, nv);
A(:, iPg) = speye(ng);
A(:, iRU) = speye(ng);

u_pu = mpc.gen(:, PMAX) / baseMVA;
om.add_lin_constraint('Pg_plus_RU_le_Pmax', A, -inf(ng,1), u_pu);

% (2) System-wide RU requirement: sum RU >= R_RU
R_RU_pu = (R_RU_MW / baseMVA);
Areq = sparse(1, nv);
Areq(1, iRU) = 1;
om.add_lin_constraint('RU_requirement', Areq, R_RU_pu, inf);

end

%% ======================= Soft line limits (DC) =============================
function om = add_soft_line_limits_dc(om, mpc, lambda_slack)
% Adds nonnegative slacks s_from, s_to and penalizes them linearly.
% Constraint uses |Pf| <= RATE_A + s_from and |Pt| <= RATE_A + s_to.
% Implemented as two-sided linear constraints on Pf and Pt.

define_constants;

nl = size(mpc.branch, 1);

% Prepare RATE_A, replace zeros with a default placeholder
rate_a = mpc.branch(:, RATE_A);
rate_a(rate_a == 0) = 250;

% Add slack variables
om.add_var('s_from', nl, zeros(nl,1), zeros(nl,1), inf(nl,1));
om.add_var('s_to',   nl, zeros(nl,1), zeros(nl,1), inf(nl,1));

% Indices
idx_i1 = om.var.idx.i1;
idx_iN = om.var.idx.iN;

iVa = idx_i1.Va:idx_iN.Va;
isf = idx_i1.s_from:idx_iN.s_from;
ist = idx_i1.s_to:idx_iN.s_to;
nv  = om.var.N;

% DC flow: Pf = Bf * Va (p.u.), where Bf is from makeBdc
[Bbus, Bf, Pbusinj, Pfinj] = makeBdc(mpc.baseMVA, mpc.bus, mpc.branch);
% In MATPOWER DC model, branch flow (from end) in p.u. is: Pf_pu = Bf*Va + Pfinj
% Convert limits to p.u.
rate_pu = rate_a / mpc.baseMVA;

% Build constraints for from-end flows (two-sided with slack):
%  Pf_pu - s_from <= rate_pu
% -Pf_pu - s_from <= rate_pu
% => [ Bf  ...  -I ...] * x <= rate_pu - Pfinj   and  [-Bf ... -I ...] * x <= rate_pu + Pfinj
A1 = sparse(nl, nv);
A2 = sparse(nl, nv);
A1(:, iVa) = Bf;
A2(:, iVa) = -Bf;
A1(:, isf) = -speye(nl);
A2(:, isf) = -speye(nl);

u1 = rate_pu - Pfinj; % Pf - s <= rate
u2 = rate_pu + Pfinj; % -Pf - s <= rate

om.add_lin_constraint('soft_from_pos', A1, -inf(nl,1), u1);
om.add_lin_constraint('soft_from_neg', A2, -inf(nl,1), u2);

% To-end flow in DC is approximately -Pf for a lossless line; MATPOWER provides PT via -Pf.
% We mirror the same with s_to using Pf expression:
A3 = sparse(nl, nv);
A4 = sparse(nl, nv);
A3(:, iVa) = -Bf;
A4(:, iVa) = Bf;
A3(:, ist) = -speye(nl);
A4(:, ist) = -speye(nl);

% Pt_pu = -Pf_pu => Pt_pu = -(Bf*Va + Pfinj) = -Bf*Va - Pfinj
% Constraints analogous:
%  Pt - s_to <= rate  => (-Bf*Va - Pfinj) - s_to <= rate  => (-Bf)*Va - s_to <= rate + Pfinj
% -Pt - s_to <= rate  => ( Bf*Va + Pfinj) - s_to <= rate  => ( Bf)*Va - s_to <= rate - Pfinj
u3 = rate_pu + Pfinj;
u4 = rate_pu - Pfinj;

om.add_lin_constraint('soft_to_pos', A3, -inf(nl,1), u3);
om.add_lin_constraint('soft_to_neg', A4, -inf(nl,1), u4);

% Add linear penalty via quadratic-cost interface: f += c'*x
Q = sparse(nv, nv);
c = zeros(nv, 1);
c(isf) = lambda_slack;
c(ist) = lambda_slack;
k = 0;
om.add_quad_cost('soft_line_slack_penalty', Q, c, k);

end

function mdo = opf_case39(bus_PD_10, bus_QD_1, gen_QMAX_7)
%OPF_CASE39  Multi-period DCOPF (MOST) for case39 with scenario parameter modifications
%            and a quadratic penalty on voltage angle differences.
%
% Inputs are post-modification placeholder values consistent with scenario directions:
%   bus_PD_10   : new PD at bus 10 (must DECREASE)
%   bus_QD_1    : new QD at bus 1  (must DECREASE)
%   gen_QMAX_7  : new QMAX for generator at bus 7 (must INCREASE)

define_constants;

%% load base case
mpc = loadcase('case39');

%% validate bus IDs exist
nb = size(mpc.bus, 1);
assert(any(mpc.bus(:, BUS_I) == 10), 'Bus 10 not found in case39');
assert(any(mpc.bus(:, BUS_I) == 1),  'Bus 1 not found in case39');

%% locate indices
iBus10 = find(mpc.bus(:, BUS_I) == 10, 1, 'first');
iBus1  = find(mpc.bus(:, BUS_I) == 1,  1, 'first');

gen7 = find(mpc.gen(:, GEN_BUS) == 7, 1, 'first');
assert(~isempty(gen7), 'No generator found at bus 7 in case39');

%% direction validation asserts (scenario-driven modifications)
% Bus 10 PD decreases
PD10_old = mpc.bus(iBus10, PD);
assert(bus_PD_10 <= PD10_old, 'Parameter must decrease');
% Bus 1 QD decreases
QD1_old = mpc.bus(iBus1, QD);
assert(bus_QD_1 <= QD1_old, 'Parameter must decrease');
% Gen at bus 7 QMAX increases
QMAX7_old = mpc.gen(gen7, QMAX);
assert(gen_QMAX_7 >= QMAX7_old, 'Parameter must increase');

%% apply parameter modifications
mpc.bus(iBus10, PD) = bus_PD_10;
mpc.bus(iBus1,  QD) = bus_QD_1;
mpc.gen(gen7, QMAX) = gen_QMAX_7;

%% MOST / DC multi-period setup
% NOTE: This function assumes required MOST inputs (xgd, profiles) are available
%       in the caller's path/workspace as in the provided template.
%       Replace ex_* placeholders with your data sources.
mpopt = mpoption('most.dc_model', 1);
mpopt = mpoption(mpopt, 'verbose', 1, 'out.all', 0);
mpopt = mpoption(mpopt, 'opf.violation', 1e-6);
mpopt = mpoption(mpopt, 'opf.dc.solver', 'MIPS');

%% load extended generator data and profiles (placeholders per template)
% These files/variables must exist for a runnable MOST study.
% - ex_xgd_ramp: xGenData with ramping, commitment, etc.
% - ex_wind, ex_wind_profile_d: wind plant definitions and profiles
% - ex_load_profile: load profiles
xgd = loadxgendata('ex_xgd_ramp', mpc);
[iwind, mpc, xgd] = addwind(ex_wind, mpc, xgd);
profiles = getprofiles(ex_wind_profile_d, iwind);
profiles = getprofiles(ex_load_profile, profiles);
nt = size(profiles(1).values, 1);

%% build MOST data
mdi = loadmd(mpc, nt, xgd, [], [], profiles);

%% add quadratic angle-difference penalty in each period
% We add: beta * ||E * Va||^2, with MATPOWER quadratic cost 0.5*x'*Q*x
beta = 10;

for t = 1:nt
    % Ensure mpc for this time period exists
    if ~isfield(mdi, 'mpc') || numel(mdi.mpc) < t
        error('MOST input mdi.mpc is not properly populated for all periods.');
    end
    mpc_t = mdi.mpc(t);

    % Build OPF model for this period and add quad cost on Va
    % Use DC model; Va exists in DC OPF variables.
    mpopt_t = mpopt;
    mpopt_t = mpoption(mpopt_t, 'model', 'DC');

    om = opf_setup(mpc_t, mpopt_t);

    nb_t = size(mpc_t.bus, 1);
    nl_t = size(mpc_t.branch, 1);
    f = mpc_t.branch(:, F_BUS);
    tt = mpc_t.branch(:, T_BUS);

    % incidence for angle differences; uses bus numbering as row indices
    % case39 uses contiguous bus numbers, but to be safe map BUS_I -> internal index
    bus_ids = mpc_t.bus(:, BUS_I);
    % map external bus id to internal row index
    map = sparse(bus_ids, 1, (1:nb_t)', max(bus_ids), 1);
    fi = full(map(f));
    ti = full(map(tt));
    if any(fi == 0) || any(ti == 0)
        error('Branch bus mapping failed due to non-contiguous BUS_I labels.');
    end

    E = sparse(1:nl_t, fi,  1, nl_t, nb_t) + sparse(1:nl_t, ti, -1, nl_t, nb_t);
    Q_va = 2 * beta * (E' * E);

    om = om.add_quad_cost('ang_diff_pen', Q_va, [], 0, {'Va'});

    % write back the augmented om into mdi using MOST userfcn mechanism
    % Store per-period userfcn that will rebuild and augment the OM at solve time.
    % MOST supports userfcn callbacks; here we attach data and use a nested function.
    mdi.userfcn.angpen(t).name = 'angpen';
    mdi.userfcn.angpen(t).stage = 'formulation';
    mdi.userfcn.angpen(t).fcn = @userfcn_angpen;
    mdi.userfcn.angpen(t).args = {beta};
end

%% solve with MOST
mdo = most(mdi, mpopt);

end

function om = userfcn_angpen(om, mpopt, args)
%USERFCN_ANGPEN MOST/OPF userfcn to add quadratic penalty on line angle differences.
define_constants;

beta = args{1};
mpc = om.get_mpc();

nb = size(mpc.bus, 1);
nl = size(mpc.branch, 1);

f = mpc.branch(:, F_BUS);
t = mpc.branch(:, T_BUS);
bus_ids = mpc.bus(:, BUS_I);
map = sparse(bus_ids, 1, (1:nb)', max(bus_ids), 1);
fi = full(map(f));
ti = full(map(t));
E = sparse(1:nl, fi,  1, nl, nb) + sparse(1:nl, ti, -1, nl, nb);
Q_va = 2 * beta * (E' * E);

om = om.add_quad_cost('ang_diff_pen', Q_va, [], 0, {'Va'});
end

function results = opf_case89pegase(gen_COST_PARAMS_C1_8, gen_COST_PARAMS_C2_9, gen_COST_PARAMS_C3_11, bus_PD_41)
%OPF_CASE89PEGASE  DCOPF for case89pegase with scenario-driven parameter updates.
%
%   Inputs are placeholder post-modification values consistent with direction
%   requirements:
%     - gen_COST_PARAMS_C1_8   : Decrease gencost C1 at generator on bus 8
%     - gen_COST_PARAMS_C2_9   : Decrease gencost C2 at generator on bus 9
%     - gen_COST_PARAMS_C3_11  : Decrease gencost C0 at generator on bus 11
%     - bus_PD_41              : Increase PD at bus 41

define_constants;

%% load base case
mpc = loadcase('case89pegase');

%% locate generators by GEN_BUS
ig8  = find(mpc.gen(:, GEN_BUS) == 8);
ig9  = find(mpc.gen(:, GEN_BUS) == 9);
ig11 = find(mpc.gen(:, GEN_BUS) == 11);
assert(~isempty(ig8),  'No generator found at bus 8');
assert(~isempty(ig9),  'No generator found at bus 9');
assert(~isempty(ig11), 'No generator found at bus 11');

% if multiple gens at same bus, apply to all at that bus (consistent with scenario statement)

%% direction-validated modifications
% Bus 41 PD increase
old_PD_41 = mpc.bus(41, PD);
assert(bus_PD_41 >= old_PD_41, 'Parameter must increase');
mpc.bus(41, PD) = bus_PD_41;

% Generator cost coefficient decreases
% MATPOWER gencost model 2: [2 startup shutdown n c(n-1) ... c0]
% For quadratic costs (n=3): c2 at col 5, c1 at col 6, c0 at col 7.
% For linear costs (n=2): c1 at col 5, c0 at col 6.

% Decrease C1 for generators at bus 8
for k = 1:numel(ig8)
    i = ig8(k);
    n = mpc.gencost(i, NCOST);
    assert(mpc.gencost(i, MODEL) == 2, 'Expected polynomial cost model (MODEL=2)');
    if n == 3
        old = mpc.gencost(i, 6); % c1
        assert(gen_COST_PARAMS_C1_8 <= old, 'Parameter must decrease');
        mpc.gencost(i, 6) = gen_COST_PARAMS_C1_8;
    elseif n == 2
        old = mpc.gencost(i, 5); % c1 (linear)
        assert(gen_COST_PARAMS_C1_8 <= old, 'Parameter must decrease');
        mpc.gencost(i, 5) = gen_COST_PARAMS_C1_8;
    else
        error('Unsupported NCOST=%d for generator at bus 8 (expected 2 or 3).', n);
    end
end

% Decrease C2 for generators at bus 9 (requires quadratic cost)
for k = 1:numel(ig9)
    i = ig9(k);
    n = mpc.gencost(i, NCOST);
    assert(mpc.gencost(i, MODEL) == 2, 'Expected polynomial cost model (MODEL=2)');
    assert(n == 3, 'C2 modification requires quadratic cost with NCOST=3');
    old = mpc.gencost(i, 5); % c2
    assert(gen_COST_PARAMS_C2_9 <= old, 'Parameter must decrease');
    mpc.gencost(i, 5) = gen_COST_PARAMS_C2_9;
end

% Decrease C3 (interpreted as constant term c0) for generators at bus 11
for k = 1:numel(ig11)
    i = ig11(k);
    n = mpc.gencost(i, NCOST);
    assert(mpc.gencost(i, MODEL) == 2, 'Expected polynomial cost model (MODEL=2)');
    if n == 3
        old = mpc.gencost(i, 7); % c0
        assert(gen_COST_PARAMS_C3_11 <= old, 'Parameter must decrease');
        mpc.gencost(i, 7) = gen_COST_PARAMS_C3_11;
    elseif n == 2
        old = mpc.gencost(i, 6); % c0
        assert(gen_COST_PARAMS_C3_11 <= old, 'Parameter must decrease');
        mpc.gencost(i, 6) = gen_COST_PARAMS_C3_11;
    else
        error('Unsupported NCOST=%d for generator at bus 11 (expected 2 or 3).', n);
    end
end

%% solver options (DCOPF)
mpopt = mpoption('model', 'DC', ...
    'opf.dc.solver', 'MIPS', ...
    'opf.violation', 1e-7, ...
    'verbose', 2);

%% run DCOPF
results = rundcopf(mpc, mpopt);

end

function results = opf_case33bw(branch_RATE_A_11_30, gen_PMIN_2)
%OPF_CASE33BW  DC-SCOPF on case33bw with scenario-driven parameter changes
%              and an added quadratic voltage-magnitude surrogate cost.
%
% Inputs (placeholders for post-modification values consistent with directions):
%   branch_RATE_A_11_30 : increased RATE_A for branch 11-30
%   gen_PMIN_2          : decreased PMIN for generator at bus 2
%
% Output:
%   results : MATPOWER results struct (external indexing)

define_constants;

%% load base case
mpc0 = loadcase('case33bw');
if isempty(mpc0)
    error('Failed to load case33bw');
end

%% validate and apply scenario-driven parameter modifications (external indexing)
% --- Branch 11-30 RATE_A must Increase
br = mpc0.branch;
f = br(:, F_BUS);
t = br(:, T_BUS);
idx_1130 = find((f == 11 & t == 30) | (f == 30 & t == 11));
assert(~isempty(idx_1130), 'Branch between buses 11 and 30 not found in case33bw');
assert(numel(idx_1130) == 1, 'Expected a single branch between buses 11 and 30');
old_rateA_1130 = mpc0.branch(idx_1130, RATE_A);
assert(branch_RATE_A_11_30 >= old_rateA_1130, 'Parameter must increase');
mpc0.branch(idx_1130, RATE_A) = branch_RATE_A_11_30;

% --- Generator at bus 2 PMIN must Decrease
g = mpc0.gen;
gbus = g(:, GEN_BUS);
idx_g2 = find(gbus == 2);
assert(~isempty(idx_g2), 'No generator found at bus 2 in case33bw');
assert(numel(idx_g2) == 1, 'Expected a single generator at bus 2');
old_pmin_g2 = mpc0.gen(idx_g2, PMIN);
assert(gen_PMIN_2 <= old_pmin_g2, 'Parameter must decrease');
mpc0.gen(idx_g2, PMIN) = gen_PMIN_2;

%% solver options (DC, MIPS) and violation tolerance
mpopt = mpoption('verbose', 1, 'out.all', 0);
mpopt = mpoption(mpopt, 'model', 'DC');
mpopt = mpoption(mpopt, 'opf.dc.solver', 'MIPS');
mpopt = mpoption(mpopt, 'opf.violation', 1e-8);

%% build DC-SCOPF model using internal indexing
mpc = ext2int(mpc0);
baseMVA = mpc.baseMVA;
bus    = mpc.bus;
branch = mpc.branch;

nb = size(bus, 1);
nl = size(branch, 1);

% DC network matrices and PTDF/LODF
[~, Bf, ~, Pfinj] = makeBdc(baseMVA, bus, branch);
PTDF = makePTDF(baseMVA, bus, branch);
LODF = makeLODF(branch, PTDF);

% contingency set: all in-service branches with RATE_A > 0
in_service = (branch(:, BR_STATUS) == 1);
has_limit  = (branch(:, RATE_A) > 0);
cont_set   = find(in_service & has_limit);
nc = length(cont_set);
if isempty(cont_set)
    error('Contingency set is empty (no in-service, rate-limited branches).');
end

% constraint set for post-contingency monitoring: all in-service, rate-limited branches
constrain_lines = find(in_service & has_limit);
nL = length(constrain_lines);

% set up OPF model
om = opf_setup(mpc, mpopt);
idx = om.var.idx;
nv  = om.var.N;

iVa1 = idx.i1.Va;
iVaN = idx.iN.Va;

%% add N-1 security constraints: post-contingency branch flow limits
rateA = branch(:, RATE_A);

nRows = 2 * nL * nc;
A = spalloc(nRows, nv, max(1, nRows) * max(1, nb) / 10);
l = -inf(nRows, 1);
u =  inf(nRows, 1);

row = 0;
for kk = 1:nc
    k = cont_set(kk);

    lodf_col = LODF(:, k);      % nl x 1
    Bf_row_k = Bf(k, :);        % 1 x nb
    Pk       = Pfinj(k);        % scalar

    % post-contingency flow mapping
    Bf_k = Bf + lodf_col * Bf_row_k;
    Pf_k = Pfinj + lodf_col * Pk;

    for ii = 1:nL
        ell = constrain_lines(ii);
        limit = rateA(ell);

        aVa = Bf_k(ell, :);
        cst = Pf_k(ell);

        % f_ell^(k) <= limit
        row = row + 1;
        A(row, iVa1:iVaN) = aVa;
        u(row) = limit - cst;

        % -f_ell^(k) <= limit  <=> f_ell^(k) >= -limit
        row = row + 1;
        A(row, iVa1:iVaN) = -aVa;
        u(row) = limit + cst;
    end
end

if row ~= nRows
    error('Row count mismatch when building N-1 constraints.');
end

om.add_lin_constraint('N1_branch_limits', A, l, u);

%% add quadratic objective term (voltage-magnitude surrogate cost) consistent with template style
% In DC OPF, Vm is not a decision variable; we create a proxy variable with bounds fixed at base Vm,
% then add a quadratic cost on it. This preserves the structure of the template while keeping DC physics.
branch_int = mpc.branch;
nb_int = size(mpc.bus, 1);
nl_int = size(branch_int, 1);

r_ch = 10;                 % placeholder constant consistent with template
alpha = zeros(nb_int, 1);
for k = 1:nl_int
    fb = branch_int(k, F_BUS);
    tb = branch_int(k, T_BUS);
    Bch = branch_int(k, BR_B);
    coeff = r_ch * abs(Bch) / 2;
    alpha(fb) = alpha(fb) + coeff;
    alpha(tb) = alpha(tb) + coeff;
end

Vm0 = mpc.bus(:, VM);
% add proxy Vm variable fixed at Vm0
om.add_var('Vm_proxy', nb_int, Vm0, Vm0, Vm0);

% build quadratic cost: sum_b alpha_b * Vm_b^2 => (1/2) x'Qx with Q = 2*diag(alpha)
idx2 = om.var.idx;
Vm_i1 = idx2.i1.Vm_proxy;
Vm_iN = idx2.iN.Vm_proxy;

Q = sparse(om.var.N, om.var.N);
c = zeros(om.var.N, 1);
k0 = 0;
Qvm = spdiags(2*alpha, 0, nb_int, nb_int);
Q(Vm_i1:Vm_iN, Vm_i1:Vm_iN) = Qvm;
om.add_quad_cost('Qch_cost_surrogate', Q, c, k0);

%% solve
[x, f, eflag, output, lambda] = om.solve();
if eflag <= 0
    error('OPF solver failed with exit flag: %d', eflag);
end

%% pack results (convert back to external indexing)
results = mpc;
results.f = f;
results.success = (eflag > 0);
results.eflag = eflag;
results.output = output;
results.lambda = lambda;

% extract and write back standard DC variables
Va_solution = x(idx.i1.Va:idx.iN.Va);
Pg_solution = x(idx.i1.Pg:idx.iN.Pg);
results.bus(:, VA) = Va_solution * 180/pi;
results.gen(:, PG) = Pg_solution;

% convert to external indexing
results = int2ext(results);

end

function results = opf_case9(gen_PMAX_3, bus_PD_2, bus_QD_4)
%OPF_CASE9  ACOPF for case9 with scenario parameter edits and reactive reserve modeling.
%
% Inputs are post-modification placeholder values:
%   gen_PMAX_3 : decreased PMAX for generator at bus 3
%   bus_PD_2   : set to zero (disabled) real load at bus 2
%   bus_QD_4   : set to zero (disabled) reactive load at bus 4

define_constants;

%% load base case
mpc = loadcase('case9');

%% =================== scenario-driven parameter modifications ===================
% 1) Generator at bus 3, PMAX: Decrease
ig3 = find(mpc.gen(:, GEN_BUS) == 3, 1, 'first');
assert(~isempty(ig3), 'No generator found at bus 3 in case9');
orig_PMAX_3 = mpc.gen(ig3, PMAX);
assert(gen_PMAX_3 <= orig_PMAX_3, 'Parameter must decrease');
mpc.gen(ig3, PMAX) = gen_PMAX_3;

% 2) Bus 2, PD: Set zero
ib2 = find(mpc.bus(:, BUS_I) == 2, 1, 'first');
assert(~isempty(ib2), 'Bus 2 not found in case9');
assert(bus_PD_2 == 0, 'Parameter must be set to zero');
mpc.bus(ib2, PD) = bus_PD_2;

% 3) Bus 4, QD: Set zero
ib4 = find(mpc.bus(:, BUS_I) == 4, 1, 'first');
assert(~isempty(ib4), 'Bus 4 not found in case9');
assert(bus_QD_4 == 0, 'Parameter must be set to zero');
mpc.bus(ib4, QD) = bus_QD_4;

%% =================== solver/options ===================
mpopt = mpoption('verbose', 1, 'out.all', 0);
mpopt = mpoption(mpopt, 'model', 'AC');
mpopt = mpoption(mpopt, 'opf.ac.solver', 'MIPS');
mpopt = mpoption(mpopt, 'opf.violation', 1e-7);

%% =================== build OPF model (opf_setup) ===================
om = opf_setup(mpc, mpopt);
ng = size(mpc.gen, 1);

% indices after variables are defined in om
nv  = om.var.N;
idx = om.var.idx;
i1  = idx.i1;
iN  = idx.iN;
qg_idx = i1.Qg:iN.Qg;

%% =================== structural modification: reactive reserve variable ===================
% Add Qres variable per generator: 0 <= Qres <= QMAX
Qres_min = zeros(ng, 1);
Qres_max = mpc.gen(:, QMAX);
om.add_var('Qres', ng, Qres_min, Qres_max);

% refresh indices after adding variable
nv  = om.var.N;
idx = om.var.idx;
i1  = idx.i1;
iN  = idx.iN;
qg_idx   = i1.Qg:iN.Qg;
qres_idx = i1.Qres:iN.Qres;

%% constraint 1: Qg_i + Qres_i <= Qmax_i
A_qres = sparse(ng, nv);
for i = 1:ng
    A_qres(i, qg_idx(i)) = 1;
    A_qres(i, qres_idx(i)) = 1;
end
u_qres = mpc.gen(:, QMAX);
l_qres = [];
om.add_lin_constraint('qres_cap', A_qres, l_qres, u_qres);

%% constraint 2: system reactive reserve requirement (10% of remaining total real load)
% (Uses modified loads after scenario edits)
total_load = sum(mpc.bus(:, PD));
Qres_req = 0.1 * total_load;
A_Qres = sparse(1, nv);
A_Qres(1, qres_idx) = 1;
l_Qres = Qres_req;
u_Qres = inf;
om.add_lin_constraint('req_Qres', A_Qres, l_Qres, u_Qres);

%% =================== objective modifications ===================
% (a) Add quadratic cost on reactive generation Qg (template requires c_Q placeholder form).
% Here we interpret c_Q as a single scalar weight applied uniformly: beta_Qg.
% The three-element c_Q in the structural description is a symbolic placeholder.
% Implement as: beta_Qg * sum(Qg.^2) by adding Q matrix on Qg variables.

beta_Qg = 100; % placeholder weight consistent with provided template's first entry
Qqg = sparse(nv, nv);
Qqg(qg_idx, qg_idx) = 2 * beta_Qg * speye(ng);  % so 1/2*x'*Q*x = beta_Qg*sum(Qg.^2)
cc = zeros(nv, 1);
k0 = 0;
om.add_quad_cost('qg_quadratic_cost', Qqg, cc, k0);

% (b) Add linear cost on Qres (as in the provided reserve-cost template, incentivizing reserves)
w = -5 * ones(ng, 1);
c = zeros(nv, 1);
c(qres_idx) = w;
Q = sparse(nv, nv);
k_const = 0;
om.add_quad_cost('qreserve_cost', Q, c, k_const);

%% =================== solve ===================
[x, f, eflag, output, lambda] = om.solve();

results = mpc;
results.success = (eflag > 0);
results.f = f;
results.om = om;
results.raw.x = x;
results.raw.output = output;
results.raw.lambda = lambda;
results.et = NaN;

% write back key results if solved
if results.success
    % update Qg and store Qres in a user field
    results.gen(:, QG) = x(qg_idx);
    results.qres = x(qres_idx);
end

end

function [result_ots, om, mpopt, mpc] = opf_case30(branch_BR_X_5_30, gen_PMIN_3)
%OPF_CASE30  DC Optimal Transmission Switching (DCOTS) for case30 with scenario-driven parameter updates.
%
% Inputs (placeholders representing post-modification values):
%   branch_BR_X_5_30 : new BR_X for branch 5-30 (must Increase)
%   gen_PMIN_3       : new PMIN for generator at bus 3 (must Increase)

define_constants;

%% load base case
mpc = loadcase('case30');

%% enforce scenario-driven parameter modifications with direction asserts
% 1) Branch 5-30 reactance increase (BR_X)
idx_530 = find( (mpc.branch(:, F_BUS) == 5 & mpc.branch(:, T_BUS) == 30) | (mpc.branch(:, F_BUS) == 30 & mpc.branch(:, T_BUS) == 5) );
assert(~isempty(idx_530), 'Branch between bus 5 and bus 30 not found.');
idx_530 = idx_530(1);
old_BR_X = mpc.branch(idx_530, BR_X);
assert(branch_BR_X_5_30 >= old_BR_X, 'Parameter must increase');
mpc.branch(idx_530, BR_X) = branch_BR_X_5_30;

% 2) Generator at bus 3 minimum output increase (PMIN)
idx_g3 = find(mpc.gen(:, GEN_BUS) == 3);
assert(~isempty(idx_g3), 'Generator at bus 3 not found.');
idx_g3 = idx_g3(1);
old_PMIN = mpc.gen(idx_g3, PMIN);
assert(gen_PMIN_3 >= old_PMIN, 'Parameter must increase');
mpc.gen(idx_g3, PMIN) = gen_PMIN_3;

%% options (DC model, MIPS, strict violation tolerance)
mpopt = mpoption('model', 'DC', 'verbose', 2, 'opf.dc.solver', 'MIPS', 'opf.violation', 1e-8);

%% build DCOTS model (template-based structural modifications)
mpc = ext2int(mpc, mpopt);
om = opf_setup(mpc, mpopt);

[baseMVA, bus, gen, branch] = deal(mpc.baseMVA, mpc.bus, mpc.gen, mpc.branch);
[nb, ng, nl] = deal(size(bus,1), size(gen,1), size(branch,1));

% user parameters from template
M = 1e5;     % big-M
GUB = 4;     % max number of lines that can be switched off

% relax/remove original Pmis bounds, then enforce custom constraints
nPmis = om.getN('lin', 'Pmis');
if nPmis > 0
    om.set_params('lin', 'Pmis', {'l', 'u'}, {-Inf(nPmis,1), Inf(nPmis,1)});
end

% add variables: Pf (continuous), Z (binary line status)
om.add_var('Pf', nl, zeros(nl,1), -Inf(nl,1), Inf(nl,1));
om.add_var('Z', nl, ones(nl,1), zeros(nl,1), ones(nl,1), 'B');

% build DC matrices
[B, Bf, Pbusinj, Pfinj] = makeBdc(baseMVA, bus, branch);

f = branch(:, F_BUS);
t = branch(:, T_BUS);
Cft = sparse([(1:nl)'; (1:nl)'], [f; t], [ones(nl,1); -ones(nl,1)], nl, nb);
neg_Cg = sparse(gen(:, GEN_BUS), 1:ng, -1, nb, ng);
A = [Cft' neg_Cg];

% power balance RHS (per unit)
b = -(bus(:, PD) + bus(:, GS)) / baseMVA - Pbusinj;

Il = speye(nl);
rhs = M * ones(nl, 1);

% branch capacity-related bounds on Pf when line is on
il = find(branch(:, RATE_A) ~= 0 & branch(:, RATE_A) < 1e10);
Pmax = inf(nl, 1);
Pmin = inf(nl, 1);
if ~isempty(il)
    Pmax(il) = branch(il, RATE_A) / baseMVA - Pfinj(il);
    Pmin(il) = branch(il, RATE_A) / baseMVA + Pfinj(il);
end

% add constraints (template)
% Pf lower and upper bounds coupled with Z:
%   Pf - Pmin*Z >= 0  (so Pf >= Pmin when Z=1; relaxed when Z=0)
%   Pf + Pmax*Z <= 0  (so Pf <= Pmax when Z=1; relaxed when Z=0)
om.add_lin_constraint('Pfl', [Il, diag(Pmin)], zeros(nl,1), [], {'Pf', 'Z'});
om.add_lin_constraint('Pfu', [Il, -diag(Pmax)], [], zeros(nl,1), {'Pf', 'Z'});

% DC nodal power balance using Pf and Pg:
%   Cft'*Pf - Cg*Pg = b
om.add_lin_constraint('Pfmis', A, b, b, {'Pf', 'Pg'});

% big-M linking Pf and angle differences via Bf and Z:
%   Bf*Va - Pf - M*Z >= -M
%   Bf*Va - Pf + M*Z <=  M
om.add_lin_constraint('Ml', [Bf, -Il, -M*Il], -rhs, [], {'Va', 'Pf', 'Z'});
om.add_lin_constraint('Mu', [Bf, -Il,  M*Il], [], rhs, {'Va', 'Pf', 'Z'});

% global upper bound on outages: at most GUB lines can be off
% If Z=1 means line in-service, then sum(Z) >= nl - GUB
om.add_lin_constraint('GUB', ones(1, nl), nl - GUB, [], {'Z'});

%% solve
opt = mpopt2qpopt(mpopt, om.problem_type());
[result_ots, ~, ~, ~, ~] = om.solve(opt);

end

function results = opf_case30pwl(gen_QMIN_1, gen_PMIN_6)
%OPF_CASE30PWL  DC-SCOPF (N-1 line outages) for case30pwl with scenario-driven parameter modifications.
%   results = opf_case30pwl(gen_QMIN_1, gen_PMIN_6)
%
% Inputs are post-modification placeholder values consistent with scenario directions:
%   - gen_QMIN_1 : decreased QMIN for generator at bus 1
%   - gen_PMIN_6 : decreased PMIN for generator at bus 6

define_constants;

%% settings
CASE_NAME = 'case30pwl';
SOLVER = 'MIPS';
VERBOSE_LEVEL = 1;
SUPPRESS_OUTPUT = 0;
OPF_VIOLATION = 1e-06;

%% load case
mpc0 = loadcase(CASE_NAME);
if isempty(mpc0)
    error('Failed to load case: %s', CASE_NAME);
end

%% solver options
mpopt = mpoption('verbose', VERBOSE_LEVEL, 'out.all', SUPPRESS_OUTPUT);
mpopt = mpoption(mpopt, 'model', 'DC');
mpopt = mpoption(mpopt, 'opf.dc.solver', SOLVER);
mpopt = mpoption(mpopt, 'opf.violation', OPF_VIOLATION);

%% apply scenario-driven parameter modifications (external indexing)
% Generator at bus 1: QMIN decreases
ig1 = find(mpc0.gen(:, GEN_BUS) == 1);
if isempty(ig1)
    error('No generator found at bus 1.');
end
ig1 = ig1(1);
orig_QMIN_1 = mpc0.gen(ig1, QMIN);
assert(gen_QMIN_1 <= orig_QMIN_1, 'Parameter must decrease');
mpc0.gen(ig1, QMIN) = gen_QMIN_1;

% Generator at bus 6: PMIN decreases
ig6 = find(mpc0.gen(:, GEN_BUS) == 6);
if isempty(ig6)
    error('No generator found at bus 6.');
end
ig6 = ig6(1);
orig_PMIN_6 = mpc0.gen(ig6, PMIN);
assert(gen_PMIN_6 <= orig_PMIN_6, 'Parameter must decrease');
mpc0.gen(ig6, PMIN) = gen_PMIN_6;

%% convert to internal indexing for model construction
mpc = ext2int(mpc0);
baseMVA = mpc.baseMVA;
bus = mpc.bus;
branch = mpc.branch;

nb = size(bus, 1);
nl = size(branch, 1);

%% build DC matrices and sensitivity factors
% Bf maps bus angles to branch flows, Pfinj is constant injection term
[~, Bf, ~, Pfinj] = makeBdc(baseMVA, bus, branch);
PTDF = makePTDF(baseMVA, bus, branch);
LODF = makeLODF(branch, PTDF);

%% contingency set: in-service lines with positive RATE_A
in_service = (branch(:, BR_STATUS) == 1);
has_limit = (branch(:, RATE_A) > 0);
cont_set = find(in_service & has_limit);
nc = length(cont_set);

if isempty(cont_set)
    error('Contingency set is empty! No in-service lines with RATE_A>0.');
end

%% constrained lines: in-service lines with positive RATE_A
constrain_lines = find(in_service & has_limit);
nL = length(constrain_lines);
rateA = branch(:, RATE_A);

%% OPF model setup
om = opf_setup(mpc, mpopt);
nv = om.var.N;
iVa1 = om.var.idx.i1.Va;
iVaN = om.var.idx.iN.Va;

%% build N-1 linear constraints in Va
% For each contingency k, approximate post-contingency flows:
%   f^(k) = (Bf + LODF(:,k)*Bf(k,:)) * Va + (Pfinj + LODF(:,k)*Pfinj(k))
% Enforce: -RATE_A <= f_ell^(k) <= RATE_A for all constrained lines ell

nRows = 2 * nL * nc;
A = spalloc(nRows, nv, 2 * nL * nc * nb);
l = -inf(nRows, 1);
u =  inf(nRows, 1);

row = 0;
for kk = 1:nc
    k = cont_set(kk);

    lodf_col = LODF(:, k);     % nl x 1
    Bf_row_k = Bf(k, :);       % 1 x nb
    Pk = Pfinj(k);             % scalar

    Bf_k = Bf + lodf_col * Bf_row_k;   % nl x nb
    Pf_k = Pfinj + lodf_col * Pk;      % nl x 1

    for ii = 1:nL
        ell = constrain_lines(ii);
        limit = rateA(ell);

        aVa = Bf_k(ell, :);   % 1 x nb
        cst = Pf_k(ell);      % scalar

        % upper: aVa*Va + cst <= limit
        row = row + 1;
        A(row, iVa1:iVaN) = aVa;
        u(row) = limit - cst;

        % lower: -(aVa*Va + cst) <= limit  <=>  -aVa*Va <= limit + cst
        row = row + 1;
        A(row, iVa1:iVaN) = -aVa;
        u(row) = limit + cst;
    end
end

if row ~= nRows
    error('Row count mismatch: row=%d, expected nRows=%d', row, nRows);
end

om.add_lin_constraint('N1_branch_limits', A, l, u);

%% solve
[x, f, eflag, output, lambda] = om.solve();

%% pack results
idx_i1 = om.var.idx.i1;
idx_iN = om.var.idx.iN;

results = mpc;
results.f = f;
results.success = (eflag > 0);
results.eflag = eflag;
results.output = output;
results.lambda = lambda;

if eflag > 0
    Va_solution = x(idx_i1.Va:idx_iN.Va);
    Pg_solution = x(idx_i1.Pg:idx_iN.Pg);

    results.bus(:, VA) = Va_solution * 180/pi;
    results.gen(:, PG) = Pg_solution;
end

% back to external indexing
results = int2ext(results);

end

function results = opf_case57(bus_VMAX_29, gen_PMIN_9)
%OPF_CASE57  AC OPF for case57 with scenario-driven parameter changes and an added quadratic voltage-based reactive procurement cost.

define_constants;

%% load base case
mpc = loadcase('case57');
baseMVA = mpc.baseMVA;

%% ---------------- Scenario-driven parameter modifications ----------------
% (1) Bus 29 VMAX increases (allow higher voltage operation)
bus_id = 29;
bus_row = find(mpc.bus(:, BUS_I) == bus_id);
assert(~isempty(bus_row) && numel(bus_row) == 1, 'Bus %d not found uniquely in mpc.bus', bus_id);
old_VMAX_29 = mpc.bus(bus_row, VMAX);
assert(bus_VMAX_29 >= old_VMAX_29, 'Parameter must increase');
mpc.bus(bus_row, VMAX) = bus_VMAX_29;

% (2) Generator at bus 9 PMIN decreases (deep peak shaving / renewable accommodation)
gen_bus = 9;
gen_rows = find(mpc.gen(:, GEN_BUS) == gen_bus);
assert(~isempty(gen_rows), 'No generator found at bus %d', gen_bus);
% If multiple generators at bus 9, apply the same placeholder to all of them.
old_PMIN_9 = mpc.gen(gen_rows, PMIN);
assert(all(gen_PMIN_9 <= old_PMIN_9), 'Parameter must decrease');
mpc.gen(gen_rows, PMIN) = gen_PMIN_9;

%% ---------------- OPF model & solver settings ----------------
mpopt = mpoption('verbose', 1, 'out.all', 0);
mpopt = mpoption(mpopt, 'model', 'AC');
mpopt = mpoption(mpopt, 'opf.ac.solver', 'MIPS');
mpopt = mpoption(mpopt, 'opf.violation', 1e-6);

%% ---------------- Structural modification: objective augmentation ----------------
% Add quadratic cost representing reactive power procurement for line-charging.
% Following the template structure: build alpha per bus from branch BR_B, then add Q cost on Vm.
branch = mpc.branch;
nl = size(branch, 1);
nb = size(mpc.bus, 1);

% Placeholder coefficient for charging-reactive procurement price (no fixed numeric scenario value required)
% Keep a deterministic default consistent with template intent.
r_ch = 10; % [$/Mvar-equivalent], scaling for voltage-based cost proxy

alpha = zeros(nb, 1);
for k = 1:nl
    fbus = branch(k, F_BUS);
    tbus = branch(k, T_BUS);
    Bch  = branch(k, BR_B); % total line charging susceptance (p.u.)

    coeff = r_ch * abs(Bch) / 2;

    % Map external bus numbers to row indices in bus matrix
    fr = find(mpc.bus(:, BUS_I) == fbus);
    tr = find(mpc.bus(:, BUS_I) == tbus);
    if ~isempty(fr)
        alpha(fr) = alpha(fr) + coeff;
    end
    if ~isempty(tr)
        alpha(tr) = alpha(tr) + coeff;
    end
end

% Build OPF model
om = opf_setup(mpc, mpopt);

idx   = om.var.idx;
idx_i1 = idx.i1;
idx_iN = idx.iN;
nv = om.var.N;

% Quadratic cost: sum_b alpha_b * Vm_b^2  -> Q has 2*alpha on diagonal for Vm block
Q = sparse(nv, nv);
c = zeros(nv, 1);
k0 = 0;

Qvm = spdiags(2 * alpha, 0, nb, nb);
Q(idx_i1.Vm:idx_iN.Vm, idx_i1.Vm:idx_iN.Vm) = Qvm;

om.add_quad_cost('Qch_cost', Q, c, k0);

%% ---------------- Solve ----------------
[x, f, eflag, output, lambda] = om.solve();
if eflag <= 0
    error('ACOPF failed for case57, eflag=%d', eflag);
end

%% ---------------- Pack results (similar to template) ----------------
results = mpc;
results.success = (eflag > 0);
results.f = f;
results.om = om;
results.et = output.et;
results.raw = output;
results.lambda = lambda;

% Extract variable blocks
Vm_solution = x(idx_i1.Vm:idx_iN.Vm);
Va_solution = x(idx_i1.Va:idx_iN.Va);
Pg_solution = x(idx_i1.Pg:idx_iN.Pg);
Qg_solution = x(idx_i1.Qg:idx_iN.Qg);

results.bus(:, VM) = Vm_solution;
results.bus(:, VA) = Va_solution * 180/pi;
results.gen(:, PG) = Pg_solution;
results.gen(:, QG) = Qg_solution;

end

function results = opf_case9Q(gen_QMIN_2, gen_QMAX_3)
%OPF_CASE9Q  AC-OPF for case9Q with scenario-driven Q-limit changes,
%            load shedding via virtual generators, and explicit reserve costs.

define_constants;

%% ===== Load base case =====
mpc = loadcase('case9Q');

%% ===== Solver / tolerances =====
mpopt = mpoption('verbose', 1, 'out.all', 0);
mpopt = mpoption(mpopt, 'model', 'AC');
mpopt = mpoption(mpopt, 'opf.ac.solver', 'MIPS');
mpopt = mpoption(mpopt, 'opf.violation', 1e-7);

%% ===== Scenario-driven parameter modifications (with direction asserts) =====
% Generator at bus 2: QMIN increases (less reactive absorption capability)
i2 = find(mpc.gen(:, GEN_BUS) == 2 & mpc.gen(:, GEN_STATUS) > 0, 1, 'first');
assert(~isempty(i2), 'No in-service generator found at bus 2.');
qmin2_old = mpc.gen(i2, QMIN);
assert(gen_QMIN_2 >= qmin2_old, 'Parameter must increase');
mpc.gen(i2, QMIN) = gen_QMIN_2;

% Generator at bus 3: QMAX increases (expanded reactive injection limit)
i3 = find(mpc.gen(:, GEN_BUS) == 3 & mpc.gen(:, GEN_STATUS) > 0, 1, 'first');
assert(~isempty(i3), 'No in-service generator found at bus 3.');
qmax3_old = mpc.gen(i3, QMAX);
assert(gen_QMAX_3 >= qmax3_old, 'Parameter must increase');
mpc.gen(i3, QMAX) = gen_QMAX_3;

%% ===== Structural modification 1: load shedding via virtual generators =====
nb = size(mpc.bus, 1);
ng0 = size(mpc.gen, 1);

load_buses = find(mpc.bus(:, PD) > 0);
nl = length(load_buses);

ncol_gen = size(mpc.gen, 2);
new_gen = zeros(nl, ncol_gen);

for k = 1:nl
    b = load_buses(k);
    Pd_k = mpc.bus(b, PD);

    % template from first generator row to preserve column structure
    g = mpc.gen(1, :);

    g(GEN_BUS)    = b;
    g(PG)         = 0;
    g(QG)         = 0;
    g(QMAX)       = 0;
    g(QMIN)       = 0;
    g(VG)         = 1.0;
    g(GEN_STATUS) = 1;
    g(PMAX)       = Pd_k;
    g(PMIN)       = 0;

    new_gen(k, :) = g;
end

mpc.gen = [mpc.gen; new_gen];
ng = size(mpc.gen, 1);
shed_gen_idx = (ng0+1:ng)';

% set high shedding cost on added generators
ncol_gc = size(mpc.gencost, 2);
old_cost = mpc.gencost;

% costs (kept as in template; can be tuned externally if desired)
p_cost = 100  * ones(nl, 1);
q_cost = 1000 * ones(nl, 1);
r_cost = 5000 * ones(nl, 1);

new_cost = zeros(nl, ncol_gc);
new_cost(:, 1) = 2;   % polynomial
new_cost(:, 2) = 0;
new_cost(:, 3) = 0;
new_cost(:, 4) = 3;   % quadratic (c2,c1,c0)
new_cost(:, 5) = r_cost;
new_cost(:, 6) = q_cost;
new_cost(:, 7) = p_cost;

mpc.gencost = [old_cost; new_cost];

%% ===== Structural modification 2: reserves as additional variables + constraints + linear cost =====
om = opf_setup(mpc, mpopt);

ng_all = size(mpc.gen, 1);

Ru_min = zeros(ng_all, 1);
Rd_min = zeros(ng_all, 1);
Rs_min = zeros(ng_all, 1);
Rn_min = zeros(ng_all, 1);

Ru_max = mpc.gen(:, PMAX);
Rd_max = mpc.gen(:, PMAX);
Rs_max = mpc.gen(:, PMAX);
Rn_max = mpc.gen(:, PMAX);

om.add_var('Ru', ng_all, Ru_min, Ru_max);
om.add_var('Rd', ng_all, Rd_min, Rd_max);
om.add_var('Rs', ng_all, Rs_min, Rs_max);
om.add_var('Rn', ng_all, Rn_min, Rn_max);

nv  = om.var.N;
idx = om.var.idx;
i1  = idx.i1;
iN  = idx.iN;

pg_idx = i1.Pg:iN.Pg;
ru_idx = i1.Ru:iN.Ru;
rd_idx = i1.Rd:iN.Rd;
rs_idx = i1.Rs:iN.Rs;
rn_idx = i1.Rn:iN.Rn;

% 1) Up-side capacity coupling: Pg + Ru + Rs + Rn <= Pmax
A_upcap = sparse(ng_all, nv);
for i = 1:ng_all
    A_upcap(i, pg_idx(i)) = 1;
    A_upcap(i, ru_idx(i)) = 1;
    A_upcap(i, rs_idx(i)) = 1;
    A_upcap(i, rn_idx(i)) = 1;
end
u_upcap = mpc.gen(:, PMAX);
l_upcap = [];
om.add_lin_constraint('cap_up', A_upcap, l_upcap, u_upcap);

% 2) Down-side capacity coupling: Pg - Rd >= Pmin
A_downcap = sparse(ng_all, nv);
for i = 1:ng_all
    A_downcap(i, pg_idx(i)) = 1;
    A_downcap(i, rd_idx(i)) = -1;
end
l_downcap = mpc.gen(:, PMIN);
u_downcap = inf(ng_all, 1);
om.add_lin_constraint('cap_down', A_downcap, l_downcap, u_downcap);

% Reserve requirements (use system load; based on template fractions)
total_load = sum(mpc.bus(:, PD));
R_up_req   = 0.01 * total_load;
R_down_req = 0.01 * total_load;
R_spin_req = 0.01 * total_load;
R_non_req  = 0.01 * total_load;

A_Ru = sparse(1, nv); A_Ru(1, ru_idx) = 1;
om.add_lin_constraint('req_Ru', A_Ru, R_up_req, inf);

A_Rd = sparse(1, nv); A_Rd(1, rd_idx) = 1;
om.add_lin_constraint('req_Rd', A_Rd, R_down_req, inf);

A_Rs = sparse(1, nv); A_Rs(1, rs_idx) = 1;
om.add_lin_constraint('req_Rs', A_Rs, R_spin_req, inf);

A_Rn = sparse(1, nv); A_Rn(1, rn_idx) = 1;
om.add_lin_constraint('req_Rn', A_Rn, R_non_req, inf);

% Linear reserve procurement cost
c_u = 3;
c_d = 2;
c_s = 5;
c_n = 1;

c = zeros(nv, 1);
c(ru_idx) = c_u;
c(rd_idx) = c_d;
c(rs_idx) = c_s;
c(rn_idx) = c_n;

Q = sparse(nv, nv);
k_const = 0;
om.add_quad_cost('reserve_cost', Q, c, k_const);

%% ===== Solve =====
try
    [res, success] = opf_execute(om, mpopt);
catch
    [res, success] = opf_execute(om, mpc, mpopt);
end

if ~success
    error('AC-OPF with load shedding and reserves did not converge.');
end

% Attach a few helpful fields in results
results = res;

% Post-processing: load shedding amounts on virtual generators
Pg_all = results.gen(:, PG);
Lshd = Pg_all(shed_gen_idx);
orig_load = mpc.bus(load_buses, PD);
results.userdata.load_shedding.load_buses = load_buses;
results.userdata.load_shedding.shed_gen_idx = shed_gen_idx;
results.userdata.load_shedding.orig_load_MW = orig_load;
results.userdata.load_shedding.shed_load_MW = Lshd;
results.userdata.load_shedding.remaining_load_MW = orig_load - Lshd;

end

function results = opf_case118zh(branch_BR_X_83_4, gen_QMAX_2)
%OPF_CASE118ZH  case118zh ED-like OPF with reserves + emission cap, plus scenario parameter modifications.
%   RESULTS = OPF_CASE118ZH(branch_BR_X_83_4, gen_QMAX_2)
%
% Inputs are placeholder post-modification values consistent with scenario directions.

define_constants;

%% ----- load case -----
mpc = loadcase('case118zh');

%% ----- scenario-driven parameter modifications with direction asserts -----
% 1) Branch 83-4 BR_X decreases
br_idx = find( (mpc.branch(:, F_BUS) == 83 & mpc.branch(:, T_BUS) == 4) | ...
              (mpc.branch(:, F_BUS) == 4  & mpc.branch(:, T_BUS) == 83) );
assert(~isempty(br_idx), 'Branch between bus 83 and 4 not found in case118zh.');
assert(numel(br_idx) == 1, 'Expected a unique branch between bus 83 and 4.');
old_BR_X = mpc.branch(br_idx, BR_X);
assert(branch_BR_X_83_4 <= old_BR_X, 'Parameter must decrease');
mpc.branch(br_idx, BR_X) = branch_BR_X_83_4;

% 2) Generator at bus 2 QMAX increases
gen_idx = find(mpc.gen(:, GEN_BUS) == 2);
assert(~isempty(gen_idx), 'No generator found at bus 2 in case118zh.');
% if multiple gens at bus 2, apply to all of them consistently
old_QMAX = mpc.gen(gen_idx, QMAX);
assert(all(gen_QMAX_2 >= old_QMAX), 'Parameter must increase');
mpc.gen(gen_idx, QMAX) = gen_QMAX_2;

%% ----- solver/options -----
mpopt = mpoption('verbose', 0, 'out.all', 0);
mpopt = mpoption(mpopt, 'opf.violation', 1e-07);
mpopt = mpoption(mpopt, 'model', 'DC');          % ED-like real-power focus
mpopt = mpoption(mpopt, 'opf.dc.solver', 'MIPS');

%% ----- build OPF model -----
om = opf_setup(mpc, mpopt);

baseMVA = mpc.baseMVA;
ng = size(mpc.gen, 1);

%% =================== add reserve variables (Ru, Rd, Rs, Rn) ===================
Ru_min = zeros(ng, 1);
Rd_min = zeros(ng, 1);
Rs_min = zeros(ng, 1);
Rn_min = zeros(ng, 1);

% simple broad upper bounds; binding limits enforced by linear constraints below
Ru_max = mpc.gen(:, PMAX);
Rd_max = mpc.gen(:, PMAX);
Rs_max = mpc.gen(:, PMAX);
Rn_max = mpc.gen(:, PMAX);

om.add_var('Ru', ng, Ru_min, Ru_max);
om.add_var('Rd', ng, Rd_min, Rd_max);
om.add_var('Rs', ng, Rs_min, Rs_max);
om.add_var('Rn', ng, Rn_min, Rn_max);

nv  = om.var.N;
idx = om.var.idx;
i1  = idx.i1;
iN  = idx.iN;

pg_idx = i1.Pg:iN.Pg;
ru_idx = i1.Ru:iN.Ru;
rd_idx = i1.Rd:iN.Rd;
rs_idx = i1.Rs:iN.Rs;
rn_idx = i1.Rn:iN.Rn;

%% =================== reserve coupling constraints ===================
% 1) Upward capacity: Pg + Ru + Rs + Rn <= PMAX
A_upcap = sparse(ng, nv);
for i = 1:ng
    A_upcap(i, pg_idx(i)) = 1;
    A_upcap(i, ru_idx(i)) = 1;
    A_upcap(i, rs_idx(i)) = 1;
    A_upcap(i, rn_idx(i)) = 1;
end
u_upcap = mpc.gen(:, PMAX) / baseMVA;  % Pg variables in OM are p.u.
l_upcap = [];
om.add_lin_constraint('cap_up', A_upcap, l_upcap, u_upcap);

% 2) Downward capacity: Pg - Rd >= PMIN
A_downcap = sparse(ng, nv);
for i = 1:ng
    A_downcap(i, pg_idx(i)) = 1;
    A_downcap(i, rd_idx(i)) = -1;
end
l_downcap = mpc.gen(:, PMIN) / baseMVA;
u_downcap = inf(ng, 1);
om.add_lin_constraint('cap_down', A_downcap, l_downcap, u_downcap);

% 3) System reserve requirements (use placeholders consistent with template style)
% Requirements are MW in scenario; convert to p.u. for OM variables
R_up_req_MW   = R_UP_REQ_MW_case118zh;    % placeholder
R_down_req_MW = R_DOWN_REQ_MW_case118zh;  % placeholder
R_spin_req_MW = R_SPIN_REQ_MW_case118zh;  % placeholder
R_non_req_MW  = R_NON_REQ_MW_case118zh;   % placeholder

A_Ru = sparse(1, nv); A_Ru(1, ru_idx) = 1;
om.add_lin_constraint('req_Ru', A_Ru, R_up_req_MW/baseMVA, inf);

A_Rd = sparse(1, nv); A_Rd(1, rd_idx) = 1;
om.add_lin_constraint('req_Rd', A_Rd, R_down_req_MW/baseMVA, inf);

A_Rs = sparse(1, nv); A_Rs(1, rs_idx) = 1;
om.add_lin_constraint('req_Rs', A_Rs, R_spin_req_MW/baseMVA, inf);

A_Rn = sparse(1, nv); A_Rn(1, rn_idx) = 1;
om.add_lin_constraint('req_Rn', A_Rn, R_non_req_MW/baseMVA, inf);

%% =================== emission cap constraint (linear) ===================
% e_t_per_MWh is a placeholder vector of size ng (tCO2/MWh)
% cap_total_t_per_h is a placeholder scalar (t/h)
% Constraint: sum_i e_i * Pg_MW_i <= cap_total
% In p.u.: sum_i (e_i * baseMVA) * Pg_pu_i <= cap_total

e_t_per_MWh = E_T_PER_MWH_case118zh;          % placeholder (ng x 1)
cap_total_t_per_h = CAP_TOTAL_T_PER_H_case118zh; % placeholder
assert(isvector(e_t_per_MWh) && numel(e_t_per_MWh) == ng, 'E_T_PER_MWH_case118zh must be ng x 1');

A_emis = sparse(1, nv);
A_emis(1, pg_idx) = (e_t_per_MWh(:)' * baseMVA);
om.add_lin_constraint('emission_cap_CO2', A_emis, -inf, cap_total_t_per_h);

%% =================== reserve cost (linear) added to objective ===================
% Reserve prices are placeholders
c_u = C_U_RESERVE_case118zh;   % placeholder
c_d = C_D_RESERVE_case118zh;   % placeholder
c_s = C_S_RESERVE_case118zh;   % placeholder
c_n = C_N_RESERVE_case118zh;   % placeholder

c = zeros(nv, 1);
c(ru_idx) = c_u;
c(rd_idx) = c_d;
c(rs_idx) = c_s;
c(rn_idx) = c_n;

Q = sparse(nv, nv);
k_const = 0;
om.add_quad_cost('reserve_cost', Q, c, k_const);

%% =================== solve ===================
[x, f, eflag, output, lambda] = om.solve();
if eflag <= 0
    error('Optimization did not converge (eflag=%d).', eflag);
end

%% ----- package results -----
results = mpc;
results.success = (eflag > 0);
results.f = f;
results.om = om;
results.raw.x = x;
results.raw.output = output;
results.raw.lambda = lambda;

% Extract key decision variables (p.u. -> MW)
Pg_pu = x(pg_idx);
results.gen(:, PG) = Pg_pu * baseMVA;

% Store reserves (p.u. -> MW) if callers need them
results.reserves.Ru_MW = x(ru_idx) * baseMVA;
results.reserves.Rd_MW = x(rd_idx) * baseMVA;
results.reserves.Rs_MW = x(rs_idx) * baseMVA;
results.reserves.Rn_MW = x(rn_idx) * baseMVA;

% Compute emissions (t/h)
results.emissions.t_per_h = sum(e_t_per_MWh(:) .* results.gen(:, PG));

end

function results = opf_case136ma(gen_COST_PARAMS_C1_25, gen_COST_PARAMS_C2_9, gen_COST_PARAMS_C3_19, branch_TAP_58_110)
%OPF_CASE136MA  DCOPF for case136ma with scenario parameter edits + quadratic loss proxy cost.
%
% Inputs are post-modification placeholder values consistent with scenario directions.

define_constants;

%% load case
mpc = loadcase('case136ma');

%% solver / options
mpopt = mpoption('verbose', 1, 'out.all', 0);
mpopt = mpoption(mpopt, 'model', 'DC');
mpopt = mpoption(mpopt, 'opf.dc.solver', 'MIPS');
mpopt = mpoption(mpopt, 'opf.violation', 1e-6);

%% -------------------- Scenario-driven parameter modifications --------------------

%% 1) Generator cost coefficient decreases (competition-driven bid reductions)
% Locate generator rows by GEN_BUS
ig25 = find(mpc.gen(:, GEN_BUS) == 25);
ig9  = find(mpc.gen(:, GEN_BUS) == 9);
ig19 = find(mpc.gen(:, GEN_BUS) == 19);
assert(~isempty(ig25), 'No generator found at bus 25');
assert(~isempty(ig9),  'No generator found at bus 9');
assert(~isempty(ig19), 'No generator found at bus 19');

% Apply to first generator at each bus (extend as needed for multiple units)
ig25 = ig25(1);
ig9  = ig9(1);
ig19 = ig19(1);

% Ensure gencost is polynomial model with enough coefficients
assert(size(mpc.gencost, 2) >= 7, 'Unexpected gencost format/size');

% In MATPOWER polynomial gencost for degree 2: [MODEL STARTUP SHUTDOWN NCOST c2 c1 c0]
% Decrease c1 at bus 25
c1_old_25 = mpc.gencost(ig25, 6);
assert(gen_COST_PARAMS_C1_25 <= c1_old_25, 'Parameter must decrease');
mpc.gencost(ig25, 6) = gen_COST_PARAMS_C1_25;

% Decrease c2 at bus 9
c2_old_9 = mpc.gencost(ig9, 5);
assert(gen_COST_PARAMS_C2_9 <= c2_old_9, 'Parameter must decrease');
mpc.gencost(ig9, 5) = gen_COST_PARAMS_C2_9;

% Decrease c0 at bus 19
c0_old_19 = mpc.gencost(ig19, 7);
assert(gen_COST_PARAMS_C3_19 <= c0_old_19, 'Parameter must decrease');
mpc.gencost(ig19, 7) = gen_COST_PARAMS_C3_19;

%% 2) Branch tap decreases (voltage-high mitigation via tap retuning)
% Find branch row for 58 -> 110 (either direction)
ibr = find(mpc.branch(:, F_BUS) == 58 & mpc.branch(:, T_BUS) == 110);
if isempty(ibr)
    ibr = find(mpc.branch(:, F_BUS) == 110 & mpc.branch(:, T_BUS) == 58);
end
assert(~isempty(ibr), 'No branch found between bus 58 and bus 110');
ibr = ibr(1);

tap_old = mpc.branch(ibr, TAP);
% Note: TAP==0 means no transformer (ratio = 1). We still enforce directional check.
assert(branch_TAP_58_110 <= tap_old, 'Parameter must decrease');
mpc.branch(ibr, TAP) = branch_TAP_58_110;

%% -------------------- Structural modification: add quadratic loss proxy cost --------------------
% Build a DC OPF model and add a quadratic cost term in Pg: beta*(Pg'*B*Pg + B0'*Pg + B00)
% Using om.add_quad_cost: (1/2)*x'*Q*x + c'*x + k

% Set up OPF model object (DC)
om = opf_setup(mpc, mpopt);
idx_i1 = om.var.idx.i1;
idx_iN = om.var.idx.iN;
nv = om.var.N;
ng = om.var.idx.N.Pg;

% Loss penalty weight (from template concept; exposed in structural_modification as beta=10)
beta_loss = 10;

% B-coefficient loss model placeholders.
% If ng ~= 3, we construct compatible placeholder matrices/vectors so the formulation remains valid.
if ng == 3
    B_loss = [
        0.0010, 0.0002, 0.0001;
        0.0002, 0.0012, 0.0003;
        0.0001, 0.0003, 0.0008];
    B0_loss = [0.5; 0.6; 0.4];
    B00_loss = 1.0;
else
    % Generic small-coefficient placeholders sized to number of generators
    B_loss = 1e-4 * speye(ng);
    B0_loss = 0.1 * ones(ng, 1);
    B00_loss = 0;
end

% Map Pg block in decision vector
Pg_start = idx_i1.Pg;
Pg_end   = idx_iN.Pg;
assert((Pg_end - Pg_start + 1) == ng, 'Inconsistent Pg indexing');

Q = sparse(nv, nv);
Q(Pg_start:Pg_end, Pg_start:Pg_end) = 2 * beta_loss * sparse(B_loss); % because MATPOWER uses 1/2 x'Qx

c = zeros(nv, 1);
c(Pg_start:Pg_end) = beta_loss * B0_loss;

k = beta_loss * B00_loss;

om.add_quad_cost('network_loss_cost', Q, c, k);

%% solve and build results in MATPOWER format
[x, f, eflag, output, lambda] = om.solve();

results = mpc;
results.success = (eflag > 0);
results.f = f;
results.om = om;
results.raw.x = x;
results.raw.output = output;
results.raw.lambda = lambda;

% Populate key solution fields for consistency (DC: Va and Pg exist)
if isfield(idx_i1, 'Va') && isfield(idx_iN, 'Va')
    Va = x(idx_i1.Va:idx_iN.Va);
    results.bus(:, VA) = Va * 180/pi;
end
Pg = x(Pg_start:Pg_end);
results.gen(:, PG) = Pg;

end

function results = opf_case5(bus_PD_3, bus_QD_4, gen_QMIN_3)
%OPF_CASE5  case5 ACOPF with scenario parameter updates, load shedding cost, and frequency-security constraints.

define_constants;

%% load base case
mpc = loadcase('case5');

%% ===================== Scenario-driven parameter modifications =====================
% Bus 3 PD: Decrease
old_PD_3 = mpc.bus(3, PD);
assert(bus_PD_3 <= old_PD_3, 'Parameter must decrease');
mpc.bus(3, PD) = bus_PD_3;

% Bus 4 QD: Decrease
old_QD_4 = mpc.bus(4, QD);
assert(bus_QD_4 <= old_QD_4, 'Parameter must decrease');
mpc.bus(4, QD) = bus_QD_4;

% Gen at bus 3 QMIN: Increase (less reactive absorption capability)
% Find all generators connected to bus 3 and apply the new QMIN to each.
g3 = find(mpc.gen(:, GEN_BUS) == 3);
if isempty(g3)
    error('No generator found at bus 3 in case5.');
end
old_QMIN_3 = mpc.gen(g3, QMIN);
assert(all(gen_QMIN_3 >= old_QMIN_3), 'Parameter must increase');
mpc.gen(g3, QMIN) = gen_QMIN_3;

%% ===================== Solver/options =====================
mpopt = mpoption('verbose', 1, 'out.all', 0);
mpopt = mpoption(mpopt, 'model', 'AC');
mpopt = mpoption(mpopt, 'opf.ac.solver', 'MIPS');
mpopt = mpoption(mpopt, 'opf.violation', 1e-6);

%% ===================== Structural modification 1: load shedding via virtual gens + cost =====================
% Add one virtual generator at each load bus with PMAX = original Pd at that bus.
% It injects Pg representing "shed" MW, so remaining served load is Pd - Pg.
% This uses standard MATPOWER modeling (extra gens) and penalizes shedding via gencost.
load_buses = find(mpc.bus(:, PD) > 0);
nl = length(load_buses);
ng0 = size(mpc.gen, 1);

ncol_gen = size(mpc.gen, 2);
new_gen = zeros(nl, ncol_gen);

for k = 1:nl
    b = load_buses(k);
    Pd_k = mpc.bus(b, PD);

    % copy a template generator row to preserve column compatibility
    g = mpc.gen(1, :);

    g(GEN_BUS)    = b;
    g(PG)         = 0;
    g(QG)         = 0;
    g(QMAX)       = 0;      % no reactive support
    g(QMIN)       = 0;
    g(VG)         = 1.0;
    g(GEN_STATUS) = 1;
    g(PMAX)       = Pd_k;   % maximum sheddable power at that bus
    g(PMIN)       = 0;

    new_gen(k, :) = g;
end

mpc.gen = [mpc.gen; new_gen];
ng = size(mpc.gen, 1);
shed_gen_idx = (ng0+1:ng)';

% Add gencost rows for the shedding generators (quadratic penalty)
% Keep original costs, append new polynomial costs [2 0 0 3 c2 c1 c0]
if size(mpc.gencost, 1) ~= ng0
    error('Unexpected gencost size in case5 (must match original number of generators).');
end

ncol_gc = size(mpc.gencost, 2);
old_cost = mpc.gencost;

% Default penalty coefficients (can be tuned by user by editing here)
% c2/c1/c0 for shedding generators
p_cost = 100  * ones(nl, 1);
q_cost = 1000 * ones(nl, 1);
r_cost = 5000 * ones(nl, 1);

new_cost = zeros(nl, ncol_gc);
new_cost(:, 1) = 2;   % polynomial
new_cost(:, 2) = 0;
new_cost(:, 3) = 0;
new_cost(:, 4) = 3;   % quadratic, linear, constant
new_cost(:, 5) = r_cost;
new_cost(:, 6) = q_cost;
new_cost(:, 7) = p_cost;

mpc.gencost = [old_cost; new_cost];

%% ===================== Structural modification 2: frequency-security constraints =====================
% Build an OPF model with additional variables:
%   Pmax_var (proxy for largest in-service trip)
%   R_i (reserve on each original generator)
% and linear constraints as in the frequency constraints template.

% Frequency parameters (can be tuned)
f0 = 60;                 % Hz
RoCoF_max = 0.5;         % Hz/s

df_req = 0.5;            % Hz
D_MW_per_Hz = 0;         % MW/Hz

% Only original generators provide reserves (exclude shedding gens)
ng_orig = ng0;

% Inertia assumptions (not provided by case file)
H = 5 * ones(ng_orig, 1);

% Use GEN_MBASE if available; otherwise approximate with PMAX
S_i = mpc.gen(1:ng_orig, MBASE);
mask = (S_i <= 0);
S_i(mask) = mpc.gen(find(mask), PMAX);

S_base = mpc.baseMVA;
H_sys = (H(:)' * S_i(:)) / S_base;
Ptrip_max_rocof = 2 * H_sys * S_base * RoCoF_max / f0;

Rmax = +Inf * ones(ng_orig, 1);

% Convert to internal and set up OPF model object
mpc_i = ext2int(mpc);
om = opf_setup(mpc_i, mpopt);

idx = om.var.idx;
iPg1 = idx.i1.Pg; iPgN = idx.iN.Pg;

% In internal indexing, Pg includes all generators (orig + shedding)
% We will constrain reserves only for the first ng0 internal generators (which correspond to originals).
% In MATPOWER internal ordering, generator ordering is preserved.

% Add variables
om = om.add_var('Pmax_var', 1, 0, Inf, 0);
om = om.add_var('R', ng_orig, zeros(ng_orig,1), Rmax, 0);

nv = om.var.N;
iPmax = om.var.idx.i1.Pmax_var;
iR1   = om.var.idx.i1.R;
iRN   = om.var.idx.iN.R;

PMAX_orig = mpc_i.gen(1:ng_orig, PMAX);

% (i) Pg_i <= Pmax_var for original generators only
A = sparse(ng_orig, nv);
A(:, iPg1:(iPg1+ng_orig-1)) = speye(ng_orig);
A(:, iPmax) = -ones(ng_orig, 1);
om = om.add_lin_constraint('MAX_TRIP_DEF', A, -Inf(ng_orig,1), zeros(ng_orig,1));

% (ii) Pg_i + R_i <= PMAX_i for original generators
A = sparse(ng_orig, nv);
A(:, iPg1:(iPg1+ng_orig-1)) = speye(ng_orig);
A(:, iR1:iRN) = speye(ng_orig);
om = om.add_lin_constraint('RESERVE_HEADROOM', A, -Inf(ng_orig,1), PMAX_orig);

% (iv) RoCoF limit: Pmax_var <= Ptrip_max_rocof
A = sparse(1, nv);
A(1, iPmax) = 1;
om = om.add_lin_constraint('ROCOF_LIMIT', A, -Inf, Ptrip_max_rocof);

% (v) Frequency nadir by reserve: Pmax_var - sum(R) <= D*df_req
A = sparse(1, nv);
A(1, iPmax) = 1;
A(1, iR1:iRN) = -ones(1, ng_orig);
om = om.add_lin_constraint('DF_LIMIT_RESERVE', A, -Inf, D_MW_per_Hz * df_req);

%% ===================== Execute OPF and return results =====================
[res_i, success] = opf_execute(om, mpopt);
if ~success
    error('ACOPF with load shedding and frequency constraints did not converge (likely infeasible).');
end
results = int2ext(res_i, mpc);

end

function out = opf_case24_ieee_rts(bus_VMIN_9, branch_RATE_A_8_4, lambda_load)
%OPF_CASE24_IEEE_RTS  Multi-period DC OPF (MOST) for case24_ieee_rts with
% scenario-driven parameter edits and an added average-branch-loadability cost.
%
% Inputs (placeholders representing post-modification values):
%   bus_VMIN_9            - bus 9 VMIN (must be set to zero)
%   branch_RATE_A_8_4     - branch RATE_A on corridor 8->4 (must decrease)
%   lambda_load           - weight for average-branch-loadability penalty (>=0)
%
% Output:
%   out.mdo               - MOST output struct
%   out.success           - success flag
%   out.results           - MOST results
%
% Notes:
%   - Uses MOST with DC model, with an additional nonlinear cost added to the
%     underlying OPF in each period via MOST's 'userfcn' mechanism.

define_constants;

if nargin < 3
    lambda_load = 1; % default penalty weight
end
assert(lambda_load >= 0, 'lambda_load must be nonnegative');

casefile = 'case24_ieee_rts';
mpc0 = loadcase(casefile);

%% -------------------- Scenario-driven parameter modifications --------------------
% 1) Disable bus 9 VMIN by setting it to zero
b9 = find(mpc0.bus(:, BUS_I) == 9, 1);
if isempty(b9)
    error('Bus 9 not found in %s.', casefile);
end
orig_VMIN_9 = mpc0.bus(b9, VMIN);
assert(bus_VMIN_9 == 0, 'Parameter must be set to zero');
mpc0.bus(b9, VMIN) = bus_VMIN_9;

% 2) Decrease RATE_A on branch 8 -> 4 (match orientation if present; otherwise try 4 -> 8)
br = mpc0.branch;
k = find(br(:, F_BUS) == 8 & br(:, T_BUS) == 4, 1);
if isempty(k)
    k = find(br(:, F_BUS) == 4 & br(:, T_BUS) == 8, 1);
end
if isempty(k)
    error('Branch (8,4) not found (either direction) in %s.', casefile);
end
orig_RATE_A_8_4 = mpc0.branch(k, RATE_A);
assert(branch_RATE_A_8_4 <= orig_RATE_A_8_4, 'Parameter must decrease');
mpc0.branch(k, RATE_A) = branch_RATE_A_8_4;

% Make sure RATE_A is positive (needed for loadability penalty normalization)
% If any remaining RATE_A are zero, set very large so they do not bind and do not blow up the ratio.
rateA = mpc0.branch(:, RATE_A);
if all(rateA == 0)
    mpc0.branch(:, RATE_A) = 1e4;
else
    mpc0.branch(rateA == 0, RATE_A) = 1e4;
end

%% -------------------- Multi-period DC OPF with MOST --------------------
mpopt = mpoption('verbose', 1, 'out.all', 0, 'model', 'DC', 'opf.dc.solver', 'MIPS');
mpopt = mpoption(mpopt, 'opf.violation', 1e-8);
mpopt = mpoption(mpopt, 'most.dc_model', 1);

% Build a simple flat multi-period profile set if none is provided.
% We create a modest number of periods and keep loads and generator availability constant.
nt = 3;

% profiles struct: MOST expects an array of profile structs.
% Here we use fixed scaling for bus PD across time (all ones), i.e., base case repeated.
profiles = struct([]);
profiles(1).type    = 'mpcData';
profiles(1).table   = CT_TBUS;
profiles(1).rows    = (1:size(mpc0.bus,1))';
profiles(1).col     = PD;
profiles(1).chgtype = CT_REL;
profiles(1).values  = ones(nt, numel(profiles(1).rows));

% Optional: also scale QD in sync (even though DC ignores it, keeps data consistent)
profiles(2).type    = 'mpcData';
profiles(2).table   = CT_TBUS;
profiles(2).rows    = (1:size(mpc0.bus,1))';
profiles(2).col     = QD;
profiles(2).chgtype = CT_REL;
profiles(2).values  = ones(nt, numel(profiles(2).rows));

% Build MOST data model
mdi = loadmd(mpc0, nt, [], [], [], profiles);

% Add userfcn to inject additional nonlinear cost into each period OPF
mdi = add_loadability_userfcn(mdi, lambda_load);

% Run MOST
mdo = most(mdi, mpopt);

out = struct();
out.mdo = mdo;
out.success = isfield(mdo, 'success') && mdo.success;
out.results = mdo.results;

% Preserve original values in output for traceability
out.original = struct('bus9_VMIN', orig_VMIN_9, 'branch_8_4_RATE_A', orig_RATE_A_8_4);

end

%% ==================== Userfcn registration ====================
function mdi = add_loadability_userfcn(mdi, lambda_load)
% Register a MOST userfcn that adds a nonlinear cost to each period's OPF model.

% MOST supports 'userfcn' via MATPOWER's userfcn interface at various stages.
% We attach to the OPF model building stage.
uc.name = 'avg_branch_loadability_cost';
uc.stage = 'formulation';
uc.fcn = @(om, mpopt, mpc, varargin) add_avg_loadability_cost_to_om(om, mpopt, mpc, lambda_load);

if ~isfield(mdi, 'userfcn') || isempty(mdi.userfcn)
    mdi.userfcn = uc;
else
    mdi.userfcn(end+1) = uc;
end
end

%% ==================== Add nonlinear cost to OM ====================
function om = add_avg_loadability_cost_to_om(om, mpopt, mpc, lambda_load)
% Adds nonlinear cost: lambda_load * mean(|flow_l|/RATE_A_l) across in-service branches.
% Implemented for DC using PF/PT (MW) from DC branch flow mapping.

define_constants;

% Use internal indexing for consistent matrix building
mpc_i = ext2int(mpc);
baseMVA = mpc_i.baseMVA;
bus = mpc_i.bus;
branch = mpc_i.branch;
gen = mpc_i.gen;

nl = size(branch, 1);
nb = size(bus, 1);
ng = size(gen, 1);

% Rate limits (MW). Ensure positive; if any are zero, set large to avoid division by zero.
rateA = branch(:, RATE_A);
rateA(rateA == 0) = 1e4;

% Build PTDF for DC flows (p.u. on baseMVA)
PTDF = makePTDF(baseMVA, bus, branch);

% Generator-to-bus incidence (internal bus numbering)
Cg = sparse(gen(:, GEN_BUS), (1:ng)', 1, nb, ng);

% Demand Pd (p.u.)
Pd = bus(:, PD) / baseMVA;

% OM variable indexing for Pg
idx = om.var.idx;
i1 = idx.i1.Pg;
iN = idx.iN.Pg;
if (iN - i1 + 1) ~= ng
    error('Pg dimension mismatch when adding loadability cost.');
end
nv = om.var.N;

% Nonlinear cost callback
fcn = @(x) avg_loadability_cost_fcn_dc(x, lambda_load, PTDF, Cg, Pd, i1, iN, nv, rateA, baseMVA, branch(:, BR_STATUS));

% Add scalar nonlinear cost
om.add_nln_cost('avg_loadability_cost', 1, fcn);

end

%% ==================== Cost function (DC) ====================
function [f, df, d2f] = avg_loadability_cost_fcn_dc(x, lambda_load, PTDF, Cg, Pd, i1, iN, nv, rateA, baseMVA, br_status)
% Average branch loadability cost for DC:
%   f = lambda_load * (1/n_in_service) * sum_l ( |F_l(MW)| / RATE_A_l )
% where F_l(MW) = baseMVA * PTDF(l,:) * (Cg*Pg_pu - Pd)
% and Pg_pu = Pg(MW)/baseMVA.

% Extract Pg in MW, convert to p.u.
Pg_MW = x(i1:iN);
Pg_pu = Pg_MW / baseMVA;

% Mean injections in p.u.
inj = Cg * Pg_pu - Pd;          % nb x 1 (p.u.)
flow_pu = PTDF * inj;           % nl x 1 (p.u.)
flow_MW = baseMVA * flow_pu;    % nl x 1 (MW)

% In-service mask
mask = (br_status ~= 0);
if ~any(mask)
    f = 0;
    if nargout > 1
        df = zeros(nv, 1);
    end
    if nargout > 2
        d2f = sparse(nv, nv);
    end
    return;
end

F = abs(flow_MW(mask));
R = rateA(mask);

f = lambda_load * mean(F ./ R);

% Finite-difference gradient (dense but robust)
if nargout > 1
    eps_fd = 1e-7;
    df = zeros(nv, 1);
    for k = 1:nv
        x_plus = x;
        x_plus(k) = x_plus(k) + eps_fd;
        f_plus = avg_loadability_cost_fcn_dc(x_plus, lambda_load, PTDF, Cg, Pd, i1, iN, nv, rateA, baseMVA, br_status);
        df(k) = (f_plus - f) / eps_fd;
    end
end

% Provide zero Hessian (solver may approximate)
if nargout > 2
    d2f = sparse(nv, nv);
end

end

function out = opf_case18(bus_VMIN_16, bus_VMAX_17, gen_CUP, gen_CDOWN)
%OPF_CASE18 Level-4 Economy Dispatch with redispatch cost + scenario bus limit edits
%   Inputs (placeholders representing post-modification values):
%     bus_VMIN_16  - new VMIN at bus 16 (must be <= original)
%     bus_VMAX_17  - new VMAX at bus 17 (must be <= original)
%     gen_CUP      - (ng x 1) upward redispatch penalty $/MW (>= 0 recommended)
%     gen_CDOWN    - (ng x 1) downward redispatch penalty $/MW (>= 0 recommended)
%
%   Output:
%     out struct with fields: mpc, results (dispatch), Pg, Pg_up, Pg_down, f, success, message

define_constants;

%% ----- load case -----
mpc0 = loadcase('case18');
mpc  = mpc0;

%% ----- scenario-driven parameter modifications (with direction asserts) -----
% Bus 16: VMIN decreases
b16 = find(mpc.bus(:, BUS_I) == 16, 1);
if isempty(b16), error('Bus 16 not found in case18.'); end
vmin0_16 = mpc0.bus(b16, VMIN);
assert(bus_VMIN_16 <= vmin0_16, 'Parameter must decrease');
mpc.bus(b16, VMIN) = bus_VMIN_16;

% Bus 17: VMAX decreases
b17 = find(mpc.bus(:, BUS_I) == 17, 1);
if isempty(b17), error('Bus 17 not found in case18.'); end
vmax0_17 = mpc0.bus(b17, VMAX);
assert(bus_VMAX_17 <= vmax0_17, 'Parameter must decrease');
mpc.bus(b17, VMAX) = bus_VMAX_17;

%% ----- economy dispatch data extraction -----
Pd_total = sum(mpc.bus(:, PD));
Pmin = mpc.gen(:, PMIN);
Pmax = mpc.gen(:, PMAX);
ng   = size(mpc.gen, 1);

% Quadratic generation cost coefficients from MATPOWER gencost
% Expect MODEL=2 polynomial costs; use columns [C2 C1 C0] = [gencost(:,5:7)]
if size(mpc.gencost, 2) < 7
    error('gencost matrix does not have expected polynomial columns.');
end
if any(mpc.gencost(:, MODEL) ~= 2)
    error('This economy dispatch implementation expects polynomial cost model (MODEL=2).');
end
c2 = mpc.gencost(:, 5);
c1 = mpc.gencost(:, 6);
c0 = mpc.gencost(:, 7);

% Base point for redispatch penalty (use initial PG)
Pg_base = mpc.gen(:, PG);

% Validate redispatch penalty vector sizes
if nargin < 3 || isempty(gen_CUP)
    gen_CUP = ones(ng,1); % default placeholder if not provided
end
if nargin < 4 || isempty(gen_CDOWN)
    gen_CDOWN = ones(ng,1); % default placeholder if not provided
end
assert(isvector(gen_CUP) && length(gen_CUP) == ng, 'gen_CUP must be ng x 1');
assert(isvector(gen_CDOWN) && length(gen_CDOWN) == ng, 'gen_CDOWN must be ng x 1');
gen_CUP   = gen_CUP(:);
gen_CDOWN = gen_CDOWN(:);

%% ----- build QP for Economy Dispatch + redispatch cost -----
% Decision variables: x = [Pg; Pg_up; Pg_down] (3*ng)
% Objective: sum_i (c2_i*Pg_i^2 + c1_i*Pg_i + c0_i) + sum_i (c_up_i*Pg_up_i + c_down_i*Pg_down_i)
% Constraints:
%   (1) Power balance: sum(Pg) = Pd_total
%   (2) Redispatch identity: Pg - Pg_up + Pg_down = Pg_base
%   (3) Bounds: Pmin <= Pg <= Pmax
%              0 <= Pg_up <= Pmax - Pg_base
%              0 <= Pg_down <= Pg_base - Pmin

n = 3*ng;

% Quadratic term: only on Pg
H = sparse(n, n);
H(1:ng, 1:ng) = spdiags(2*c2, 0, ng, ng);

% Linear term
f = zeros(n, 1);
f(1:ng)             = c1;
f(ng+(1:ng))        = gen_CUP;
f(2*ng+(1:ng))      = gen_CDOWN;

% Equality constraints
Aeq = sparse(ng+1, n);
beq = zeros(ng+1, 1);

% (1) sum(Pg) = Pd_total
Aeq(1, 1:ng) = 1;
beq(1) = Pd_total;

% (2) Pg - Pg_up + Pg_down = Pg_base (per generator)
Aeq(2:end, 1:ng)              = speye(ng);
Aeq(2:end, ng+(1:ng))         = -speye(ng);
Aeq(2:end, 2*ng+(1:ng))       = speye(ng);
beq(2:end) = Pg_base;

% Bounds
lb = -inf(n,1);
ub = inf(n,1);

lb(1:ng) = Pmin;
ub(1:ng) = Pmax;

lb(ng+(1:ng)) = 0;
ub(ng+(1:ng)) = max(Pmax - Pg_base, 0);

lb(2*ng+(1:ng)) = 0;
ub(2*ng+(1:ng)) = max(Pg_base - Pmin, 0);

% Solve with quadprog
qp_opt = optimoptions('quadprog', 'Display', 'off');

try
    [x, fval, exitflag, output] = quadprog(H, f, [], [], Aeq, beq, lb, ub, [], qp_opt);
catch me
    error('quadprog failed to run: %s', me.message);
end

success = (exitflag > 0);

% Parse solution
Pg      = x(1:ng);
Pg_up   = x(ng+(1:ng));
Pg_down = x(2*ng+(1:ng));

% Compute full objective including constants
obj = fval + sum(c0);

% Package outputs
out = struct();
out.mpc = mpc;
out.success = success;
out.message = '';
if isfield(output, 'message')
    out.message = output.message;
end
out.Pg = Pg;
out.Pg_up = Pg_up;
out.Pg_down = Pg_down;
out.f = obj;

% Provide a simple "results" struct consistent with an ED context
results = mpc;
results.gen(:, PG) = Pg;
results.f = obj;
results.success = success;
out.results = results;

end

function results = opf_case94pi(bus_VMIN_59, gen_PMIN_18)
%OPF_CASE94PI  Case94pi with scenario parameter changes + reactive Q cost + frequency constraints.

define_constants;

%% load case
mpc0 = loadcase('case94pi');
mpc  = mpc0;

%% ---------------- scenario-driven parameter modifications ----------------
% (1) Disable lower voltage limit at bus 59 by setting VMIN to zero
b59 = find(mpc.bus(:, BUS_I) == 59);
assert(~isempty(b59), 'Bus 59 not found in case94pi');
assert(bus_VMIN_59 == 0, 'Parameter must be set to zero');
mpc.bus(b59, VMIN) = bus_VMIN_59;

% (2) Increase PMIN of generator at bus 18
g18 = find(mpc.gen(:, GEN_BUS) == 18);
assert(~isempty(g18), 'No generator found at bus 18 in case94pi');
% if multiple generators at bus 18, apply to all
orig_PMIN_18 = mpc0.gen(g18, PMIN);
assert(all(gen_PMIN_18 >= orig_PMIN_18), 'Parameter must increase');
mpc.gen(g18, PMIN) = gen_PMIN_18;

%% ---------------- solver / options ----------------
mpopt = mpoption('verbose', 1, 'out.all', 0);
mpopt = mpoption(mpopt, 'opf.violation', 1e-6);
mpopt = mpoption(mpopt, 'model', 'AC');
mpopt = mpoption(mpopt, 'opf.ac.solver', 'MIPS');

%% ---------------- build OPF model ----------------
mpc_i = ext2int(mpc);
om = opf_setup(mpc_i, mpopt);
idx = om.var.idx;
ng  = size(mpc_i.gen, 1);

%% ---------------- objective modification: reactive power generation cost ----------------
% Placeholder c_Q coefficients (user can edit to match study intent)
% If ng differs from 3, expand/trim deterministically.
c_Q_base = [100; 15; 20];
if ng <= 3
    c_Q = c_Q_base(1:ng);
else
    c_Q = [c_Q_base; 15 * ones(ng-3, 1)];
end
Q_mat = sparse(1:ng, 1:ng, 2*c_Q, ng, ng);
om = om.add_quad_cost('reactive_power_generation_cost', Q_mat, [], 0, {'Qg'});

%% ---------------- constraint modification: frequency-style constraints ----------------
% Frequency parameters (placeholders consistent with template intent)
f0 = 60;                % Hz
RoCoF_max = 0.5;        % Hz/s
df_req = 0.5;           % Hz
D_MW_per_Hz = 0;        % MW/Hz

% Inertia constants H (seconds) - placeholders
H = 5 * ones(ng, 1);

% Machine MVA bases
S_i = mpc_i.gen(:, MBASE);
S_i(S_i <= 0) = mpc_i.gen(S_i <= 0, PMAX);

S_base = mpc_i.baseMVA;
H_sys = (H(:)' * S_i(:)) / S_base;
Ptrip_max_rocof = 2 * H_sys * S_base * RoCoF_max / f0;

% Reserve upper bounds (placeholders)
Rmax = +Inf * ones(ng, 1);

% Add proxy max-trip variable and reserve variables
om = om.add_var('Pmax_var', 1, 0, Inf, 0);
om = om.add_var('R', ng, zeros(ng,1), Rmax, 0);

nv = om.var.N;
iPg1 = idx.i1.Pg; iPgN = idx.iN.Pg;
iPmax = om.var.idx.i1.Pmax_var;
iR1   = om.var.idx.i1.R;
iRN   = om.var.idx.iN.R;

PMAXv = mpc_i.gen(:, PMAX);

% (i) Pg_i <= Pmax_var
A = sparse(ng, nv);
A(:, iPg1:iPgN) = speye(ng);
A(:, iPmax) = -ones(ng, 1);
om = om.add_lin_constraint('MAX_TRIP_DEF', A, -Inf(ng, 1), zeros(ng, 1));

% (ii) Pg_i + R_i <= PMAX_i (reserve headroom)
A = sparse(ng, nv);
A(:, iPg1:iPgN) = speye(ng);
A(:, iR1:iRN)   = speye(ng);
om = om.add_lin_constraint('RESERVE_HEADROOM', A, -Inf(ng, 1), PMAXv);

% (iv) RoCoF: Pmax_var <= Ptrip_max_rocof
A = sparse(1, nv);
A(1, iPmax) = 1;
om = om.add_lin_constraint('ROCOF_LIMIT', A, -Inf, Ptrip_max_rocof);

% (v) Frequency deviation adequacy: Pmax_var - sum(R) <= D*df_req
A = sparse(1, nv);
A(1, iPmax) = 1;
A(1, iR1:iRN) = -ones(1, ng);
om = om.add_lin_constraint('DF_LIMIT_RESERVE', A, -Inf, D_MW_per_Hz * df_req);

%% ---------------- solve ----------------
[res_i, success] = opf_execute(om, mpopt);
if ~success
    error('ACOPF with objective/constraints failed (likely infeasible).');
end
results = int2ext(res_i, mpc);

end

function mdo = opf_case69(gen_PMIN_12, gen_GENCOST_C1_4, gen_GENCOST_C2_10, gen_GENCOST_C3_2, lambda_L)
%OPF_CASE69  Multi-period DCOPF (MOST) on case69 with scenario parameter edits and L-index penalty.
%   Inputs are post-modification placeholder values consistent with scenario directions.

clearvars -except gen_PMIN_12 gen_GENCOST_C1_4 gen_GENCOST_C2_10 gen_GENCOST_C3_2 lambda_L;
define_constants;

if nargin < 5 || isempty(lambda_L)
    lambda_L = 1;   % default weight (can be overridden)
end

CASE_NAME = 'case69';
SOLVER = 'MIPS';

%% load base case
mpc0 = loadcase(CASE_NAME);
if isempty(mpc0)
    error('Failed to load case: %s', CASE_NAME);
end

%% apply scenario-driven parameter modifications with direction asserts
% Generator at bus 12, PMIN: Increase
idx12 = find(mpc0.gen(:, GEN_BUS) == 12, 1, 'first');
if isempty(idx12)
    error('No generator found at bus 12.');
end
orig_PMIN_12 = mpc0.gen(idx12, PMIN);
assert(gen_PMIN_12 >= orig_PMIN_12, 'Parameter must increase');
mpc0.gen(idx12, PMIN) = gen_PMIN_12;

% Generator at bus 4, COST_PARAMS_C1: Decrease (assume polynomial cost: c2, c1, c0)
idx4 = find(mpc0.gen(:, GEN_BUS) == 4, 1, 'first');
if isempty(idx4)
    error('No generator found at bus 4.');
end
if size(mpc0.gencost, 1) < idx4
    error('gencost has fewer rows than generators; cannot map gen@bus4 to cost row.');
end
% For polynomial model (MODEL=2), NCOST=3: [c2 c1 c0] stored at columns 5:7
orig_C1_4 = mpc0.gencost(idx4, 6);
assert(gen_GENCOST_C1_4 <= orig_C1_4, 'Parameter must decrease');
mpc0.gencost(idx4, 6) = gen_GENCOST_C1_4;

% Generator at bus 10, COST_PARAMS_C2: Decrease
idx10 = find(mpc0.gen(:, GEN_BUS) == 10, 1, 'first');
if isempty(idx10)
    error('No generator found at bus 10.');
end
if size(mpc0.gencost, 1) < idx10
    error('gencost has fewer rows than generators; cannot map gen@bus10 to cost row.');
end
orig_C2_10 = mpc0.gencost(idx10, 5);
assert(gen_GENCOST_C2_10 <= orig_C2_10, 'Parameter must decrease');
mpc0.gencost(idx10, 5) = gen_GENCOST_C2_10;

% Generator at bus 2, COST_PARAMS_C3: Decrease (interpreted as c0)
idx2 = find(mpc0.gen(:, GEN_BUS) == 2, 1, 'first');
if isempty(idx2)
    error('No generator found at bus 2.');
end
if size(mpc0.gencost, 1) < idx2
    error('gencost has fewer rows than generators; cannot map gen@bus2 to cost row.');
end
orig_C3_2 = mpc0.gencost(idx2, 7);
assert(gen_GENCOST_C3_2 <= orig_C3_2, 'Parameter must decrease');
mpc0.gencost(idx2, 7) = gen_GENCOST_C3_2;

%% MOST multi-period DC model options
mpopt = mpoption('most.dc_model', 1);
mpopt = mpoption(mpopt, 'verbose', 1, 'out.all', 0);
mpopt = mpoption(mpopt, 'model', 'DC');
mpopt = mpoption(mpopt, 'opf.dc.solver', SOLVER);
mpopt = mpoption(mpopt, 'opf.violation', 1e-6);

%% build a minimal multi-period dataset (profiles as placeholders)
% NOTE: This is a self-contained template that creates a flat load profile.
% Users can replace with real getprofiles/loadmd workflows.
nt = 2;                              % placeholder number of periods
basePD = mpc0.bus(:, PD);

profiles = struct([]);
profiles(1).type = 'mpcData';
profiles(1).table = CT_TAREALOAD;     % apply to area loads
profiles(1).rows = 1;                % default area row
profiles(1).col = CT_LOAD_ALL_P;
profiles(1).chgtype = CT_REP;
profiles(1).values = ones(nt,1);     % flat multiplier

% MOST expects some xGenData; if none, pass empty and MOST will run with fixed gens
xgd = [];
mdi = loadmd(mpc0, nt, xgd, [], [], profiles);

%% Solve with MOST (multi-period DCOPF)
mdo = most(mdi, mpopt);

%% Add voltage stability L-index penalty per period (post-processing objective add-on)
% MOST solved the dispatch; we compute per-period L_max from an AC Ybus built
% on the base network and the period voltages assumed at 1.0 pu and Va from DC.
% This augments reported objective for analysis; users can embed directly in a
% custom nonlinear model if desired.

% Prepare matrices for L-index from base case
[Ybus, ~, ~] = makeYbus(mpc0.baseMVA, mpc0.bus, mpc0.branch);
bus_type = mpc0.bus(:, BUS_TYPE);
idxG = find(bus_type == REF | bus_type == PV);
idxL = find(bus_type == PQ);

Lmax_t = zeros(nt,1);
if ~isempty(idxL) && ~isempty(idxG)
    Y_LL = Ybus(idxL, idxL);
    Y_LG = Ybus(idxL, idxG);
    Fmat = -(Y_LL \ Y_LG);

    % Extract MOST expected dispatch angles if available
    % ExpectedDispatch is (ng x nt). Va is not always provided; approximate with zeros.
    Va = zeros(size(mpc0.bus,1), nt);
    if isfield(mdo, 'results') && isfield(mdo.results, 'Va')
        Va = mdo.results.Va;
    end

    Vm = ones(size(mpc0.bus,1), nt);
    for t = 1:nt
        V = Vm(:,t) .* exp(1j * Va(:,t));
        V_G = V(idxG);
        V_L = V(idxL);
        T = Fmat * V_G;
        U = T ./ V_L;
        Lvec = abs(1 - U);
        Lmax_t(t) = max(Lvec);
    end
end

% Store penalty information in MOST output struct
mdo.results.Lmax = Lmax_t;
mdo.results.Lindex_penalty = lambda_L * sum(Lmax_t);
if isfield(mdo, 'results') && isfield(mdo.results, 'f')
    mdo.results.f_with_Lindex = mdo.results.f + mdo.results.Lindex_penalty;
end

end

function results = opf_case30Q(branch_BR_B_19_11, branch_RATE_A_19_20)
%OPF_CASE30Q  AC-OPF on case30Q with scenario parameter edits, load shedding, and angle-difference penalty.
%
%   Inputs are post-modification placeholder values consistent with scenario directions:
%     - branch_BR_B_19_11    : increased BR_B on branch 19-11
%     - branch_RATE_A_19_20  : decreased RATE_A on branch 19-20
%
%   Output:
%     - results : MATPOWER results struct (external indexing)

define_constants;

%% load base case
mpc0 = loadcase('case30Q');
mpc  = mpc0;

%% solver/options
mpopt = mpoption('verbose', 1, 'out.all', 0);
mpopt = mpoption(mpopt, 'model', 'AC');
mpopt = mpoption(mpopt, 'opf.ac.solver', 'MIPS');
mpopt = mpoption(mpopt, 'opf.violation', 1e-8);

%% ===================== Scenario-driven parameter modifications =====================
% helper to find a unique branch row by (fbus,tbus) in either direction
find_branch_row = @(br, f, t) find((br(:,F_BUS)==f & br(:,T_BUS)==t) | (br(:,F_BUS)==t & br(:,T_BUS)==f));

% (1) BR_B increase on branch 19-11
idx_19_11 = find_branch_row(mpc.branch, 19, 11);
assert(~isempty(idx_19_11), 'Branch 19-11 not found in case30Q.');
assert(numel(idx_19_11)==1, 'Branch 19-11 is not unique in case30Q.');
old_BR_B_19_11 = mpc.branch(idx_19_11, BR_B);
assert(branch_BR_B_19_11 >= old_BR_B_19_11, 'Parameter must increase');
mpc.branch(idx_19_11, BR_B) = branch_BR_B_19_11;

% (2) RATE_A decrease on branch 19-20
idx_19_20 = find_branch_row(mpc.branch, 19, 20);
assert(~isempty(idx_19_20), 'Branch 19-20 not found in case30Q.');
assert(numel(idx_19_20)==1, 'Branch 19-20 is not unique in case30Q.');
old_RATE_A_19_20 = mpc.branch(idx_19_20, RATE_A);
assert(branch_RATE_A_19_20 <= old_RATE_A_19_20, 'Parameter must decrease');
mpc.branch(idx_19_20, RATE_A) = branch_RATE_A_19_20;

%% ===================== Structural modification 1: load shedding via fictitious gens =====================
nb = size(mpc.bus, 1);
ng0 = size(mpc.gen, 1);

load_buses = find(mpc.bus(:, PD) > 0);
nl_load = length(load_buses);

% Create one shedding gen at each load bus
ncol_gen = size(mpc.gen, 2);
new_gen = zeros(nl_load, ncol_gen);
for k = 1:nl_load
    b = load_buses(k);
    Pd_k = mpc.bus(b, PD);

    g = mpc.gen(1, :);          % template for column compatibility
    g(GEN_BUS)    = b;
    g(PG)         = 0;
    g(QG)         = 0;
    g(QMAX)       = 0;
    g(QMIN)       = 0;
    g(VG)         = 1.0;
    g(GEN_STATUS) = 1;
    g(PMAX)       = Pd_k;       % max shed = original load
    g(PMIN)       = 0;

    new_gen(k, :) = g;
end

mpc.gen = [mpc.gen; new_gen];
ng = size(mpc.gen, 1);
shed_gen_idx = (ng0+1:ng)';

% Add costs for shedding gens: polynomial [2 0 0 3 c2 c1 c0]
% Keep existing costs unchanged
ncol_gc = size(mpc.gencost, 2);
old_cost = mpc.gencost;

% If gencost has fewer than 7 cols, pad (robustness)
if ncol_gc < 7
    old_cost(:, end+1:7) = 0; %#ok<AGROW>
    ncol_gc = 7;
end

% Placeholder penalty shape (same structure as template, values fixed as in template intent)
p_cost = 100  * ones(nl_load, 1);
q_cost = 1000 * ones(nl_load, 1);
r_cost = 5000 * ones(nl_load, 1);

new_cost = zeros(nl_load, ncol_gc);
new_cost(:,1) = 2;   % polynomial
new_cost(:,2) = 0;
new_cost(:,3) = 0;
new_cost(:,4) = 3;
new_cost(:,5) = r_cost;
new_cost(:,6) = q_cost;
new_cost(:,7) = p_cost;

mpc.gencost = [old_cost; new_cost];

%% ===================== Structural modification 2: angle difference quadratic penalty =====================
% Build OPF model and add quadratic cost on Va differences across branches
beta = 10;

om = opf_setup(mpc, mpopt);

% dimensions
mpc_i = ext2int(mpc);
nb_i  = size(mpc_i.bus, 1);
branch_i = mpc_i.branch;

% Use only in-service branches for penalty
in_service = find(branch_i(:, BR_STATUS) ~= 0);

f = branch_i(in_service, F_BUS);
t = branch_i(in_service, T_BUS);

nl_pen = length(in_service);
E = sparse(1:nl_pen, f,  1, nl_pen, nb_i) + sparse(1:nl_pen, t, -1, nl_pen, nb_i);
Q_va = 2 * beta * (E' * E);

om = om.add_quad_cost('angle_difference_penalty', Q_va, [], 0, {'Va'});

%% ===================== Solve =====================
try
    [res_i, success] = opf_execute(om, mpopt);
catch
    % compatibility with older MATPOWER signatures
    [res_i, success] = opf_execute(om, mpc_i, mpopt);
end

if ~success
    error('AC-OPF with load shedding and angle penalty did not converge.');
end

results = int2ext(res_i, mpc);

% add some convenience outputs (optional)
Pg_all = results.gen(:, PG);
results.order.load_shed.shed_gen_idx = shed_gen_idx;
results.order.load_shed.load_buses = load_buses;
results.order.load_shed.Lshed = Pg_all(shed_gen_idx);

end

function results = opf_case51ga(branch_RATE_A_16_17, gen_PMAX_3)
%OPF_CASE51GA  AC-OPF for case51ga with scenario parameter updates, load shedding, and line-charging voltage cost
%
% Inputs (placeholders for post-modification values consistent with scenario directions):
%   branch_RATE_A_16_17 : new RATE_A for branch 16-17 (must be >= original)
%   gen_PMAX_3          : new PMAX for generator at bus 3 (must be <= original)
%
% Output:
%   results : MATPOWER results struct from solved OPF (includes shed generators)

define_constants;

%% load base case
mpc0 = loadcase('case51ga');
mpc  = mpc0;  % working copy

%% solver options
mpopt = mpoption('verbose', 1, 'out.all', 0);
mpopt = mpoption(mpopt, 'model', 'AC');
mpopt = mpoption(mpopt, 'opf.ac.solver', 'MIPS');
mpopt = mpoption(mpopt, 'opf.violation', 1e-7);

%% =========================
% Scenario-driven parameter modifications with direction asserts

% --- Branch 16-17 RATE_A increase
br_idx_16_17 = find( (mpc.branch(:, F_BUS) == 16 & mpc.branch(:, T_BUS) == 17) | ...
                     (mpc.branch(:, F_BUS) == 17 & mpc.branch(:, T_BUS) == 16) );
assert(~isempty(br_idx_16_17), 'Branch between bus 16 and 17 not found.');
assert(numel(br_idx_16_17) == 1, 'Expected a single branch between bus 16 and 17.');
old_RATE_A_16_17 = mpc0.branch(br_idx_16_17, RATE_A);
assert(branch_RATE_A_16_17 >= old_RATE_A_16_17, 'Parameter must increase');
mpc.branch(br_idx_16_17, RATE_A) = branch_RATE_A_16_17;

% --- Generator at bus 3 PMAX decrease
gen_idx_bus3 = find(mpc.gen(:, GEN_BUS) == 3);
assert(~isempty(gen_idx_bus3), 'No generator at bus 3 found.');
assert(numel(gen_idx_bus3) == 1, 'Expected exactly one generator at bus 3 for this modification.');
old_PMAX_3 = mpc0.gen(gen_idx_bus3, PMAX);
assert(gen_PMAX_3 <= old_PMAX_3, 'Parameter must decrease');
mpc.gen(gen_idx_bus3, PMAX) = gen_PMAX_3;

%% =========================
% Structural modification 1: Add load shedding via virtual generators
nb  = size(mpc.bus, 1);
ng0 = size(mpc.gen, 1);

load_buses = find(mpc.bus(:, PD) > 0);
nl_load = length(load_buses);

ncol_gen = size(mpc.gen, 2);
new_gen = zeros(nl_load, ncol_gen);

for k = 1:nl_load
    b = load_buses(k);
    Pd_k = mpc.bus(b, PD);

    g = mpc.gen(1, :);          % template to preserve extra columns
    g(GEN_BUS)    = b;
    g(PG)         = 0;
    g(QG)         = 0;
    g(QMAX)       = 0;
    g(QMIN)       = 0;
    g(VG)         = 1.0;
    g(GEN_STATUS) = 1;
    g(PMAX)       = Pd_k;
    g(PMIN)       = 0;

    new_gen(k, :) = g;
end

mpc.gen = [mpc.gen; new_gen];
ng = size(mpc.gen, 1);
shed_gen_idx = (ng0+1:ng)';

% Add/extend gencost for shed generators (high penalty)
ncol_gc = size(mpc.gencost, 2);
if ncol_gc < 7
    % ensure polynomial cost format has at least 7 columns
    mpc.gencost(:, end+1:7) = 0;
    ncol_gc = 7;
end

old_cost = mpc.gencost;

p_cost = 100  * ones(nl_load, 1);
q_cost = 1000 * ones(nl_load, 1);
r_cost = 5000 * ones(nl_load, 1);

new_cost = zeros(nl_load, ncol_gc);
new_cost(:, 1) = 2;   % polynomial
new_cost(:, 2) = 0;   % startup
new_cost(:, 3) = 0;   % shutdown
new_cost(:, 4) = 3;   % ncost
new_cost(:, 5) = r_cost;
new_cost(:, 6) = q_cost;
new_cost(:, 7) = p_cost;

mpc.gencost = [old_cost; new_cost];

%% =========================
% Structural modification 2: Add line-charging reactive procurement cost as quadratic cost on Vm
%   Objective add: sum_b alpha(b) * Vm(b)^2

branch = mpc.branch;
nl = size(branch, 1);
alpha = zeros(nb, 1);

r_ch = 10;  % [$/Mvar] placeholder coefficient as in template

for k = 1:nl
    f = branch(k, F_BUS);
    t = branch(k, T_BUS);
    Bch = branch(k, BR_B);
    coeff = r_ch * abs(Bch) / 2;
    alpha(f) = alpha(f) + coeff;
    alpha(t) = alpha(t) + coeff;
end

% Set up OPF model and add quadratic cost
om = opf_setup(mpc, mpopt);
idx = om.var.idx;
idx_i1 = idx.i1;
idx_iN = idx.iN;
nv = om.var.N;

Q = sparse(nv, nv);
c = zeros(nv, 1);
k0 = 0;

Qvm = spdiags(2 * alpha, 0, nb, nb);
Q(idx_i1.Vm:idx_iN.Vm, idx_i1.Vm:idx_iN.Vm) = Qvm;

om.add_quad_cost('Qch_cost', Q, c, k0);

%% =========================
% Solve
[x, f, eflag, ~, ~] = om.solve();

if eflag <= 0
    error('AC-OPF with load shedding and Qch voltage cost did not converge.');
end

% Build MATPOWER-like results struct
results = mpc;
results.success = 1;
results.f = f;

results.bus(:, VA) = x(idx_i1.Va:idx_iN.Va) * 180/pi;
results.bus(:, VM) = x(idx_i1.Vm:idx_iN.Vm);
results.gen(:, PG) = x(idx_i1.Pg:idx_iN.Pg);
results.gen(:, QG) = x(idx_i1.Qg:idx_iN.Qg);

% Add convenience fields for load shedding summary
Pg_all = results.gen(:, PG);
Lshd = Pg_all(shed_gen_idx);
orig_load = mpc.bus(load_buses, PD);
results.userdata.load_shedding.load_buses = load_buses;
results.userdata.load_shedding.shed_gen_idx = shed_gen_idx;
results.userdata.load_shedding.orig_load_MW = orig_load;
results.userdata.load_shedding.shed_load_MW = Lshd;
results.userdata.load_shedding.remaining_load_MW = orig_load - Lshd;
results.userdata.load_shedding.total_orig_MW = sum(orig_load);
results.userdata.load_shedding.total_shed_MW = sum(Lshd);
results.userdata.load_shedding.total_remaining_MW = sum(orig_load) - sum(Lshd);

Vm = results.bus(:, VM);
results.userdata.Qch_cost.alpha = alpha;
results.userdata.Qch_cost.value = sum(alpha .* Vm.^2);

end

function mdo = opf_case14(bus_BS_12, gen_QMIN_1)
%OPF_CASE14  Multi-period DCOPF (MOST) on case14 with scenario parameter changes
%           and added real-power redispatch cost via custom objective.

define_constants;

%% load base case
mpc0 = loadcase('case14');

%% scenario-driven parameter modifications with direction validation
% 1) Bus 12 shunt susceptance BS decreases (disconnect shunt capacitors)
old_BS_12 = mpc0.bus(12, BS);
assert(bus_BS_12 <= old_BS_12, 'Parameter must decrease');
mpc0.bus(12, BS) = bus_BS_12;

% 2) Generator at bus 1 QMIN decreases (allow deeper reactive absorption)
ig1 = find(mpc0.gen(:, GEN_BUS) == 1);
assert(~isempty(ig1), 'No generator found at bus 1');
% apply to the first generator at bus 1 (case14 has one)
ig1 = ig1(1);
old_QMIN_1 = mpc0.gen(ig1, QMIN);
assert(gen_QMIN_1 <= old_QMIN_1, 'Parameter must decrease');
mpc0.gen(ig1, QMIN) = gen_QMIN_1;

%% MOST multi-period DC model options
mpopt = mpoption('verbose', 1, 'out.all', 0);
mpopt = mpoption(mpopt, 'most.dc_model', 1);
mpopt = mpoption(mpopt, 'model', 'DC');
mpopt = mpoption(mpopt, 'opf.dc.solver', 'MIPS');
mpopt = mpoption(mpopt, 'opf.violation', 1e-06);

%% build a simple multi-period horizon (self-contained)
% If you have external profiles, replace this block with getprofiles/loadmd calls.
nt = 24;
profiles = struct([]);

% load profile: scale all bus PD (and QD, though DC ignores QD) over time
load_mult = ones(nt, 1);
% placeholder shape (kept generic and feasible)
for t = 1:nt
    load_mult(t) = 1; %#ok<AGROW>
end

profiles(1).type = 'mpcData';
profiles(1).table = CT_TBUS;
profiles(1).rows = (1:size(mpc0.bus,1))';
profiles(1).col = PD;
profiles(1).chgtype = CT_REL;
profiles(1).values = load_mult;

%% xGenData and MOST model data
xgd = loadxgendata('ex_xgd_ramp', mpc0);
mdi = loadmd(mpc0, nt, xgd, [], [], profiles);

%% add real-power redispatch cost via MOST user function
% Cost coefficients (placeholders consistent with template intent)
ng = size(mpc0.gen, 1);
mdi.uc = [];  % no unit commitment
mdi.userdata.redispatch.c_up = 50 * ones(ng, 1);
mdi.userdata.redispatch.c_down = 30 * ones(ng, 1);
mdi.userdata.redispatch.Pg_base = mpc0.gen(:, PG);

% register userfcn callbacks for each period's OPF model
mdi = add_userfcn(mdi, 'formulation', @userfcn_redispatch_formulation);

%% run MOST
mdo = most(mdi, mpopt);

end

%% ===== MOST user function: add redispatch vars/constraints/cost to each period OPF =====
function om = userfcn_redispatch_formulation(om, mpopt, args)
% Adds Pg_up/Pg_down and enforces Pg - Pg_up + Pg_down = Pg_base
% and adds linear redispatch cost sum(c_up.*Pg_up + c_down.*Pg_down).

define_constants;

% access MOST/MDI data passed in args
% In MOST, args contains (mdi, mpc, offer, bid, t, etc.) depending on stage.
% We rely on mdi.userdata.redispatch.
mdi = args.mdi;
mpc = args.mpc;

c_up = mdi.userdata.redispatch.c_up;
c_down = mdi.userdata.redispatch.c_down;
Pg_base = mdi.userdata.redispatch.Pg_base;

ng = size(mpc.gen, 1);

% add variables (nonnegative)
Pgmax_up = mpc.gen(:, PMAX) - Pg_base;
Pgmax_dn = Pg_base - mpc.gen(:, PMIN);
Pgmax_up(Pgmax_up < 0) = 0;
Pgmax_dn(Pgmax_dn < 0) = 0;

om = om.add_var('Pg_up', ng, zeros(ng,1), zeros(ng,1), Pgmax_up);
om = om.add_var('Pg_down', ng, zeros(ng,1), zeros(ng,1), Pgmax_dn);

% indices after adding vars
idx_i1 = om.var.idx.i1;
idx_iN = om.var.idx.iN;
nv = om.var.N;

% linear equality: Pg - Pg_up + Pg_down = Pg_base
A = sparse(ng, nv);
A(:, idx_i1.Pg:idx_iN.Pg) = speye(ng);
A(:, idx_i1.Pg_up:idx_iN.Pg_up) = -speye(ng);
A(:, idx_i1.Pg_down:idx_iN.Pg_down) = speye(ng);
b = Pg_base;
om = om.add_lin_constraint('redispatch_balance', A, b, b);

% linear cost on Pg_up/Pg_down (implemented via add_quad_cost with zero Q)
c = zeros(nv, 1);
c(idx_i1.Pg_up:idx_iN.Pg_up) = c_up;
c(idx_i1.Pg_down:idx_iN.Pg_down) = c_down;
om = om.add_quad_cost('redispatch_cost', [], c, 0);

end

function results = opf_case9target(bus_VMIN_1, branch_RATE_A_7_1)
%OPF_CASE9TARGET  DCOTS with soft line-limit slacks, scenario parameter edits w/ direction asserts.
%
% Inputs are post-modification placeholder values consistent with scenario directions.

define_constants;

%% load base case
mpc0 = loadcase('case9target');

%% scenario-driven parameter modifications (with direction validation)
% (1) Disable VMIN at bus 1 by setting it to zero
bus1 = find(mpc0.bus(:, BUS_I) == 1);
assert(~isempty(bus1) && numel(bus1) == 1, 'Bus 1 not found or not unique');
assert(bus_VMIN_1 == 0, 'Parameter must be set to zero');
mpc0.bus(bus1, VMIN) = bus_VMIN_1;

% (2) Decrease RATE_A on branch 7-1 (either direction allowed in data)
br71 = find( (mpc0.branch(:, F_BUS) == 7 & mpc0.branch(:, T_BUS) == 1) | ...
            (mpc0.branch(:, F_BUS) == 1 & mpc0.branch(:, T_BUS) == 7) );
assert(~isempty(br71) && numel(br71) == 1, 'Branch 7-1 not found or not unique');
assert(branch_RATE_A_7_1 <= mpc0.branch(br71, RATE_A), 'Parameter must decrease');
mpc0.branch(br71, RATE_A) = branch_RATE_A_7_1;

%% solver/settings
useropt = struct();
useropt.model = 'DC';
useropt.solver = 'MIPS';
useropt.M = 1e5;      % Big-M for DCOTS
useropt.GUB = 4;      % max number of opened lines

mpopt = mpoption('model', useropt.model, 'verbose', 1, 'out.all', 0);
mpopt = mpoption(mpopt, 'opf.dc.solver', useropt.solver);
mpopt = mpoption(mpopt, 'opf.violation', 1e-7);

%% internal indexing + OPF model
mpc = ext2int(mpc0, mpopt);
om = opf_setup(mpc, mpopt);

fprintf('\n%s DCOTS + Soft Line Limits %s\n', repmat('=', 1, 30), repmat('=', 1, 30));

[baseMVA, bus, gen, branch] = deal(mpc.baseMVA, mpc.bus, mpc.gen, mpc.branch);
[nb, ng, nl] = deal(size(bus,1), size(gen,1), size(branch,1));

%% DCOTS structural modification: introduce Pf (line flows) and Z (binary status)
% relax/remove original linear power mismatch bounds (as in template)
try
    nPmis = om.getN('lin', 'Pmis');
    if nPmis > 0
        om.set_params('lin', 'Pmis', {'l', 'u'}, {-Inf(nPmis,1), Inf(nPmis,1)});
    end
catch
    % if model does not contain named 'Pmis' in this MATPOWER version, ignore
end

% add variables
om.add_var('Pf', nl, zeros(nl,1));                     % continuous line flows (p.u.)
om.add_var('Z',  nl, ones(nl,1), [], [], 'B');         % binary line status

%% build DC matrices
[B, Bf, Pbusinj, Pfinj] = makeBdc(baseMVA, bus, branch);
f = branch(:, F_BUS); t = branch(:, T_BUS);
Cft = sparse([(1:nl)'; (1:nl)'], [f; t], [ones(nl,1); -ones(nl,1)], nl, nb);
neg_Cg = sparse(gen(:, GEN_BUS), 1:ng, -1, nb, ng);
Aeq = [Cft' neg_Cg];
beq = -(bus(:, PD) + bus(:, GS)) / baseMVA - Pbusinj;

Il  = speye(nl);
rhs = useropt.M * ones(nl, 1);

% line capacity bounds for DC Pf variable
il = find(branch(:, RATE_A) ~= 0 & branch(:, RATE_A) < 1e10);
Pmax = inf(nl,1);
Pmin = inf(nl,1);
if ~isempty(il)
    Pmax(il) = branch(il, RATE_A) / baseMVA - Pfinj(il);
    Pmin(il) = branch(il, RATE_A) / baseMVA + Pfinj(il);
end

%% add DCOTS linear constraints
% capacity * status (Big-M-like using Z)
om.add_lin_constraint('Pfl', [Il,  diag(Pmin)], zeros(nl,1), [], {'Pf', 'Z'});
om.add_lin_constraint('Pfu', [Il, -diag(Pmax)], [], zeros(nl,1), {'Pf', 'Z'});

% nodal balance using Pf and Pg
om.add_lin_constraint('Pfmis', Aeq, beq, beq, {'Pf', 'Pg'});

% link Pf to angles when line is on: Bf*Va - Pf within +/- M*(1-Z)
om.add_lin_constraint('Ml', [Bf, -Il, -useropt.M*Il], -rhs, [], {'Va', 'Pf', 'Z'});
om.add_lin_constraint('Mu', [Bf, -Il,  useropt.M*Il], [], rhs,  {'Va', 'Pf', 'Z'});

% global upper bound on number of opened lines: sum(Z) >= nl - GUB
om.add_lin_constraint('GUB', ones(1, nl), nl - useropt.GUB, [], {'Z'});

%% Soft line limits objective augmentation (linear penalty on slack)
% add nonnegative slack variables for each branch end
om.add_var('s_from', nl, zeros(nl,1), zeros(nl,1), inf(nl,1));
om.add_var('s_to',   nl, zeros(nl,1), zeros(nl,1), inf(nl,1));

% build rate_a vector for all branches (replace 0 with large placeholder as in template)
rate_a = branch(:, RATE_A);
rate_a(rate_a == 0) = 250; % placeholder emergency default

% add nonlinear soft limit constraint on apparent power flow magnitudes
idx_i1 = om.var.idx.i1;
idx_iN = om.var.idx.iN;
nv_new = om.var.N;

fcn_soft_limit = @(x) branch_flow_soft_constraint(x, mpc, idx_i1, idx_iN, rate_a, nv_new);
om.add_nln_constraint('soft_flow_limit', 2*nl, 0, fcn_soft_limit, @(x, lambda) sparse(nv_new, nv_new));

% add linear penalty on slacks to objective
lambda_slack = 10000;
Q = sparse(nv_new, nv_new);
c = zeros(nv_new, 1);
c(idx_i1.s_from:idx_iN.s_from) = lambda_slack * ones(nl, 1);
c(idx_i1.s_to:idx_iN.s_to)     = lambda_slack * ones(nl, 1);
om.add_quad_cost('slack_penalty', Q, c, 0);

%% solve
[x, fval, eflag, output, lambda] = om.solve();

% pack results in MATPOWER-style struct (minimal)
results = mpc0;
results.f = fval;
results.success = (eflag > 0);
results.raw = struct('x', x, 'eflag', eflag, 'output', output, 'lambda', lambda);

end

function [h, dh] = branch_flow_soft_constraint(x, mpc, idx_i1, idx_iN, rate_a, nv)
% Nonlinear inequality h(x) <= 0, where:
% |Sf| - rate_a - s_from <= 0
% |St| - rate_a - s_to   <= 0

define_constants;

Va = x(idx_i1.Va:idx_iN.Va);
% Vm may not exist in DC; if absent, use 1.0 p.u.
if isfield(idx_i1, 'Vm') && isfield(idx_iN, 'Vm') && ~isempty(idx_i1.Vm)
    Vm = x(idx_i1.Vm:idx_iN.Vm);
else
    Vm = ones(size(mpc.bus,1), 1);
end

s_from = x(idx_i1.s_from:idx_iN.s_from);
s_to   = x(idx_i1.s_to:idx_iN.s_to);

nl = size(mpc.branch, 1);

[~, Yf, Yt] = makeYbus(mpc.baseMVA, mpc.bus, mpc.branch);
V = Vm .* exp(1j * Va);

f_bus = mpc.branch(:, F_BUS);
t_bus = mpc.branch(:, T_BUS);

Sf = V(f_bus) .* conj(Yf * V) * mpc.baseMVA;
St = V(t_bus) .* conj(Yt * V) * mpc.baseMVA;

Sf_mag = abs(Sf);
St_mag = abs(St);

h = [Sf_mag - rate_a - s_from;
     St_mag - rate_a - s_to];

if nargout > 1
    epsilon = 1e-7;
    dh = zeros(2*nl, nv);
    for k = 1:nv
        x_plus = x;
        x_plus(k) = x_plus(k) + epsilon;
        h_plus = branch_flow_soft_constraint(x_plus, mpc, idx_i1, idx_iN, rate_a, nv);
        dh(:, k) = (h_plus - h) / epsilon;
    end
end

end

function mdo = opf_case51he(bus_VMAX_21, branch_RATE_A_27_24)
%OPF_CASE51HE  Multi-period DC OPF (MOST) with scenario parameter edits and reserve-consuming limits.

define_constants;

%% ===== Load base case =====
mpc = loadcase('case51he');

%% ===== Scenario-driven parameter modifications with direction asserts =====
% 1) Bus 21 VMAX increased due to substation upgrade
b21 = find(mpc.bus(:, BUS_I) == 21);
assert(~isempty(b21) && numel(b21) == 1, 'Bus 21 not found or not unique');
VMAX0_21 = mpc.bus(b21, VMAX);
assert(bus_VMAX_21 >= VMAX0_21, 'Parameter must increase');
mpc.bus(b21, VMAX) = bus_VMAX_21;

% 2) Branch 27-24 RATE_A decreased due to thermal derating in high temperature
br_27_24 = find(mpc.branch(:, F_BUS) == 27 & mpc.branch(:, T_BUS) == 24);
if isempty(br_27_24)
    % allow reversed orientation in data
    br_27_24 = find(mpc.branch(:, F_BUS) == 24 & mpc.branch(:, T_BUS) == 27);
end
assert(~isempty(br_27_24) && numel(br_27_24) == 1, 'Branch 27-24 not found or not unique');
RATEA0_27_24 = mpc.branch(br_27_24, RATE_A);
assert(branch_RATE_A_27_24 <= RATEA0_27_24, 'Parameter must decrease');
mpc.branch(br_27_24, RATE_A) = branch_RATE_A_27_24;

%% ===== Solver and model options (MOST multi-period DC) =====
mpopt = mpoption('verbose', 1, 'out.all', 0);
mpopt = mpoption(mpopt, 'most.dc_model', 1);
mpopt = mpoption(mpopt, 'model', 'DC');
mpopt = mpoption(mpopt, 'opf.dc.solver', 'MIPS');
mpopt = mpoption(mpopt, 'opf.violation', 1e-8);

%% ===== Reserve-consuming limits (template-based tightening around planned Pg0/Qg0) =====
ng = size(mpc.gen, 1);
Pg0 = mpc.gen(:, PG);
Qg0 = mpc.gen(:, QG);

% symmetric reserve margins (template values)
PRU = 10 * ones(ng, 1);   % upward real-power margin
PRD = 10 * ones(ng, 1);   % downward real-power margin
QRU =  5 * ones(ng, 1);   % upward reactive-power margin
QRD =  5 * ones(ng, 1);   % downward reactive-power margin

Pmin_phys = mpc.gen(:, PMIN);
Pmax_phys = mpc.gen(:, PMAX);
Qmin_phys = mpc.gen(:, QMIN);
Qmax_phys = mpc.gen(:, QMAX);

Pmin_res = Pg0 - PRD;
Pmax_res = Pg0 + PRU;
Qmin_res = Qg0 - QRD;
Qmax_res = Qg0 + QRU;

mpc.gen(:, PMIN) = max(Pmin_phys, Pmin_res);
mpc.gen(:, PMAX) = min(Pmax_phys, Pmax_res);
mpc.gen(:, QMIN) = max(Qmin_phys, Qmin_res);
mpc.gen(:, QMAX) = min(Qmax_phys, Qmax_res);

%% ===== Multi-period MOST setup (minimal self-contained profiles) =====
% Create a simple flat profile set so the function is self-contained.
% Users can replace these with richer getprofiles(...) data.
nt = 24;  % number of periods

% Load profile: scale all bus PD/QD by a time-varying multiplier
load_mult = ones(nt, 1);
profiles = struct([]);
profiles(1).type = 'mpcData';
profiles(1).table = CT_TBUS;
profiles(1).rows = 1:size(mpc.bus, 1);
profiles(1).col = PD;
profiles(1).chgtype = CT_REL;
profiles(1).values = load_mult;

profiles(2).type = 'mpcData';
profiles(2).table = CT_TBUS;
profiles(2).rows = 1:size(mpc.bus, 1);
profiles(2).col = QD;
profiles(2).chgtype = CT_REL;
profiles(2).values = load_mult;

% Generator availability profile (keep all online)
gen_mult = ones(nt, 1);
profiles(3).type = 'mpcData';
profiles(3).table = CT_TGEN;
profiles(3).rows = 1:size(mpc.gen, 1);
profiles(3).col = GEN_STATUS;
profiles(3).chgtype = CT_ABS;
profiles(3).values = gen_mult;

% MOST model data (no xgd/contingencies/storage; focuses on multi-period OPF)
mdi = loadmd(mpc, nt, [], [], [], profiles);

%% ===== Run MOST =====
mdo = most(mdi, mpopt);

% optional reporting (caller can inspect mdo.results)
% most_summary(mdo);

end

function mdo = opf_case74ds()
%OPF_CASE74DS  Level-4 multi-period AC OPF (MOST) with scenario-driven parameter modifications
%
% Combines:
% - MOST multi-period OPF structure (template 1_multi_period_OPF)
% - Additional quadratic cost approximating network losses (template 11_power_loss)
% - Scenario-driven parameter modifications with direction validation asserts
%
% Requirements:
% - Solver: MIPS
% - opf.violation: 1e-06
%
% Returns:
% - mdo : MOST output struct

clear; clc;

%% ==================== Setup ====================
define_constants;

casefile = 'case74ds';
mpc0 = loadcase(casefile);

% AC model + MIPS + strict violation tolerance
mpopt = mpoption('verbose', 1, 'out.all', 0);
mpopt = mpoption(mpopt, 'model', 'AC');
mpopt = mpoption(mpopt, 'opf.ac.solver', 'MIPS');
mpopt = mpoption(mpopt, 'opf.violation', 1e-6);

%% ==================== Scenario Modifications (with direction asserts) ====================
% Scenario 1: Winter heating peak loads -> UP (Increase)
% Scenario 2: Data center strict voltage lower limit -> bus.VMIN UP (Increase)
%
% Direction constraints:
% - Bus 51, PD: Increase
% - Bus 72, QD: Increase
% - Bus 47, VMIN: Increase

mpc = mpc0;

% Cache old values for asserts
old_PD_51   = mpc0.bus(51, PD);
old_QD_72   = mpc0.bus(72, QD);
old_VMIN_47 = mpc0.bus(47, VMIN);

% --- Apply required directional increases (minimal, deterministic edits) ---
% Increase Bus 51 PD
winter_PD_delta_51 = max(1e-3, 0.05 * max(old_PD_51, 0));  % at least a small positive increment
mpc.bus(51, PD) = old_PD_51 + winter_PD_delta_51;

% Increase Bus 72 QD
winter_QD_delta_72 = max(1e-3, 0.05 * max(old_QD_72, 0));
mpc.bus(72, QD) = old_QD_72 + winter_QD_delta_72;

% Increase Bus 47 VMIN
% Tighten lower bound modestly but safely below typical VMAX
vmin_delta_47 = 0.01;
mpc.bus(47, VMIN) = min(mpc0.bus(47, VMAX) - 1e-4, old_VMIN_47 + vmin_delta_47);

% Optional global adjustments consistent with templates (kept conservative)
% Voltage upper bound slightly relaxed to avoid infeasibility if VMIN tightened
mpc.bus(:, VMAX) = max(mpc.bus(:, VMAX), 1.05);

% --- Direction validation asserts ---
assert(mpc.bus(51, PD)   >= old_PD_51,   'Direction violation: Bus 51 PD must Increase');
assert(mpc.bus(72, QD)   >= old_QD_72,   'Direction violation: Bus 72 QD must Increase');
assert(mpc.bus(47, VMIN) >= old_VMIN_47, 'Direction violation: Bus 47 VMIN must Increase');

%% ==================== Multi-period (MOST) structure ====================
% If you have custom profiles (load/wind), plug them in here.
% This implementation builds a simple winter-peak multi-period load profile
% and uses MOST to run a multi-period OPF.

nt = 24;                      % number of periods (e.g., 24 hours)

% Winter peak profile: higher in morning/evening, normalized around 1.0
t = (1:nt)';
profile_mult = 1.00 + 0.15 * exp(-((t-8)/3).^2) + 0.20 * exp(-((t-19)/3).^2);

% Build MOST profiles struct to scale PD and QD for all buses
% MOST profile format uses idx and change tables; we use a simple approach
% via loadmd with a profiles array (compatible with MOST examples).

profiles = struct([]);

% Profile for PD
profiles(1).type    = 'mpcData';
profiles(1).table   = CT_TBUS;
profiles(1).rows    = (1:size(mpc.bus,1))';
profiles(1).col     = PD;
profiles(1).chgtype = CT_REL;          % relative change
profiles(1).values  = profile_mult;    % nt x 1

% Profile for QD (apply same multiplier)
profiles(2).type    = 'mpcData';
profiles(2).table   = CT_TBUS;
profiles(2).rows    = (1:size(mpc.bus,1))';
profiles(2).col     = QD;
profiles(2).chgtype = CT_REL;
profiles(2).values  = profile_mult;

% Note: If you have xGen/wind, you can add them similarly; here we keep it load-driven.

xgd = [];   % no xGen data provided

mdi = loadmd(mpc, nt, xgd, [], [], profiles);

%% ==================== Add loss-penalty quadratic cost (template 11_power_loss) ====================
% We inject an additional quadratic cost on Pg into the MOST model.
% In MOST, each period has an OPF; we add the same cost each period.

alpha_loss = 10;   % loss penalty weight

% If ng != 3, expand B_loss to match ng with a diagonal approximation.
ng = size(mpc.gen, 1);

B_loss_3 = [
    0.0010,  0.0002,  0.0001;
    0.0002,  0.0012,  0.0003;
    0.0001,  0.0003,  0.0008
];
B0_3 = [0.5; 0.6; 0.4];
B00 = 1.0;

if ng == 3
    B_loss = B_loss_3;
    B0_loss = B0_3;
else
    % Diagonal approximation when generator count differs
    diagval = mean(diag(B_loss_3));
    B_loss = diagval * speye(ng);
    B0_loss = mean(B0_3) * ones(ng, 1);
end

% Add quad cost via MOST's formulation callback: we modify each period's OM after creation.
% MOST supports userfcn callbacks; we register a callback to add quad cost to each period.
mdi = add_userfcn(mdi, 'most', 'formulation', @userfcn_add_loss_cost, {alpha_loss, B_loss, B0_loss, B00});

%% ==================== Solve MOST ====================
mdo = most(mdi, mpopt);

% Optional reporting
most_summary(mdo);

end

function mpc = userfcn_add_loss_cost(om, mpopt, args)
% USERFCN_ADD_LOSS_COST  MOST formulation-stage callback to add quadratic loss cost.
%
% In MATPOWER/MOST, a formulation-stage userfcn can modify the OM.
% We add a quadratic cost on Pg: alpha*(Pg'B Pg + B0'Pg + B00).

define_constants;

alpha_loss = args{1};
B_loss     = args{2};
B0_loss    = args{3};
B00_loss   = args{4};

% Extract variable indexing
idx_i1 = om.var.idx.i1;
idx_iN = om.var.idx.iN;
nv = om.var.N;
ng = om.var.idx.N.Pg;

% Build Q, c, k in MATPOWER quadratic-cost form: (1/2)*x'*Q*x + c'*x + k
Q = sparse(nv, nv);
Q(idx_i1.Pg:idx_iN.Pg, idx_i1.Pg:idx_iN.Pg) = 2 * alpha_loss * sparse(B_loss(1:ng, 1:ng));

c = zeros(nv, 1);
c(idx_i1.Pg:idx_iN.Pg) = alpha_loss * B0_loss(1:ng);

k = alpha_loss * B00_loss;

om.add_quad_cost('network_loss_cost', Q, c, k);

% Return mpc is ignored in formulation userfcn; keep signature compatible
mpc = [];
end

function results = opf_case141(branch_RATE_A_102_21, bus_VMAX_85)
%OPF_CASE141  AC-OPF with scenario parameter changes, load shedding, added line-charging reactive procurement cost, and an emission cap.
%   results = opf_case141(branch_RATE_A_102_21, bus_VMAX_85)

define_constants;

%% --- load base case ---
mpc = loadcase('case141');

%% --- solver/options ---
mpopt = mpoption('verbose', 1, 'out.all', 0);
mpopt = mpoption(mpopt, 'model', 'AC');
mpopt = mpoption(mpopt, 'opf.ac.solver', 'MIPS');
mpopt = mpoption(mpopt, 'opf.violation', 1e-07);

%% ===================== Scenario-driven parameter modifications =====================
% 1) Decrease branch RATE_A on corridor 102-21
f = 102; t = 21;
br_idx = find( (mpc.branch(:, F_BUS) == f & mpc.branch(:, T_BUS) == t) | ...
              (mpc.branch(:, F_BUS) == t & mpc.branch(:, T_BUS) == f), 1, 'first');
assert(~isempty(br_idx), 'Branch between buses 102 and 21 not found in case141.');
old_rateA = mpc.branch(br_idx, RATE_A);
assert(branch_RATE_A_102_21 <= old_rateA, 'Parameter must decrease');
mpc.branch(br_idx, RATE_A) = branch_RATE_A_102_21;

% 2) Decrease bus VMAX at bus 85
bus_id = 85;
b_idx = find(mpc.bus(:, BUS_I) == bus_id, 1, 'first');
assert(~isempty(b_idx), 'Bus 85 not found in case141.');
old_vmax = mpc.bus(b_idx, VMAX);
assert(bus_VMAX_85 <= old_vmax, 'Parameter must decrease');
mpc.bus(b_idx, VMAX) = bus_VMAX_85;

%% ===================== Add load shedding as dispatchable negative load =====================
nb = size(mpc.bus, 1);
ng0 = size(mpc.gen, 1);

load_buses = find(mpc.bus(:, PD) > 0);
nlsh = length(load_buses);

ncol_gen = size(mpc.gen, 2);
new_gen  = zeros(nlsh, ncol_gen);

for k = 1:nlsh
    b = load_buses(k);
    Pd_k = mpc.bus(b, PD);

    g = mpc.gen(1, :);      % template row to preserve column compatibility
    g(GEN_BUS)    = mpc.bus(b, BUS_I);
    g(PG)         = 0;
    g(QG)         = 0;
    g(QMAX)       = 0;
    g(QMIN)       = 0;
    g(VG)         = 1.0;
    g(GEN_STATUS) = 1;
    g(PMAX)       = Pd_k;
    g(PMIN)       = 0;

    new_gen(k, :) = g;
end

mpc.gen = [mpc.gen; new_gen];
ng = size(mpc.gen, 1);
shed_gen_idx = (ng0+1:ng)';

% gencost for shedding generators (high penalty)
ncol_gc = size(mpc.gencost, 2);
old_cost = mpc.gencost;

p_cost = 100 * ones(nlsh, 1);
q_cost = 1000 * ones(nlsh, 1);
r_cost = 5000 * ones(nlsh, 1);

new_cost = zeros(nlsh, ncol_gc);
new_cost(:, 1) = 2;   % polynomial
new_cost(:, 2) = 0;
new_cost(:, 3) = 0;
new_cost(:, 4) = 3;   % quadratic
new_cost(:, 5) = r_cost;
new_cost(:, 6) = q_cost;
new_cost(:, 7) = p_cost;

mpc.gencost = [old_cost; new_cost];

%% ===================== Build OPF model (OM) =====================
om = opf_setup(mpc, mpopt);
idx = om.get_idx();
baseMVA = mpc.baseMVA;

%% ===================== Objective add-on: line-charging reactive procurement cost (Vm^2) =====================
branch = mpc.branch;
nl = size(branch, 1);

r_ch = 10;                 % placeholder coefficient [$/Mvar] as in template
alpha = zeros(nb, 1);

for k = 1:nl
    fb = branch(k, F_BUS);
    tb = branch(k, T_BUS);
    Bch = branch(k, BR_B);
    coeff = r_ch * abs(Bch) / 2;

    % fb/tb are bus numbers; map to internal indices
    i_f = find(mpc.bus(:, BUS_I) == fb, 1, 'first');
    i_t = find(mpc.bus(:, BUS_I) == tb, 1, 'first');
    if ~isempty(i_f)
        alpha(i_f) = alpha(i_f) + coeff;
    end
    if ~isempty(i_t)
        alpha(i_t) = alpha(i_t) + coeff;
    end
end

idx_i1 = idx.i1;
idx_iN = idx.iN;
nv = om.var.N;

Q = sparse(nv, nv);
c = zeros(nv, 1);
k0 = 0;

% cost = sum(alpha .* Vm.^2) corresponds to 0.5*x'*Q*x with Q(Vm,Vm)=2*diag(alpha)
Qvm = spdiags(2*alpha, 0, nb, nb);
Q(idx_i1.Vm:idx_iN.Vm, idx_i1.Vm:idx_iN.Vm) = Qvm;

om.add_quad_cost('Qch_cost', Q, c, k0);

%% ===================== Constraint add-on: CO2 emission cap (linear in Pg) =====================
% Placeholder emission factors (tCO2/MWh). If ng is larger than provided, pad with zeros.
e_template = [0.9; 0.5; 0.0];
e_t_per_MWh = zeros(ng, 1);
e_t_per_MWh(1:min(ng, numel(e_template))) = e_template(1:min(ng, numel(e_template)));

Cap_t_per_h = 140;          % placeholder cap
Allowance_t_per_h = 0;      % placeholder allowance
cap_total = Cap_t_per_h + Allowance_t_per_h;

iPg = idx.i1.Pg:idx.iN.Pg;
A = sparse(1, nv);
A(1, iPg) = (e_t_per_MWh(:)' * baseMVA);

om.add_lin_constraint('emission_cap_CO2', A, -inf, cap_total);

%% ===================== Solve and return results =====================
[x, f, eflag, output, lam] = om.solve();

% Build a MATPOWER-like results struct
results = mpc;
results.f = f;
results.success = (eflag > 0);
results.et = NaN;
results.raw = struct('x', x, 'output', output, 'lam', lam, 'eflag', eflag);

if results.success
    results.bus(:, VA) = x(idx_i1.Va:idx_iN.Va) * 180/pi;
    results.bus(:, VM) = x(idx_i1.Vm:idx_iN.Vm);
    results.gen(:, PG) = x(idx_i1.Pg:idx_iN.Pg) * baseMVA;
    results.gen(:, QG) = x(idx.i1.Qg:idx.iN.Qg) * baseMVA;

    % Optional: compute load shedding summary and attach
    Pg_all_MW = results.gen(:, PG);
    Lshd_MW = Pg_all_MW(shed_gen_idx);
    orig_load = mpc.bus(load_buses, PD);
    remain_load = orig_load - Lshd_MW;

    results.userdata = struct();
    results.userdata.load_shedding = struct( ...
        'load_buses', mpc.bus(load_buses, BUS_I), ...
        'shed_gen_idx', shed_gen_idx, ...
        'orig_load_MW', orig_load, ...
        'shed_load_MW', Lshd_MW, ...
        'remaining_load_MW', remain_load, ...
        'total_orig_MW', sum(orig_load), ...
        'total_shed_MW', sum(Lshd_MW));

    % Emissions
    emission_t_per_h = sum(e_t_per_MWh .* results.gen(:, PG));
    results.userdata.emissions = struct('e_t_per_MWh', e_t_per_MWh, 'cap_t_per_h', cap_total, 'total_t_per_h', emission_t_per_h);
end

if ~results.success
    error('AC-OPF with load shedding/emission cap did not converge. eflag=%d', eflag);
end

end

function results = opf_case22(bus_BS_18, branch_BR_B_9_18)
%OPF_CASE22  AC-OPF with scenario-driven parameter updates and load shedding.

define_constants;

%% load base case
mpc0 = loadcase('case22');
mpc  = mpc0;

%% === scenario-driven parameter modifications with direction asserts ===
% Bus 18 BS increases (dynamic reactive compensation commissioned)
bus_id = 18;
bus_row = find(mpc.bus(:, BUS_I) == bus_id);
assert(~isempty(bus_row) && numel(bus_row) == 1, 'Bus %d not found or not unique.', bus_id);
old_bs = mpc0.bus(bus_row, BS);
assert(bus_BS_18 >= old_bs, 'Parameter must increase');
mpc.bus(bus_row, BS) = bus_BS_18;

% Branch 9-18 BR_B increases (higher line charging under light load)
f = 9; t = 18;
br_rows = find( (mpc.branch(:, F_BUS) == f & mpc.branch(:, T_BUS) == t) | ...
                (mpc.branch(:, F_BUS) == t & mpc.branch(:, T_BUS) == f) );
assert(~isempty(br_rows), 'Branch %d-%d not found.', f, t);
% apply to all matching parallel circuits, if any
for kk = 1:numel(br_rows)
    r = br_rows(kk);
    old_b = mpc0.branch(r, BR_B);
    assert(branch_BR_B_9_18 >= old_b, 'Parameter must increase');
    mpc.branch(r, BR_B) = branch_BR_B_9_18;
end

%% === structural modification: ACOPF with load shedding via virtual generators ===
mpopt = mpoption('verbose', 1, 'out.all', 0);
mpopt = mpoption(mpopt, 'model', 'AC');
mpopt = mpoption(mpopt, 'opf.ac.solver', 'MIPS');
mpopt = mpoption(mpopt, 'opf.violation', 1e-6);

nb  = size(mpc.bus, 1);
ng0 = size(mpc.gen, 1);

% load buses (positive active load)
load_buses = find(mpc.bus(:, PD) > 0);
nl = length(load_buses);

% create one virtual generator per load bus representing shed load
ncol_gen = size(mpc.gen, 2);
new_gen  = zeros(nl, ncol_gen);

for k = 1:nl
    b = load_buses(k);
    Pd_k = mpc.bus(b, PD);

    % copy a template generator row to preserve column compatibility
    g = mpc.gen(1, :);

    g(GEN_BUS)    = b;
    g(PG)         = 0;
    g(QG)         = 0;
    g(QMAX)       = 0;
    g(QMIN)       = 0;
    g(VG)         = 1.0;
    g(GEN_STATUS) = 1;
    g(PMAX)       = Pd_k;
    g(PMIN)       = 0;

    new_gen(k, :) = g;
end

mpc.gen = [mpc.gen; new_gen];
ng = size(mpc.gen, 1);
shed_gen_idx = (ng0+1:ng)';

% set gencost for virtual shed generators (high convex quadratic penalty)
old_cost = mpc.gencost;
ncol_gc  = size(old_cost, 2);

% ensure polynomial model with 3 coefficients is available
% MATPOWER format: [MODEL STARTUP SHUTDOWN NCOST c(n-1) ... c0]
% We will build [2 0 0 3 c2 c1 c0]
if ncol_gc < 7
    % pad existing cost rows to 7 columns
    old_cost = [old_cost, zeros(size(old_cost, 1), 7 - ncol_gc)];
    ncol_gc = 7;
end

% penalty coefficients (chosen large to discourage shedding)
p_cost = 100  * ones(nl, 1);
q_cost = 1000 * ones(nl, 1);
r_cost = 5000 * ones(nl, 1);

new_cost = zeros(nl, ncol_gc);
new_cost(:, 1) = 2;  % polynomial
new_cost(:, 2) = 0;  % startup
new_cost(:, 3) = 0;  % shutdown
new_cost(:, 4) = 3;  % ncost
new_cost(:, 5) = r_cost;
new_cost(:, 6) = q_cost;
new_cost(:, 7) = p_cost;

mpc.gencost = [old_cost; new_cost];

%% solve
results = runopf(mpc, mpopt);
if ~results.success
    error('AC-OPF with load shedding did not converge.');
end

% optional summary printout
Pg_all = results.gen(:, PG);
Lshd   = Pg_all(shed_gen_idx);
orig_load = mpc.bus(load_buses, PD);
remain_load = orig_load - Lshd;

total_orig   = sum(orig_load);
total_shed   = sum(Lshd);
total_remain = total_orig - total_shed;

shed_cost = sum(p_cost + q_cost .* Lshd + r_cost .* (Lshd.^2));

fprintf('\n=== AC-OPF with Load Shedding (case22) ===\n');
fprintf('Total objective = %.6f\n', results.f);
fprintf('\n-- Load Shedding Summary --\n');
fprintf('  Total original load   = %8.3f MW\n', total_orig);
fprintf('  Total shed load       = %8.3f MW\n', total_shed);
fprintf('  Total remaining load  = %8.3f MW\n', total_remain);
if total_orig > 0
    fprintf('  Overall shed ratio    = %8.2f %%\n', 100 * total_shed / total_orig);
else
    fprintf('  Overall shed ratio    = %8.2f %%\n', 0);
end
fprintf('  Load shedding cost    = %8.2f (from cost function)\n', shed_cost);

fprintf('\nBus  OrigLoad  ShedLoad  RemainLoad  ShedRatio(%%)\n');
for k = 1:nl
    b = load_buses(k);
    if orig_load(k) > 0
        ratio = 100 * Lshd(k) / orig_load(k);
    else
        ratio = 0;
    end
    fprintf('%3d  %8.3f  %8.3f  %10.3f   %8.2f\n', b, orig_load(k), Lshd(k), remain_load(k), ratio);
end

end

function out = opf_case85(gen_QMAX_9, gen_PMIN_15, user_M, user_GUB, user_MaxTime, user_MaxNodes, user_heuristic, w_bus_ext, mu_w_MW, sigma_w_MW, eps, lambda_L)
%OPF_CASE85  Level-4 OPF: Scenario parameter changes + DC OTS + chance constraints + L-index nonlinear cost.
%
% Inputs are post-modification placeholders consistent with scenario directions.
%
% Required scenario parameters:
%   gen_QMAX_9   : decreased QMAX for generator at bus 9
%   gen_PMIN_15  : increased PMIN for generator at bus 15
%
% Structural parameters (placeholders):
%   user_M, user_GUB, user_MaxTime, user_MaxNodes, user_heuristic
%   w_bus_ext, mu_w_MW, sigma_w_MW, eps, lambda_L

define_constants;

%% defaults for structural placeholders (if not provided)
if nargin < 3 || isempty(user_M),        user_M = 1e5; end
if nargin < 4 || isempty(user_GUB),      user_GUB = 4; end
if nargin < 5 || isempty(user_MaxTime),  user_MaxTime = 600; end
if nargin < 6 || isempty(user_MaxNodes), user_MaxNodes = 5e5; end
if nargin < 7 || isempty(user_heuristic), user_heuristic = 'basic'; end

if nargin < 8 || isempty(w_bus_ext),   w_bus_ext = 1; end
if nargin < 9 || isempty(mu_w_MW),     mu_w_MW = 0; end
if nargin < 10 || isempty(sigma_w_MW), sigma_w_MW = 0; end
if nargin < 11 || isempty(eps),        eps = 0.05; end
if nargin < 12 || isempty(lambda_L),   lambda_L = 1; end

%% load case
mpc0 = loadcase('case85');

%% scenario-driven parameter modifications with direction asserts
mpc = mpc0;

% --- gen at bus 9: QMAX must DECREASE ---
idx_g9 = find(mpc.gen(:, GEN_BUS) == 9, 1);
if isempty(idx_g9), error('No generator found at bus 9.'); end
orig_QMAX_9 = mpc.gen(idx_g9, QMAX);
assert(gen_QMAX_9 <= orig_QMAX_9, 'Parameter must decrease');
mpc.gen(idx_g9, QMAX) = gen_QMAX_9;

% --- gen at bus 15: PMIN must INCREASE ---
idx_g15 = find(mpc.gen(:, GEN_BUS) == 15, 1);
if isempty(idx_g15), error('No generator found at bus 15.'); end
orig_PMIN_15 = mpc.gen(idx_g15, PMIN);
assert(gen_PMIN_15 >= orig_PMIN_15, 'Parameter must increase');
mpc.gen(idx_g15, PMIN) = gen_PMIN_15;

%% embed mean stochastic injection as negative load (mean model)
bus_idx_ext = find(mpc.bus(:, BUS_I) == w_bus_ext, 1);
if isempty(bus_idx_ext), error('Wind/stochastic injection bus not found in case85.'); end
mpc.bus(bus_idx_ext, PD) = mpc.bus(bus_idx_ext, PD) - mu_w_MW;

%% ensure thermal limits exist (chance constraints need RATE_A)
rateA = mpc.branch(:, RATE_A);
if all(rateA == 0)
    mpc.branch(:, RATE_A) = 1e4;
else
    mpc.branch(rateA == 0, RATE_A) = 1e4;
end

%% options: DC + OT solver for OTS, violation tolerance
mpopt = mpoption('verbose', 1, 'out.all', 0, 'model', 'DC', 'opf.dc.solver', 'OT');
mpopt = mpoption(mpopt, 'opf.violation', 1e-6);

%% convert to internal indexing and build OM
mpc_i = ext2int(mpc, mpopt);
om = opf_setup(mpc_i, mpopt);

[baseMVA, bus, gen, branch] = deal(mpc_i.baseMVA, mpc_i.bus, mpc_i.gen, mpc_i.branch);
[nb, ng, nl] = deal(size(bus,1), size(gen,1), size(branch,1));

%% =========================
%% DC OTS structural changes
%% =========================

% relax original power mismatch constraint bounds (remove equality)
Nmis = om.getN('lin', 'Pmis');
if Nmis > 0
    om.set_params('lin', 'Pmis', {'l', 'u'}, {-Inf(Nmis,1), Inf(Nmis,1)});
end

% add variables: Pf (continuous line flows), Z (binary line status)
om.add_var('Pf', nl, zeros(nl,1));
om.add_var('Z',  nl, ones(nl,1), [], [], 'B');

% build DC matrices
[B, Bf, Pbusinj, Pfinj] = makeBdc(baseMVA, bus, branch);
f = branch(:, F_BUS); t = branch(:, T_BUS);
Cft = sparse([(1:nl)'; (1:nl)'], [f; t], [ones(nl,1); -ones(nl,1)], nl, nb);
neg_Cg = sparse(gen(:, GEN_BUS), 1:ng, -1, nb, ng);
A = [Cft' neg_Cg];
b = -(bus(:, PD) + bus(:, GS)) / baseMVA - Pbusinj;

Il = speye(nl);
rhs = user_M * ones(nl, 1);

% branch capacity constraints
il = find(branch(:, RATE_A) ~= 0 & branch(:, RATE_A) < 1e10);
Pmax = inf(nl,1); Pmin = inf(nl,1);
if ~isempty(il)
    Pmax(il) = branch(il, RATE_A) / baseMVA - Pfinj(il);
    Pmin(il) = branch(il, RATE_A) / baseMVA + Pfinj(il);
end

% add OTS linear constraints
om.add_lin_constraint('Pfl', [Il,  diag(Pmin)], zeros(nl,1), [], {'Pf', 'Z'});
om.add_lin_constraint('Pfu', [Il, -diag(Pmax)], [], zeros(nl,1), {'Pf', 'Z'});
om.add_lin_constraint('Pfmis', A, b, b, {'Pf', 'Pg'});
om.add_lin_constraint('Ml', [Bf, -Il, -user_M*Il], -rhs, [], {'Va', 'Pf', 'Z'});
om.add_lin_constraint('Mu', [Bf, -Il,  user_M*Il], [],  rhs, {'Va', 'Pf', 'Z'});
om.add_lin_constraint('GUB', ones(1, nl), nl-user_GUB, [], {'Z'});

%% ==========================================
%% Chance constraints on line limits (on Pg)
%% ==========================================

% PTDF and incidence
PTDF = makePTDF(baseMVA, bus, branch);  % nl x nb
Cg = sparse(gen(:, GEN_BUS), (1:ng)', 1, nb, ng);
Pd = bus(:, PD) / baseMVA;

% wind bus internal index (derive from ext2int mapping of original mpc0)
tmp_i = ext2int(mpc0, mpopt);
w_bus_int = find(tmp_i.bus(:, BUS_I) == w_bus_ext, 1);
if isempty(w_bus_int)
    error('Wind bus internal mapping failed.');
end

z = norminv_approx(1 - eps/2);
sigma_w_pu = sigma_w_MW / baseMVA;
ptdf_w = PTDF(:, w_bus_int);
sigma_f = abs(ptdf_w) * sigma_w_pu;
Fmax = branch(:, RATE_A) / baseMVA;

idx = om.var.idx;
i1Pg = idx.i1.Pg; iNPg = idx.iN.Pg;
if (iNPg - i1Pg + 1) ~= ng
    error('Pg dimension mismatch.');
end
nv = om.var.N;

Arows = []; lcc = []; ucc = [];
for ell = 1:nl
    if branch(ell, BR_STATUS) == 0
        continue;
    end
    a_pg  = PTDF(ell,:) * Cg;      % 1 x ng
    const = PTDF(ell,:) * (-Pd);   % scalar
    margin = Fmax(ell) - z * sigma_f(ell);

    rhs_pos = margin - const;
    rhs_neg = margin + const;

    Arows(end+1,:) = a_pg; %#ok<AGROW>
    lcc(end+1,1)   = -Inf; %#ok<AGROW>
    ucc(end+1,1)   = rhs_pos; %#ok<AGROW>

    Arows(end+1,:) = -a_pg; %#ok<AGROW>
    lcc(end+1,1)   = -Inf; %#ok<AGROW>
    ucc(end+1,1)   = rhs_neg; %#ok<AGROW>
end

if ~isempty(Arows)
    Acc = sparse(Arows);
    Afull = sparse(size(Acc,1), nv);
    Afull(:, i1Pg:iNPg) = Acc;
    om.add_lin_constraint('CHANCE_LINE_LIMITS', Afull, lcc, ucc);
end

%% ==================================
%% L-index nonlinear cost (objective)
%% ==================================

% Build Ybus and F-matrix on the *mean* modified case in external indexing
% (Ybus is independent of DC/AC model choice; used only for cost calculation)
[Ybus, ~, ~] = makeYbus(mpc.baseMVA, mpc.bus, mpc.branch);

bus_type_ext = mpc.bus(:, BUS_TYPE);
idxG_ext = find(bus_type_ext == REF | bus_type_ext == PV);
idxL_ext = find(bus_type_ext == PQ);

if isempty(idxL_ext) || isempty(idxG_ext)
    % If classification is degenerate, skip adding L-index cost.
else
    Y_LL = Ybus(idxL_ext, idxL_ext);
    Y_LG = Ybus(idxL_ext, idxG_ext);
    Fmat = -(Y_LL \ Y_LG);

    % map these external bus indices to internal ordering in OM variables
    % ext2int mapping: internal bus rows correspond to mpc_i.bus order.
    % Create map from external BUS_I to internal row index.
    ext_bus_numbers = mpc.bus(:, BUS_I);
    int_bus_numbers = mpc_i.bus(:, BUS_I);
    map = containers.Map(num2cell(ext_bus_numbers), num2cell((1:numel(ext_bus_numbers))'));

    % idxG/idxL are row indices in external mpc.bus; convert to BUS_I then to internal index
    idxG_int = zeros(numel(idxG_ext),1);
    for k = 1:numel(idxG_ext)
        busno = mpc.bus(idxG_ext(k), BUS_I);
        idxG_int(k) = find(int_bus_numbers == busno, 1);
    end
    idxL_int = zeros(numel(idxL_ext),1);
    for k = 1:numel(idxL_ext)
        busno = mpc.bus(idxL_ext(k), BUS_I);
        idxL_int(k) = find(int_bus_numbers == busno, 1);
    end

    % add nonlinear cost to OM (finite-difference gradient)
    idx_i1 = om.var.idx.i1;
    idx_iN = om.var.idx.iN;
    nv = om.var.N;

    fcn = @(x) l_index_cost_fcn_fd(x, lambda_L, idx_i1, idx_iN, nv, Fmat, idxG_int, idxL_int);
    om.add_nln_cost('L_index_cost', 1, fcn);
end

%% solve
opt = mpopt2qpopt(mpopt, om.problem_type());
if isfield(opt, 'intlinprog_opt')
    opt.intlinprog_opt = struct('MaxTime', user_MaxTime, 'MaxNodes', user_MaxNodes, 'Heuristics', user_heuristic);
else
    opt.intlinprog_opt = struct('MaxTime', user_MaxTime, 'MaxNodes', user_MaxNodes, 'Heuristics', user_heuristic);
end

[result_i, F, eflag, output, lambda] = om.solve(opt); %#ok<ASGLU>
res = int2ext(result_i, mpc);

out = struct();
out.success = (eflag > 0);
out.eflag = eflag;
out.output = output;
out.f = F;
out.results = res;

end

%% ===== helper functions =====
function z = norminv_approx(p)
% Compute z = Phi^{-1}(p) without requiring Statistics Toolbox.
z = -sqrt(2) * erfcinv(2*p);
end

function [f, df, d2f] = l_index_cost_fcn_fd(x, lambda_L, idx_i1, idx_iN, nv, Fmat, idxG, idxL)
% Nonlinear cost: f(x) = lambda_L * max_j |1 - (F*V_G)_j / V_L_j|
% Uses finite differences for gradient.

Va = x(idx_i1.Va:idx_iN.Va);
Vm = x(idx_i1.Vm:idx_iN.Vm);

V = Vm .* exp(1j * Va);
V_G = V(idxG);
V_L = V(idxL);

T = Fmat * V_G;
U = T ./ V_L;
Lvec = abs(1 - U);
Lmax = max(Lvec);

f = lambda_L * Lmax;

if nargout > 1
    eps_fd = 1e-7;
    df = zeros(nv, 1);
    for k = 1:nv
        x_plus = x;
        x_plus(k) = x_plus(k) + eps_fd;
        f_plus = l_index_cost_fcn_fd(x_plus, lambda_L, idx_i1, idx_iN, nv, Fmat, idxG, idxL);
        df(k) = (f_plus - f) / eps_fd;
    end
end

if nargout > 2
    d2f = sparse(nv, nv);
end
end

function results = opf_case118(gen_GENCOST_C1_5, gen_GENCOST_C2_8, gen_GENCOST_C0_6, bus_VMIN_103)
%OPF_CASE118  DC Optimal Transmission Switching on case118 with loss-penalty objective and scenario-driven parameter changes.
%
% Inputs are scenario post-modification placeholder values that must satisfy
% the required direction constraints relative to the original case118 data.

define_constants;

%% load base case
mpc = loadcase('case118');

%% solver / tolerances
mpopt = mpoption('verbose', 1, 'out.all', 0);
mpopt = mpoption(mpopt, 'model', 'DC');
mpopt = mpoption(mpopt, 'opf.dc.solver', 'MIPS');
mpopt = mpoption(mpopt, 'opf.violation', 1e-8);

%% map external to internal indexing (required for OM construction)
mpc = ext2int(mpc, mpopt);

%% ---------------- Scenario-driven parameter modifications ----------------
% 1) Renewable subsidy reduces effective marginal costs (decrease selected cost coefficients)
% 2) Raised lower voltage limit requirement (increase VMIN at bus 103)

% --- generator cost coefficient at bus 5: decrease COST_PARAMS_C1
ig5 = find(mpc.gen(:, GEN_BUS) == 5);
assert(~isempty(ig5), 'No generator found at bus 5');
ig5 = ig5(1);
if mpc.gencost(ig5, MODEL) == POLYNOMIAL
    orig_c1_5 = mpc.gencost(ig5, COST+1);  % for NCOST=3: [c2 c1 c0]
    assert(gen_GENCOST_C1_5 <= orig_c1_5, 'Parameter must decrease');
    mpc.gencost(ig5, COST+1) = gen_GENCOST_C1_5;
else
    error('Generator at bus 5 must have polynomial cost model for this template.');
end

% --- generator cost coefficient at bus 8: decrease COST_PARAMS_C2
ig8 = find(mpc.gen(:, GEN_BUS) == 8);
assert(~isempty(ig8), 'No generator found at bus 8');
ig8 = ig8(1);
if mpc.gencost(ig8, MODEL) == POLYNOMIAL
    orig_c2_8 = mpc.gencost(ig8, COST);    % c2
    assert(gen_GENCOST_C2_8 <= orig_c2_8, 'Parameter must decrease');
    mpc.gencost(ig8, COST) = gen_GENCOST_C2_8;
else
    error('Generator at bus 8 must have polynomial cost model for this template.');
end

% --- generator cost coefficient at bus 6: decrease COST_PARAMS_C3 (mapped here to constant term c0)
ig6 = find(mpc.gen(:, GEN_BUS) == 6);
assert(~isempty(ig6), 'No generator found at bus 6');
ig6 = ig6(1);
if mpc.gencost(ig6, MODEL) == POLYNOMIAL
    % for NCOST=3: constant term is COST+2 (c0)
    orig_c0_6 = mpc.gencost(ig6, COST+2);
    assert(gen_GENCOST_C0_6 <= orig_c0_6, 'Parameter must decrease');
    mpc.gencost(ig6, COST+2) = gen_GENCOST_C0_6;
else
    error('Generator at bus 6 must have polynomial cost model for this template.');
end

% --- bus 103 VMIN: increase
ib103 = find(mpc.bus(:, BUS_I) == 103);
assert(~isempty(ib103), 'Bus 103 not found');
ib103 = ib103(1);
orig_vmin_103 = mpc.bus(ib103, VMIN);
assert(bus_VMIN_103 >= orig_vmin_103, 'Parameter must increase');
mpc.bus(ib103, VMIN) = bus_VMIN_103;

%% ---------------- Structural modification: DCOTS + loss penalty ------------
% user options consistent with the provided DCOTS template, using MIPS solve
useropt = struct();
useropt.model     = 'DC';
useropt.solver    = 'MIPS';
useropt.M         = 1e5;      % big-M
useropt.GUB       = 4;        % max number of opened lines (sum(Z) >= nl-GUB)

% build optimization model
om = opf_setup(mpc, mpopt);

% retrieve sizes
[baseMVA, bus, gen, branch] = deal(mpc.baseMVA, mpc.bus, mpc.gen, mpc.branch);
[nb, ng, nl] = deal(size(bus,1), size(gen,1), size(branch,1));

% relax/overwrite original power balance linear constraint bounds (as template)
om.set_params('lin', 'Pmis', {'l', 'u'}, {-Inf(om.getN('lin','Pmis'),1), Inf(om.getN('lin','Pmis'),1)});

% add OTS variables
om.add_var('Pf', nl, zeros(nl,1));                 % branch flow variables
om.add_var('Z',  nl, ones(nl,1), [], [], 'B');     % line status binaries (1=in service)

% build DC matrices
[B, Bf, Pbusinj, Pfinj] = makeBdc(baseMVA, bus, branch);

f = branch(:, F_BUS);
t = branch(:, T_BUS);
Cft = sparse([(1:nl)'; (1:nl)'], [f; t], [ones(nl,1); -ones(nl,1)], nl, nb);
neg_Cg = sparse(gen(:, GEN_BUS), 1:ng, -1, nb, ng);
A = [Cft' neg_Cg];
bm = -(bus(:, PD) + bus(:, GS)) / baseMVA - Pbusinj;

Il = speye(nl);
rhs = useropt.M * ones(nl, 1);

% branch thermal limits translated to Pmax/Pmin in per unit
il = find(branch(:, RATE_A) ~= 0 & branch(:, RATE_A) < 1e10);
Pmax = inf(nl,1);
Pmin = inf(nl,1);
if ~isempty(il)
    Pmax(il) = branch(il, RATE_A) / baseMVA - Pfinj(il);
    Pmin(il) = branch(il, RATE_A) / baseMVA + Pfinj(il);
end

% linear constraints
om.add_lin_constraint('Pfl',  [Il,  diag(Pmin)], zeros(nl,1), [], {'Pf', 'Z'});
om.add_lin_constraint('Pfu',  [Il, -diag(Pmax)], [], zeros(nl,1), {'Pf', 'Z'});
om.add_lin_constraint('Pfmis', A, bm, bm, {'Pf', 'Pg'});
om.add_lin_constraint('Ml',  [Bf, -Il, -useropt.M*Il], -rhs, [], {'Va', 'Pf', 'Z'});
om.add_lin_constraint('Mu',  [Bf, -Il,  useropt.M*Il], [], rhs, {'Va', 'Pf', 'Z'});
% limit number of opened lines: sum(Z) >= nl - GUB
om.add_lin_constraint('GUB', ones(1, nl), nl - useropt.GUB, [], {'Z'});

%% add quadratic network-loss penalty in objective (B-coefficient surrogate)
% Use a small demonstrative loss model mapped to the first 3 Pg variables.
% Placeholder weight alpha_loss is implemented as a fixed scalar in code.
alpha_loss = 10;  % penalty weight (template-inspired)

B_loss = [
    0.0010, 0.0002, 0.0001;
    0.0002, 0.0012, 0.0003;
    0.0001, 0.0003, 0.0008
];
B0_loss = [0.5; 0.6; 0.4];
B00_loss = 1.0;

idx_i1 = om.var.idx.i1;
idx_iN = om.var.idx.iN;
nv = om.var.N;
ng_om = om.var.idx.N.Pg;

nloss = min(3, ng_om);
Q = sparse(nv, nv);
c = zeros(nv, 1);
k = alpha_loss * B00_loss;

pg_i1 = idx_i1.Pg;
pg_iN = idx_i1.Pg + nloss - 1;
Q(pg_i1:pg_iN, pg_i1:pg_iN) = 2 * alpha_loss * sparse(B_loss(1:nloss, 1:nloss));
c(pg_i1:pg_iN) = alpha_loss * B0_loss(1:nloss);

om.add_quad_cost('network_loss_cost', Q, c, k);

%% solve
[x, fval, eflag, output, lambda] = om.solve();

%% build results in internal indexing
results = mpc;
results.success = (eflag > 0);
results.f = fval;
results.om = om;
results.x = x;
results.output = output;
results.lambda = lambda;

% unpack key solution values if available
try
    if isfield(idx_i1, 'Va')
        results.bus(:, VA) = x(idx_i1.Va:idx_iN.Va) * 180/pi;
    end
    results.gen(:, PG) = x(idx_i1.Pg:idx_iN.Pg) * baseMVA;
catch
end

% convert back to external indexing
results = int2ext(results);

end

function results = opf_case6ww(bus_PD_5, bus_QD_5, gen_QMIN_3)
%OPF_CASE6WW  Level-4 OPF: DCOTS + quad Vm proxy cost + CO2 cap, with scenario parameter modifications.

define_constants;

%% ----- load case -----
mpc0 = loadcase('case6ww');
mpc  = mpc0;

%% ----- scenario-driven parameter modifications with direction asserts -----
% Bus 5 load disabled (set to zero)
assert(bus_PD_5 == 0, 'Parameter must be set to zero');
assert(bus_QD_5 == 0, 'Parameter must be set to zero');

b5 = find(mpc.bus(:, BUS_I) == 5);
assert(~isempty(b5) && numel(b5) == 1, 'Bus 5 not found or not unique');
mpc.bus(b5, PD) = bus_PD_5;
mpc.bus(b5, QD) = bus_QD_5;

% Generator at bus 3 QMIN increased (less absorption)
g3 = find(mpc.gen(:, GEN_BUS) == 3);
assert(~isempty(g3) && numel(g3) >= 1, 'Generator at bus 3 not found');
for k = 1:numel(g3)
    assert(gen_QMIN_3 >= mpc0.gen(g3(k), QMIN), 'Parameter must increase');
    mpc.gen(g3(k), QMIN) = gen_QMIN_3;
end

%% ----- solver/options -----
% Use OT as dc solver to match OTS template requirement
mpopt = mpoption('model', 'DC', 'verbose', 2, 'out.all', 0, ...
    'opf.dc.solver', 'OT', 'opf.violation', 1e-07);

% OTS controls (big-M, switching budget)
useropt = struct();
useropt.M = 1e5;      % big-M
useropt.GUB = 4;      % max number of opened lines (budget)

%% ----- build OM -----
mpc = ext2int(mpc, mpopt);
om  = opf_setup(mpc, mpopt);

[baseMVA, bus, gen, branch] = deal(mpc.baseMVA, mpc.bus, mpc.gen, mpc.branch);
[nb, ng, nl] = deal(size(bus,1), size(gen,1), size(branch,1));

%% ===================== 1) DC Optimal Transmission Switching (OTS) =====================
% Relax/remove original power balance mismatch constraint bounds, then re-add with Pf and Z
om.set_params('lin', 'Pmis', {'l', 'u'}, {-Inf(om.getN('lin','Pmis'),1), Inf(om.getN('lin','Pmis'),1)});

% Add branch flow variables Pf (continuous) and line status Z (binary)
om.add_var('Pf', nl, zeros(nl,1));
om.add_var('Z',  nl, ones(nl,1), [], [], 'B');

% DC network matrices
[B, Bf, Pbusinj, Pfinj] = makeBdc(baseMVA, bus, branch);
f = branch(:, F_BUS);
t = branch(:, T_BUS);
Cft = sparse([(1:nl)'; (1:nl)'], [f; t], [ones(nl,1); -ones(nl,1)], nl, nb);
neg_Cg = sparse(gen(:, GEN_BUS), 1:ng, -1, nb, ng);
A = [Cft' neg_Cg];

% Power balance RHS: -(Pd + Gs)/baseMVA - Pbusinj
b = -(bus(:, PD) + bus(:, GS)) / baseMVA - Pbusinj;

% Line limits
il = find(branch(:, RATE_A) ~= 0 & branch(:, RATE_A) < 1e10);
Pmax = inf(nl,1);
Pmin = inf(nl,1);
if ~isempty(il)
    Pmax(il) = branch(il, RATE_A) / baseMVA - Pfinj(il);
    Pmin(il) = branch(il, RATE_A) / baseMVA + Pfinj(il);
end

Il  = speye(nl);
rhs = useropt.M * ones(nl, 1);

% Capacity constraints tied to Z
om.add_lin_constraint('Pfl',  [Il,  diag(Pmin)], zeros(nl,1), [], {'Pf','Z'});
om.add_lin_constraint('Pfu',  [Il, -diag(Pmax)], [], zeros(nl,1), {'Pf','Z'});

% Nodal balance using Pf and Pg
om.add_lin_constraint('Pfmis', A, b, b, {'Pf','Pg'});

% Big-M DC flow equations with switching
om.add_lin_constraint('Ml', [Bf, -Il, -useropt.M*Il], -rhs, [], {'Va','Pf','Z'});
om.add_lin_constraint('Mu', [Bf, -Il,  useropt.M*Il], [], rhs, {'Va','Pf','Z'});

% Switching budget: sum(Z) >= nl - GUB  (at most GUB opened)
om.add_lin_constraint('GUB', ones(1,nl), nl-useropt.GUB, [], {'Z'});

%% ===================== 2) Objective modification: proxy reactive procurement cost =====================
% Add quadratic cost on Vm: sum_b alpha_b * Vm_b^2 derived from branch charging
% Note: Even in DC model, MATPOWER keeps Vm variables (typically fixed). This adds a convex proxy term.
r_ch = 10;                 % placeholder $/Mvar weighting
alpha = zeros(nb, 1);
for k = 1:nl
    ff = branch(k, F_BUS);
    tt = branch(k, T_BUS);
    Bch = branch(k, BR_B);
    coeff = r_ch * abs(Bch) / 2;
    alpha(ff) = alpha(ff) + coeff;
    alpha(tt) = alpha(tt) + coeff;
end

idx   = om.get_idx();
i1 = idx.i1; iN = idx.iN;
nv = om.var.N;
Q = sparse(nv, nv);
c = zeros(nv, 1);
k0 = 0;

% 2*alpha because OM quadratic form is (1/2)x'Qx + c'x + k0
if isfield(i1, 'Vm') && isfield(iN, 'Vm')
    Qvm = spdiags(2*alpha, 0, nb, nb);
    Q(i1.Vm:iN.Vm, i1.Vm:iN.Vm) = Qvm;
    om.add_quad_cost('Qch_cost', Q, c, k0);
end

%% ===================== 3) Constraint modification: CO2 emission cap (linear) =====================
% e_t_per_MWh is a placeholder vector sized to ng (can be tuned externally by editing here if needed)
e_t_per_MWh = ones(ng, 1) * 0.5;   % placeholder intensities
Cap_t_per_h = 1e9;                 % placeholder cap large enough unless tightened
Allowance_t_per_h = 0;
cap_total = Cap_t_per_h + Allowance_t_per_h;

Aem = sparse(1, nv);
Aem(1, i1.Pg:iN.Pg) = (e_t_per_MWh(:)' * baseMVA);
om.add_lin_constraint('emission_cap_CO2', Aem, -inf, cap_total);

%% ----- solve -----
opt = mpopt2qpopt(mpopt, om.problem_type());
[x, fval, eflag, output, lambda] = om.solve(opt);

% Build MATPOWER-like results struct
results = mpc;
results.success = (eflag > 0);
results.f = fval;

% Map solution back (internal ordering)
if results.success
    if isfield(i1,'Va'); results.bus(:, VA) = x(i1.Va:iN.Va) * 180/pi; end
    if isfield(i1,'Vm'); results.bus(:, VM) = x(i1.Vm:iN.Vm); end
    if isfield(i1,'Pg'); results.gen(:, PG) = x(i1.Pg:iN.Pg) * baseMVA; end
    if isfield(i1,'Qg'); results.gen(:, QG) = x(i1.Qg:iN.Qg) * baseMVA; end
end

% Convert back to external indexing
results = int2ext(results, mpopt);
results.om = om;
results.output = output;
results.lambda = lambda;
results.eflag = eflag;

end

function results = opf_case70da(branch_RATE_A_47_59, branch_BR_B_20_56, gen_QCOST_1, gen_QCOST_2, gen_QCOST_3, system_CO2_cap_t_per_h, gen_CO2_EF_1, gen_CO2_EF_2, gen_CO2_EF_3)
%OPF_CASE70DA  DCOTS (DC model) with scenario-driven parameter changes,
%reactive power quadratic cost, and a CO2 emission cap.

define_constants;

%% load case
mpc0 = loadcase('case70da');
mpc  = mpc0;

%% ========== Scenario-driven parameter modifications (with direction asserts) ==========
% 1) Increase branch RATE_A on branch 47-59 (DLR due to cold/windy conditions)
[br_47_59, ok1] = find_branch(mpc0, 47, 59);
assert(ok1, 'Branch 47-59 not found in case70da');
old_rateA_47_59 = mpc0.branch(br_47_59, RATE_A);
assert(branch_RATE_A_47_59 >= old_rateA_47_59, 'Parameter must increase');
mpc.branch(br_47_59, RATE_A) = branch_RATE_A_47_59;

% 2) Increase branch BR_B on branch 20-56 (higher charging under light-load)
[br_20_56, ok2] = find_branch(mpc0, 20, 56);
assert(ok2, 'Branch 20-56 not found in case70da');
old_brB_20_56 = mpc0.branch(br_20_56, BR_B);
assert(branch_BR_B_20_56 >= old_brB_20_56, 'Parameter must increase');
mpc.branch(br_20_56, BR_B) = branch_BR_B_20_56;

%% ========== DCOTS setup (structural modification based on template 2_OTS) ==========
useropt = struct('casename', 'case70da', 'model', 'DC', 'solver', 'MIPS', ...
    'M', 1e5, 'GUB', 4);

mpopt = mpoption('model', useropt.model, 'verbose', 0, 'out.all', 0, ...
    'opf.dc.solver', useropt.solver, 'opf.violation', 1e-7);

% Convert to internal numbering and build OPF model
mpc_int = ext2int(mpc, mpopt);
om = opf_setup(mpc_int, mpopt);

% retrieve data
[baseMVA, bus, gen, branch] = deal(mpc_int.baseMVA, mpc_int.bus, mpc_int.gen, mpc_int.branch);
[nb, ng, nl] = deal(size(bus,1), size(gen,1), size(branch,1));

% Remove original power balance linear constraint bounds (make free, then add custom)
om.set_params('lin', 'Pmis', {'l', 'u'}, {-Inf(om.getN('lin','Pmis'),1), Inf(om.getN('lin','Pmis'),1)});

% Add OTS variables: Pf (continuous) and Z (binary)
om.add_var('Pf', nl, zeros(nl,1));
om.add_var('Z',  nl, ones(nl,1), [], [], 'B');

% Build DC matrices
[B, Bf, Pbusinj, Pfinj] = makeBdc(baseMVA, bus, branch);
f = branch(:, F_BUS);
t = branch(:, T_BUS);
Cft = sparse([(1:nl)'; (1:nl)'], [f; t], [ones(nl,1); -ones(nl,1)], nl, nb);
neg_Cg = sparse(gen(:, GEN_BUS), 1:ng, -1, nb, ng);
Aeq = [Cft' neg_Cg];
beq = -(bus(:, PD) + bus(:, GS)) / baseMVA - Pbusinj;

Il = speye(nl);
rhs = useropt.M * ones(nl, 1);

% Branch capacity constraints (for those with finite RATE_A)
il = find(branch(:, RATE_A) ~= 0 & branch(:, RATE_A) < 1e10);
Pmax = inf(nl,1);
Pmin = inf(nl,1);
if ~isempty(il)
    Pmax(il) = branch(il, RATE_A) / baseMVA - Pfinj(il);
    Pmin(il) = branch(il, RATE_A) / baseMVA + Pfinj(il);
end

% Add linear constraints
% Pf <=  Z*Pmax  ->  Pf - diag(Pmax)*Z <= 0
% Pf >= -Z*Pmin  ->  Pf + diag(Pmin)*Z >= 0
om.add_lin_constraint('Pfl', [Il,  diag(Pmin)], zeros(nl,1), [], {'Pf', 'Z'});
om.add_lin_constraint('Pfu', [Il, -diag(Pmax)], [], zeros(nl,1), {'Pf', 'Z'});

% Power balance using Pf and Pg
om.add_lin_constraint('Pfmis', Aeq, beq, beq, {'Pf', 'Pg'});

% Big-M linking between Va and Pf when line in/out
% Bf*Va - Pf - M*Z <=  rhs
% Bf*Va - Pf + M*Z >= -rhs
om.add_lin_constraint('Ml', [Bf, -Il, -useropt.M*Il], -rhs, [], {'Va', 'Pf', 'Z'});
om.add_lin_constraint('Mu', [Bf, -Il,  useropt.M*Il], [],  rhs, {'Va', 'Pf', 'Z'});

% Global upper bound on number of opened lines: sum(Z) >= nl - GUB  (i.e., at most GUB open)
om.add_lin_constraint('GUB', ones(1, nl), nl - useropt.GUB, [], {'Z'});

%% ========== Objective modification: reactive power generation quadratic cost ==========
% Even under DC model, Qg variables exist in MATPOWER formulation; we add a quadratic penalty on Qg.
idx = om.get_idx();
ng_om = idx.iN.Pg - idx.i1.Pg + 1;

% Build placeholder c_Q vector matching ng
c_Q = zeros(ng_om, 1);
% If user supplies fewer/more, map first entries; remaining kept at last provided value.
user_cQ = [gen_QCOST_1; gen_QCOST_2; gen_QCOST_3];
if ng_om <= numel(user_cQ)
    c_Q = user_cQ(1:ng_om);
else
    c_Q(1:numel(user_cQ)) = user_cQ;
    c_Q(numel(user_cQ)+1:end) = user_cQ(end);
end
Q_mat = sparse(1:ng_om, 1:ng_om, 2*c_Q, ng_om, ng_om);
om = om.add_quad_cost('reactive_support_cost', Q_mat, [], 0, {'Qg'});

%% ========== Constraint modification: CO2 emission cap (linear constraint on Pg) ==========
% Emission factors in tCO2/MWh; cap in tCO2/h.
% Constraint: sum_i e_i * Pg_i(MW) <= cap  ==> (e*baseMVA)'*Pg_pu <= cap

ef = zeros(ng_om, 1);
user_ef = [gen_CO2_EF_1; gen_CO2_EF_2; gen_CO2_EF_3];
if ng_om <= numel(user_ef)
    ef = user_ef(1:ng_om);
else
    ef(1:numel(user_ef)) = user_ef;
    ef(numel(user_ef)+1:end) = user_ef(end);
end

nv = om.var.N;
Aem = sparse(1, nv);
iPg = idx.i1.Pg : idx.iN.Pg;
Aem(1, iPg) = (ef(:)' * baseMVA);

om.add_lin_constraint('emission_cap_CO2', Aem, -Inf, system_CO2_cap_t_per_h);

%% ========== Solve ==========
opt = mpopt2qpopt(mpopt, om.problem_type());
[x, fval, eflag, output, lambda] = om.solve(opt);

% Build results in internal numbering, then convert to external
results = mpc_int;
results.success = (eflag > 0);
results.f = fval;

% assign solution back to results struct (best-effort)
idx = om.get_idx();
if results.success
    if isfield(idx.i1, 'Va')
        results.bus(:, VA) = x(idx.i1.Va:idx.iN.Va) * 180/pi;
    end
    if isfield(idx.i1, 'Vm')
        results.bus(:, VM) = x(idx.i1.Vm:idx.iN.Vm);
    end
    results.gen(:, PG) = x(idx.i1.Pg:idx.iN.Pg) * baseMVA;
    if isfield(idx.i1, 'Qg')
        results.gen(:, QG) = x(idx.i1.Qg:idx.iN.Qg) * baseMVA;
    end
end

results = int2ext(results, mpopt);
results.om = om;
results.output = output;
results.lambda = lambda;

end

function [i, ok] = find_branch(mpc, fbus, tbus)
%FIND_BRANCH Find first branch index connecting fbus-tbus (either direction).
% Works on external bus numbering of the provided MPC.

define_constants;
br = mpc.branch;
ix = find((br(:, F_BUS) == fbus & br(:, T_BUS) == tbus) | (br(:, F_BUS) == tbus & br(:, T_BUS) == fbus), 1, 'first');
ok = ~isempty(ix);
if ok
    i = ix;
else
    i = NaN;
end
end

function results = opf_case145(branch_RATE_A_59_91, branch_BR_X_57_49, unc_BUSES_EXT, unc_DELTA_MW)
%OPF_CASE145  DCOPF on case145 with scenario-driven parameter changes and PTDF-based robust line limits (box uncertainty).
%
% Inputs (placeholders for post-modification values consistent with scenario directions):
%   branch_RATE_A_59_91   - new RATE_A for branch (59 -> 91), must be >= original
%   branch_BR_X_57_49     - new BR_X   for branch (57 -> 49), must be >= original
%   unc_BUSES_EXT         - column vector of external bus numbers with uncertain injection deviations
%   unc_DELTA_MW          - column vector of same length, box half-widths (MW) for each uncertain bus
%
% Output:
%   results - MATPOWER results struct (external indexing)

define_constants;

%% Load base case
mpc0 = loadcase('case145');
mpc  = mpc0;

%% Validate inputs
if nargin < 4
    error('opf_case145 requires 4 inputs: branch_RATE_A_59_91, branch_BR_X_57_49, unc_BUSES_EXT, unc_DELTA_MW');
end
if isempty(unc_BUSES_EXT) || isempty(unc_DELTA_MW)
    error('unc_BUSES_EXT and unc_DELTA_MW must be non-empty for the robust constraint.');
end
unc_BUSES_EXT = unc_BUSES_EXT(:);
unc_DELTA_MW  = unc_DELTA_MW(:);
if numel(unc_BUSES_EXT) ~= numel(unc_DELTA_MW)
    error('unc_BUSES_EXT and unc_DELTA_MW must have the same length.');
end

%% Scenario-driven parameter modifications with direction asserts
% 1) Increase RATE_A on branch 59-91
k_59_91 = find(mpc.branch(:, F_BUS) == 59 & mpc.branch(:, T_BUS) == 91, 1, 'first');
if isempty(k_59_91)
    error('Branch (59 -> 91) not found in case145.');
end
orig_RATE_A_59_91 = mpc.branch(k_59_91, RATE_A);
assert(branch_RATE_A_59_91 >= orig_RATE_A_59_91, 'Parameter must increase');
mpc.branch(k_59_91, RATE_A) = branch_RATE_A_59_91;

% 2) Increase BR_X on branch 57-49
k_57_49 = find(mpc.branch(:, F_BUS) == 57 & mpc.branch(:, T_BUS) == 49, 1, 'first');
if isempty(k_57_49)
    error('Branch (57 -> 49) not found in case145.');
end
orig_BR_X_57_49 = mpc.branch(k_57_49, BR_X);
assert(branch_BR_X_57_49 >= orig_BR_X_57_49, 'Parameter must increase');
mpc.branch(k_57_49, BR_X) = branch_BR_X_57_49;

%% DCOPF + solver settings
mpopt = mpoption('verbose', 1, 'out.all', 0);
mpopt = mpoption(mpopt, 'model', 'DC');
mpopt = mpoption(mpopt, 'opf.dc.solver', 'MIPS');
mpopt = mpoption(mpopt, 'opf.violation', 1e-7);

%% Robust OPF structural modification: PTDF-based robust line limits under box uncertainty
% Use internal indexing for PTDF and OM model construction
mpc_i   = ext2int(mpc);
baseMVA = mpc_i.baseMVA;
bus     = mpc_i.bus;
branch  = mpc_i.branch;
gen     = mpc_i.gen;

nb = size(bus, 1);
nl = size(branch, 1);
ng = size(gen, 1);

% Standardize RATE_A: replace zeros to avoid degenerate constraints
rateA = branch(:, RATE_A);
if all(rateA == 0)
    branch(:, RATE_A) = 250;      % default placeholder-like large finite
else
    branch(rateA == 0, RATE_A) = 1e4;
end
mpc_i.branch = branch;

% PTDF (nl x nb)
PTDF = makePTDF(baseMVA, bus, branch);

% Generator-to-bus incidence Cg (nb x ng)
Cg = sparse(gen(:, GEN_BUS), (1:ng)', 1, nb, ng);

% Nominal demands (p.u.)
Pd = bus(:, PD) / baseMVA;

% Map uncertain buses (external) to internal bus indices
mpc_map = ext2int(mpc); % mapping based on modified case
unc_buses_int = zeros(size(unc_BUSES_EXT));
for k = 1:numel(unc_BUSES_EXT)
    bi = find(mpc_map.bus(:, BUS_I) == unc_BUSES_EXT(k), 1);
    if isempty(bi)
        error('Uncertain bus ext #%d not found after ext2int.', unc_BUSES_EXT(k));
    end
    unc_buses_int(k) = bi;
end

Delta_pu = unc_DELTA_MW / baseMVA;

% Worst-case deviation margin for each line (p.u.)
PTDF_U = PTDF(:, unc_buses_int);      % nl x m
worst  = abs(PTDF_U) * abs(Delta_pu); % nl x 1

Fmax = branch(:, RATE_A) / baseMVA;   % p.u.

% Build OPF model
om = opf_setup(mpc_i, mpopt);
idx = om.var.idx;
i1 = idx.i1.Pg;
iN = idx.iN.Pg;
nv = om.var.N;
if (iN - i1 + 1) ~= ng
    error('Pg dimension mismatch.');
end

% Add robust linear constraints for each in-service, limited line:
%   mu_f_l <= Fmax_l - worst_l
%  -mu_f_l <= Fmax_l - worst_l
% where mu_f = PTDF*(Cg*Pg - Pd)
Arows = [];
lvec  = [];
uvec  = [];

for ell = 1:nl
    if branch(ell, BR_STATUS) == 0
        continue;
    end
    if Fmax(ell) <= 0
        continue;
    end

    margin = Fmax(ell) - worst(ell);
    a_pg   = PTDF(ell,:) * Cg;       % 1 x ng
    const  = PTDF(ell,:) * (-Pd);    % scalar

    rhs_pos = margin - const;        % for +mu_f
    rhs_neg = margin + const;        % for -mu_f

    % +mu_f <= margin
    Arows(end+1,:) =  a_pg; %#ok<SAGROW>
    lvec(end+1,1)  = -Inf; %#ok<SAGROW>
    uvec(end+1,1)  =  rhs_pos; %#ok<SAGROW>

    % -mu_f <= margin
    Arows(end+1,:) = -a_pg; %#ok<SAGROW>
    lvec(end+1,1)  = -Inf; %#ok<SAGROW>
    uvec(end+1,1)  =  rhs_neg; %#ok<SAGROW>
end

if ~isempty(Arows)
    A = sparse(Arows);
    Afull = sparse(size(A,1), nv);
    Afull(:, i1:iN) = A;
    om = om.add_lin_constraint('ROBUST_LINE_LIMITS_BOX', Afull, lvec, uvec);
end

%% Solve
try
    [res_i, success] = opf_execute(om, mpopt);
catch
    [res_i, success] = opf_execute(om, mpc_i, mpopt);
end
if ~success
    error('Robust DCOPF failed (likely infeasible under given uncertainty bounds).');
end

%% Return results in external numbering
results = int2ext(res_i, mpc);

end

function results = opf_case300(gen_QMIN_47, bus_PD_279, bus_QD_218)
%OPF_CASE300  DCOPF on case300 with scenario parameter modifications and angle-difference penalty.

define_constants;

%% load base case
mpc = loadcase('case300');

%% --- Scenario-driven parameter modifications with direction asserts ---
% 1) Generator at bus 47, QMIN decreases (allow deeper reactive absorption)
ig47 = find(mpc.gen(:, GEN_BUS) == 47);
assert(~isempty(ig47), 'No generator found at bus 47');
% apply to all gens at bus 47
old_QMIN_47 = mpc.gen(ig47, QMIN);
assert(all(gen_QMIN_47 <= old_QMIN_47), 'Parameter must decrease');
mpc.gen(ig47, QMIN) = gen_QMIN_47;

% 2) Bus 279, PD increases (summer AC peak load)
i279 = find(mpc.bus(:, BUS_I) == 279);
assert(~isempty(i279), 'Bus 279 not found');
old_PD_279 = mpc.bus(i279, PD);
assert(bus_PD_279 >= old_PD_279, 'Parameter must increase');
mpc.bus(i279, PD) = bus_PD_279;

% 3) Bus 218, QD increases (reactive demand increases under high temperatures)
i218 = find(mpc.bus(:, BUS_I) == 218);
assert(~isempty(i218), 'Bus 218 not found');
old_QD_218 = mpc.bus(i218, QD);
assert(bus_QD_218 >= old_QD_218, 'Parameter must increase');
mpc.bus(i218, QD) = bus_QD_218;

%% --- Solver settings ---
mpopt = mpoption('verbose', 1, 'out.all', 0);
mpopt = mpoption(mpopt, 'model', 'DC');
mpopt = mpoption(mpopt, 'opf.dc.solver', 'MIPS');
mpopt = mpoption(mpopt, 'opf.violation', 1e-8);

%% --- Structural modification: add quadratic penalty on angle differences ---
beta = 10;

% build OPF model
om = opf_setup(mpc, mpopt);

% incidence matrix E for in-service branches only
nb = size(mpc.bus, 1);
in_service = mpc.branch(:, BR_STATUS) ~= 0;
br = mpc.branch(in_service, :);
nl = size(br, 1);
f = br(:, F_BUS);
t = br(:, T_BUS);

% Note: in MATPOWER, F_BUS/T_BUS store bus numbers, which in case300 are 1..nb
E = sparse(1:nl, f,  1, nl, nb) + sparse(1:nl, t, -1, nl, nb);

% Quadratic cost on Va: beta * ||E*Va||^2 = beta * Va' * (E'*E) * Va
% MATPOWER quadratic form is 0.5 * x'Qx, so Q = 2*beta*(E'*E)
Q_va = 2 * beta * (E' * E);
om = om.add_quad_cost('ang_diff_pen', Q_va, [], 0, {'Va'});

%% solve
[x, fval, eflag, output, lambda] = om.solve();

%% pack results similar to MATPOWER
idx_i1 = om.var.idx.i1;
idx_iN = om.var.idx.iN;

results = mpc;

% Va exists in DC model; Vm is typically fixed in DC but may still be present in OM
if isfield(idx_i1, 'Va') && isfield(idx_iN, 'Va')
    Va_solution = x(idx_i1.Va:idx_iN.Va);
    results.bus(:, VA) = Va_solution * 180/pi;
end

if isfield(idx_i1, 'Pg') && isfield(idx_iN, 'Pg')
    Pg_solution = x(idx_i1.Pg:idx_iN.Pg);
    results.gen(:, PG) = Pg_solution;
end

% If Qg exists in the model (depends on formulation), copy it; otherwise leave as-is
if isfield(idx_i1, 'Qg') && isfield(idx_iN, 'Qg')
    Qg_solution = x(idx_i1.Qg:idx_iN.Qg);
    results.gen(:, QG) = Qg_solution;
end

results.f = fval;
results.success = (eflag > 0);
results.om = om;
results.raw = struct('x', x, 'output', output, 'eflag', eflag, 'lambda', lambda);

end

function results = opf_case33mg(bus_PD_8, bus_QD_19, bus_BS_6)
%OPF_CASE33MG  DCOTS + PTDF box-robust line limits with scenario-driven parameter changes.

define_constants;

%% load case
mpc0 = loadcase('case33mg');
mpc  = mpc0;

%% solver/options
mpopt = mpoption('verbose', 1, 'out.all', 0);
mpopt = mpoption(mpopt, 'model', 'DC');
mpopt = mpoption(mpopt, 'opf.dc.solver', 'MIPS');
mpopt = mpoption(mpopt, 'opf.violation', 1e-8);

%% ===================== scenario-driven modifications (with asserts) =====================
% Bus 8 PD: Set zero (disable noncritical load)
old_PD_8 = mpc.bus(mpc.bus(:, BUS_I) == 8, PD);
assert(~isempty(old_PD_8), 'Bus 8 not found in case.');
assert(bus_PD_8 == 0, 'Parameter must be set to zero');
mpc.bus(mpc.bus(:, BUS_I) == 8, PD) = bus_PD_8;

% Bus 19 QD: Set zero (disable noncritical reactive load)
old_QD_19 = mpc.bus(mpc.bus(:, BUS_I) == 19, QD);
assert(~isempty(old_QD_19), 'Bus 19 not found in case.');
assert(bus_QD_19 == 0, 'Parameter must be set to zero');
mpc.bus(mpc.bus(:, BUS_I) == 19, QD) = bus_QD_19;

% Bus 6 BS: Increase (commissioned shunt/reactive devices)
old_BS_6 = mpc.bus(mpc.bus(:, BUS_I) == 6, BS);
assert(~isempty(old_BS_6), 'Bus 6 not found in case.');
assert(bus_BS_6 >= old_BS_6, 'Parameter must increase');
mpc.bus(mpc.bus(:, BUS_I) == 6, BS) = bus_BS_6;

%% ===================== standardize RATE_A (avoid 0 limits) =====================
rateA = mpc.branch(:, RATE_A);
if all(rateA == 0)
    mpc.branch(:, RATE_A) = 250;
else
    mpc.branch(rateA == 0, RATE_A) = 1e4;
end

%% ===================== build DCOTS model (ext2int + OM) =====================
useropt = struct();
useropt.M   = 1e5;      % big-M
useropt.GUB = 4;        % max number of opened lines

mpc_i = ext2int(mpc, mpopt);
om    = opf_setup(mpc_i, mpopt);

[baseMVA, bus, gen, branch] = deal(mpc_i.baseMVA, mpc_i.bus, mpc_i.gen, mpc_i.branch);
[nb, ng, nl] = deal(size(bus,1), size(gen,1), size(branch,1));

% relax original Pmis bounds (template style)
try
    om.set_params('lin', 'Pmis', {'l', 'u'}, {-Inf(om.getN('lin','Pmis'),1), Inf(om.getN('lin','Pmis'),1)});
catch
    % if name differs across versions, ignore
end

% add variables: Pf (continuous) and Z (binary)
om.add_var('Pf', nl, zeros(nl,1));
om.add_var('Z',  nl, ones(nl,1), [], [], 'B');

% build DC matrices
[B, Bf, Pbusinj, Pfinj] = makeBdc(baseMVA, bus, branch);
f = branch(:, F_BUS);
t = branch(:, T_BUS);
Cft = sparse([(1:nl)'; (1:nl)'], [f; t], [ones(nl,1); -ones(nl,1)], nl, nb);
neg_Cg = sparse(gen(:, GEN_BUS), 1:ng, -1, nb, ng);
A = [Cft' neg_Cg];
b = -(bus(:, PD) + bus(:, GS)) / baseMVA - Pbusinj;

Il  = speye(nl);
rhs = useropt.M * ones(nl, 1);

% branch capacity terms
il = find(branch(:, RATE_A) ~= 0 & branch(:, RATE_A) < 1e10);
Pmax = inf(nl,1);
Pmin = inf(nl,1);
if ~isempty(il)
    Pmax(il) = branch(il, RATE_A) / baseMVA - Pfinj(il);
    Pmin(il) = branch(il, RATE_A) / baseMVA + Pfinj(il);
end

% add OTS constraints
om.add_lin_constraint('Pfl',   [Il,  diag(Pmin)], zeros(nl,1), [], {'Pf','Z'});
om.add_lin_constraint('Pfu',   [Il, -diag(Pmax)], [], zeros(nl,1), {'Pf','Z'});
om.add_lin_constraint('Pfmis', A, b, b, {'Pf','Pg'});
om.add_lin_constraint('Ml',    [Bf, -Il, -useropt.M*Il], -rhs, [], {'Va','Pf','Z'});
om.add_lin_constraint('Mu',    [Bf, -Il,  useropt.M*Il], [], rhs, {'Va','Pf','Z'});
om.add_lin_constraint('GUB',   ones(1,nl), nl-useropt.GUB, [], {'Z'});

%% ===================== add PTDF box-robust line limits (structural add-on) =====================
% uncertainty set: choose two representative uncertain injection sources
% (placeholders are not requested for these; kept as internal demo constants)
unc_buses_ext = [6; 19];
Delta_MW      = [10; 10];

% PTDF on internal data
PTDF = makePTDF(baseMVA, bus, branch);        % nl x nb
Cg   = sparse(gen(:, GEN_BUS), (1:ng)', 1, nb, ng);
Pd   = bus(:, PD) / baseMVA;

% map ext uncertain buses to internal indices using original case mapping
mpc_map = ext2int(mpc, mpopt);
unc_buses_int = zeros(size(unc_buses_ext));
for k = 1:numel(unc_buses_ext)
    bi = find(mpc_map.bus(:, BUS_I) == unc_buses_ext(k), 1);
    if isempty(bi)
        error('Uncertain bus ext #%d not found after ext2int mapping.', unc_buses_ext(k));
    end
    unc_buses_int(k) = bi;
end
Delta_pu = Delta_MW(:) / baseMVA;
PTDF_U   = PTDF(:, unc_buses_int);
worst    = abs(PTDF_U) * Delta_pu;            % nl x 1
Fmax     = branch(:, RATE_A) / baseMVA;       % nl x 1

% build constraints on Pg variables only
idx = om.var.idx;
i1 = idx.i1.Pg;
iN = idx.iN.Pg;
nv = om.var.N;
if (iN - i1 + 1) ~= ng
    error('Pg dimension mismatch.');
end

Arows = [];
lvec  = [];
uvec  = [];

for ell = 1:nl
    if branch(ell, BR_STATUS) == 0
        continue;
    end
    if Fmax(ell) <= 0
        continue;
    end
    margin = Fmax(ell) - worst(ell);
    a_pg   = PTDF(ell,:) * Cg;     % 1 x ng
    const  = PTDF(ell,:) * (-Pd);  % scalar

    rhs_pos = margin - const;
    rhs_neg = margin + const;

    Arows(end+1,:) =  a_pg; %#ok<AGROW>
    lvec(end+1,1)  = -Inf; %#ok<AGROW>
    uvec(end+1,1)  =  rhs_pos; %#ok<AGROW>

    Arows(end+1,:) = -a_pg; %#ok<AGROW>
    lvec(end+1,1)  = -Inf; %#ok<AGROW>
    uvec(end+1,1)  =  rhs_neg; %#ok<AGROW>
end

if ~isempty(Arows)
    A = sparse(Arows);
    Afull = sparse(size(A,1), nv);
    Afull(:, i1:iN) = A;
    om = om.add_lin_constraint('ROBUST_LINE_LIMITS_BOX', Afull, lvec, uvec);
end

%% ===================== solve =====================
try
    [res_i, success] = opf_execute(om, mpopt);
catch
    [res_i, success] = opf_execute(om, mpc_i, mpopt);
end
if ~success
    error('DCOTS + robust constraints failed (likely infeasible).');
end

results = int2ext(res_i, mpc);

end

function mdo = opf_case39(bus_PD_16, bus_QD_31, branch_RATE_A_32_29)
