% find the specific branch 32 -> 29 (orientation-specific)
br_idx_32_29 = find(mpc.branch(:, F_BUS) == 32 & mpc.branch(:, T_BUS) == 29, 1, 'first');
assert(~isempty(br_idx_32_29), 'Branch 32->29 not found in case39.');
old_branch_RATE_A_32_29 = mpc.branch(br_idx_32_29, RATE_A);

%% scenario-driven modifications with direction validation
