mpc.bus(16, PD) = bus_PD_16;

assert(bus_QD_31 <= old_bus_QD_31, 'Parameter must decrease');
mpc.bus(31, QD) = bus_QD_31;

% Corridor maintenance: branch long-term rating decreases
assert(branch_RATE_A_32_29 <= old_branch_RATE_A_32_29, 'Parameter must decrease');
