%% 10) Build MOST data model
mdi = loadmd(mpc, nt, xgd, sd, [], profiles);

%% 11) Add quadratic reactive power generation cost (objective modification template)
% MOST will solve a sequence of OPFs/UC with an internal OM; we attach
% userfcn hooks that add the quadratic cost term to each OPF model.
% Use c_Q as provided in the structural modification template.
c_Q = [100; 15; 20];
